function usarEmpresasDoCadastro(lista) {
  if (!Array.isArray(lista) || lista.length === 0) return;
  if (lista.length === EMPRESAS.length && lista.every((x, i) => x === EMPRESAS[i])) return;
  EMPRESAS.splice(0, EMPRESAS.length, ...lista);
}
