// Valores de desconto de uma ausência conforme os flags do tipo (salário/VT/VR/horas). Retorna null
// quando o tipo NÃO desconta nada. Salário = salarioBase ÷ 30 × dias informados (corridos); VT/VR =
// valor/dia × dias ÚTEIS (Seg–Sex, fora feriados); HORAS = (valor do dia ÷ jornada) × horas ausentes.
// Tudo do CADASTRO/CONFIG, nunca hardcoded. Sem salário/VT/VR ativo, aquele item entra como 0 (sem erro).
// Precisão: valor do dia e valor da hora ficam SEM arredondar; só cada linha e o total viram 2 casas
// (ex.: 1980 ÷ 31 dias de agosto = 63,87 → 63,87 ÷ 9,5 = 6,723259… × 3h = 20,17, e não 6,72 × 3 = 20,16).
function descontoAusenciaValores(f, a, config, tipos) {
  if (!f || !a) return null;
  const ts = tipos || tiposAusencia(config);
  const tipo = tipoAusenciaDe(a.tipo, ts);
  const flags = descontoAusencia(a, ts, config);
  if (!flags.salario && !flags.vt && !flags.vr && !flags.horas) return null;
  const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;
  const dias = atestadoDias(a);                                   // salário: dias informados (corridos)
  let diasUteis = (a.dataInicio && a.dataFim) ? contarDiasUteis(a.dataInicio, a.dataFim, feriadosDe(config)) : dias;
  if (diasUteis > dias) diasUteis = dias;                         // úteis nunca passam do total informado
  const salMensal = num(f.salarioBase);
  const vtAtivo = !!f.beneficios?.vt?.ativo;
  const vrAtivo = !!f.beneficios?.vr?.ativo;
  const vtDia = (flags.vt && vtAtivo) ? num(calcVTDetalhe(f, config)?.valorDiario) : 0;   // VT/dia do cadastro
  const vrDia = (flags.vr && vrAtivo) ? num(config?.vrDiario) : 0;                        // VR/dia do config
  const j = jornadaDe(config);
  const valorDia = valorDiaSalario(salMensal, config, a.dataInicio);   // precisão cheia (÷ dias do mês da falta)
  const valorHora = j.horas > 0 ? valorDia / j.horas : 0;         // precisão cheia
  const horasAusentes = flags.horas ? horasAusentesDe(a, j, tipo) : 0;
  const descSalario = flags.salario ? r2(valorDia * dias) : 0;
  const descVT = r2(vtDia * diasUteis);
  const descVR = r2(vrDia * diasUteis);
  const descHoras = r2(valorHora * horasAusentes);
  return {
    flags, dias, diasUteis, salMensal, vtDia, vrDia, vtAtivo, vrAtivo,
    jornadaHoras: j.horas, valorDia, valorHora, horasAusentes,
    descSalario, descVT, descVR, descHoras, total: r2(descSalario + descVT + descVR + descHoras),
    semSalario: (flags.salario || flags.horas) && salMensal <= 0, semVT: flags.vt && !vtAtivo, semVR: flags.vr && !vrAtivo,
    semHorario: flags.horas && horasAusentes <= 0,
  };
}
// Competência seguinte (YYYY-MM + 1 mês) — para lançar quando o mês da falta já está pago.
const proximaComp = (c) => { const p = (c || "").split("-").map(Number); if (p.length < 2) return c; const dt = new Date(p[0], p[1], 1); return `${dt.getFullYear()}-${String(dt.getMonth() + 1).padStart(2, "0")}`; };
// Meses a que uma linha de desconto de falta pode pertencer: o mês REAL da ausência (compFalta) e a
// competência em que ela foi LANÇADA. Os dois diferem quando a folha do mês já estava paga e o
// desconto foi empurrado para a competência seguinte. A rescisão do mês reconhece os dois — senão a
// falta some da tela do desligamento. Registros antigos (sem compFalta) caem na competência.
const mesesDaFalta = (p) => [p.compFalta, p.competencia].filter(Boolean);
// Uma linha de desconto por ausência só VALE se o benefício dela continuar ativo no cadastro do
// funcionário. Quem não recebe VR não pode ter desconto de VR — nem mesmo numa linha antiga, que
// foi lançada quando o benefício ainda existia e ficou parada no histórico. O CADASTRO é a fonte
// única: desligou o benefício, o desconto dele some de todas as contas (folha, rescisão, líquido).
// A linha não é apagada (fica auditável), só deixa de contar.
const faltaLinhaVale = (p, f) => {
  if (!f || !p) return true;
  if (p.categoria === "VT") return !!f.beneficios?.vt?.ativo;
  if (p.categoria === "VR") return !!f.beneficios?.vr?.ativo;
  return true;
};
// Dias do SALDO DE SALÁRIO na rescisão: dias trabalhados no mês até o desligamento, INCLUINDO o próprio
// dia (dias = dia do mês, nunca dia+1); conta do dia 1 do mês, ou da admissão se ela cair no mesmo mês.
// Nunca conta dias posteriores ao desligamento. Se descontarDia = true, o dia do desligamento não é pago
// (dias − 1). Nunca negativo (dia 1 com descontarDia → 0). Função PURA (usada na tela e nos testes).
function saldoDiasSalario(dataDesligamento, dataAdmissao, descontarDia) {
  const b = parseDate(dataDesligamento); if (!b) return 0;
  const adm = parseDate(dataAdmissao);
  const ini = (adm && adm.getFullYear() === b.getFullYear() && adm.getMonth() === b.getMonth() && adm <= b) ? adm : new Date(b.getFullYear(), b.getMonth(), 1);
  return Math.max(diasEntre(ini, b) + 1 - (descontarDia ? 1 : 0), 0);
}
// Valor monetário em vários formatos: BR ("1.980,00"), US ("1,980.00") e número puro.
// Fica aqui, junto dos helpers de cálculo, porque é usado pelas importações E é conferido
// pela Conferência de Cálculos.
function parseMoedaFlex(v) {
  if (v == null || v === "") return 0;
  if (typeof v === "number") return v;
  const t = String(v).replace(/[^\d.,-]/g, ""); if (!t) return 0;
  const c = t.lastIndexOf(","), d = t.lastIndexOf(".");
  let s = t;
  if (c > -1 && d > -1) s = c > d ? t.replace(/\./g, "").replace(",", ".") : t.replace(/,/g, "");
  else if (c > -1) s = t.replace(/\./g, "").replace(",", ".");
  return parseFloat(s) || 0;
}

/* ── RELAÇÃO GERAL DOS LÍQUIDOS (PDF da contabilidade) ───────────────────────────
   Layout do escritório: cabeçalho com Empresa / CNPJ / Cálculo / Competência e, na
   tabela, uma linha por empregado: CÓDIGO · NOME · IDENTIDADE (RG) · VALOR. No rodapé,
   "Total da Empresa" — que serve de conferência: se a soma das linhas não bater com ele,
   alguma linha se perdeu na leitura.
   Ex.: "12 ANDERSON KENJI TAKEDA 21.405.317 800,00"
   Funciona com o texto do PDF digital e também com o texto que sai do OCR. */
const RE_LIQ_VALOR = "\\d{1,3}(?:\\.\\d{3})*,\\d{2}";
function parseRelacaoLiquidos(texto) {
  const linhas = String(texto || "").split(/\r?\n/).map((l) => l.replace(/\s+/g, " ").trim()).filter(Boolean);
  const cab = { empresa: "", cnpj: "", calculo: "", competencia: "", total: 0, emissao: "" };
  const pega = (re, l) => { const m = re.exec(l); return m ? m[1].trim() : ""; };
  linhas.forEach((l) => {
    cab.empresa = cab.empresa || pega(/empresa\s*:\s*(.+?)(?:\s+p[áa]gina\s*:|\s+cnpj\s*:|$)/i, l);
    cab.cnpj = cab.cnpj || pega(/cnpj\s*:\s*([\d./-]{14,})/i, l);
    cab.calculo = cab.calculo || pega(/c[áa]lculo\s*:\s*(.+?)(?:\s+horas\s*:|\s+emiss[ãa]o\s*:|\s+compet|$)/i, l);
    cab.emissao = cab.emissao || pega(/emiss[ãa]o\s*:\s*(\d{2}\/\d{2}\/\d{4})/i, l);
    const c = /compet[êe]ncia\s*:\s*(\d{2})\/(\d{4})/i.exec(l);
    if (c && !cab.competencia) cab.competencia = `${c[2]}-${c[1]}`;
    const t = new RegExp(`total\\s+da\\s+empresa\\s*:?\\s*(${RE_LIQ_VALOR})`, "i").exec(l);
    if (t) cab.total = parseMoedaFlex(t[1]);
  });
  // Linha com identidade (o normal) e linha sem identidade (quando o campo vem vazio).
  const comRG = new RegExp(`^(\\d{1,6})\\s+(.+?)\\s+([\\dxX][\\dxX./-]{3,})\\s+(${RE_LIQ_VALOR})$`);
  const semRG = new RegExp(`^(\\d{1,6})\\s+(.+?)\\s+(${RE_LIQ_VALOR})$`);
  const itens = [];
  linhas.forEach((l) => {
    if (/total\s+da\s+empresa|empregados\s*:|estagi[áa]rios\s*:|p[áa]gina\s*:/i.test(l)) return;
    let m = comRG.exec(l);
    if (m && /[A-Za-zÀ-ú]{3}/.test(m[2])) { itens.push({ codigo: m[1], nome: m[2].trim(), identidade: m[3], valor: parseMoedaFlex(m[4]) }); return; }
    m = semRG.exec(l);
    if (m && /[A-Za-zÀ-ú]{3}/.test(m[2])) itens.push({ codigo: m[1], nome: m[2].trim(), identidade: "", valor: parseMoedaFlex(m[3]) });
  });
  const soma = arred2(itens.reduce((s, i) => s + i.valor, 0));
  // "Adiantamento"/"Vale" → coluna de adiantamento; qualquer outro cálculo → total do mês.
  const ehAdiantamento = /adiant|vale/i.test(cab.calculo || "");
  return { ...cab, itens, soma, ehAdiantamento, confere: cab.total > 0 ? Math.abs(soma - cab.total) < 0.005 : null };
}

/* ── QUEM É ESSA LINHA? (importação da folha) ────────────────────────────────────
   Ordem das chaves: CÓDIGO > CPF > IDENTIDADE (RG) > nome normalizado.
   O código MANDA: se o código da linha existe em algum cadastro, é aquele funcionário,
   ainda que o nome pareça de outra pessoa. A queda para as outras chaves só acontece
   quando aquele código ainda não está em cadastro nenhum — que é o caso da primeira
   importação, quando ninguém tem código gravado ainda (aí o código é gravado depois). */
function casarFuncionario(funcs, { matricula, cpf, identidade, nome }) {
  const lista = funcs || [];
  const eqTxt = (a, b) => String(a || "").trim().toLowerCase() === String(b || "").trim().toLowerCase();
  if (matricula) { const f = lista.find((x) => String(x.matricula || "").trim() && eqTxt(x.matricula, matricula)); if (f) return { func: f, via: "Código" }; }
  const cpfD = soDigitos(cpf);
  if (cpfD) { const f = lista.find((x) => soDigitos(x.cpf) && soDigitos(x.cpf) === cpfD); if (f) return { func: f, via: "CPF" }; }
  const rgD = soDigitos(identidade);
  if (rgD) { const f = lista.find((x) => soDigitos(x.rg) && soDigitos(x.rg) === rgD); if (f) return { func: f, via: "Identidade" }; }
  if (nome) { const f = lista.find((x) => normalizarTexto(x.nome) === normalizarTexto(nome)); if (f) return { func: f, via: "Nome" }; }
  return { func: null, via: "" };
}

/* ---------------------- Relatórios / Exportação (inalterado) ------- */
function csvCell(v) { const s = v == null ? "" : String(v); return /[",;\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; }
function baixarCSV(nome, headers, rows) {
  const linhas = [headers.map(csvCell).join(";"), ...rows.map((r) => r.map(csvCell).join(";"))];
  const blob = new Blob(["\uFEFF" + linhas.join("\n")], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `${nome}.csv`; a.click(); URL.revokeObjectURL(url);
}
// Exporta\u00E7\u00E3o Excel real (.xlsx) via SheetJS.
function baixarXLSX(nome, headers, rows) {
  const ws = XLSX.utils.aoa_to_sheet([headers, ...rows]);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Dados");
  XLSX.writeFile(wb, `${nome}.xlsx`);
}
// Excel com VÁRIAS abas: abas = [{ nome, headers, rows }]. Usado na Folha de Repasse, que
// devolve TOTAL e ADIANTAMENTO no mesmo arquivo (é assim que a contabilidade recebe).
function baixarXLSXAbas(nome, abas) {
  const wb = XLSX.utils.book_new();
  abas.forEach((a) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([a.headers, ...a.rows]), String(a.nome).slice(0, 31)));
  XLSX.writeFile(wb, `${nome}.xlsx`);
}

/* ==================================================================
   IMPORTA\u00C7\u00C3O INTELIGENTE \u2014 reconhece colunas por sin\u00F4nimos, converte
   valores e detecta duplicidades. N\u00E3o exige editar a planilha.
   ================================================================== */
const normalizarTexto = (s) => String(s ?? "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036F]/g, "").replace(/[^a-z0-9]+/g, " ").trim();
// ---- Formata\u00E7\u00E3o (m\u00E1scara visual) a partir de d\u00EDgitos armazenados ----
const fmtCPF = (v) => { const d = soDigitos(v).slice(0, 11); return d.replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d{1,2})$/, "$1-$2"); };
const fmtTelefoneBR = (v) => { const d = soDigitos(v).slice(0, 11); if (!d) return ""; if (d.length <= 10) return d.replace(/(\d{2})(\d)/, "($1) $2").replace(/(\d{4})(\d{1,4})$/, "$1-$2"); return d.replace(/(\d{2})(\d)/, "($1) $2").replace(/(\d{5})(\d{1,4})$/, "$1-$2"); };
const fmtCEP = (v) => { const d = soDigitos(v).slice(0, 8); return d.replace(/(\d{5})(\d{1,3})$/, "$1-$2"); };
const fmtPIS = (v) => { const d = soDigitos(v).slice(0, 11); return d.replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{5})(\d)/, "$1.$2").replace(/(\d{2})(\d{1})$/, "$1-$2"); };
// ---- Separa\u00E7\u00E3o de cargo composto (ex.: "Supervisor Comercial" -> Supervisor + Comercial) ----
function matchDepto(v) {
  const n = normalizarTexto(v); if (!n) return "";
  for (const [dep, toks] of Object.entries(DEPTO_TOKENS)) { if (normalizarTexto(dep) === n || toks.includes(n)) return dep; }
  for (const [dep, toks] of Object.entries(DEPTO_TOKENS)) { if (toks.some((t) => n === t || (t.length > 2 && (n.includes(t) || t.includes(n))))) return dep; }
  return "";
}
function removerTokens(cargo, matched) {
  const set = new Set(normalizarTexto(matched).split(" ").filter(Boolean));
  return String(cargo).split(/\s+/).filter((w) => !set.has(normalizarTexto(w))).join(" ").trim();
}
function separarCargoDepto(cargoRaw, deptoRaw) {
  let departamento = matchDepto(deptoRaw);
  let cargo = String(cargoRaw || "").trim();
  const nCargo = " " + normalizarTexto(cargo) + " ";
  let depFound = "", matched = "";
  for (const [dep, toks] of Object.entries(DEPTO_TOKENS)) {
    for (const t of toks) { if (nCargo.includes(" " + t + " ")) { depFound = dep; matched = t; break; } }
    if (depFound) break;
  }
  if (depFound) { if (!departamento) departamento = depFound; cargo = removerTokens(cargo, matched); }
  const conhecido = matchLista(cargo, CARGOS_LISTA);
  return { cargo: conhecido || cargo, departamento, precisaDepto: !departamento && !!cargo };
}
// Meses por extenso/abreviados \u2014 planilhas de RH costumam trazer "18/jun", "5 de julho".
const MESES_NOME = { jan: 1, fev: 2, mar: 3, abr: 4, mai: 5, jun: 6, jul: 7, ago: 8, set: 9, out: 10, nov: 11, dez: 12 };
// Data em v\u00E1rios formatos: BR (dd/mm/aaaa), ISO (aaaa-mm-dd), serial do Excel e
// dia/m\u00EAs-por-nome ("18/jun", "18-junho-2026"). Sem ano, assume o ano corrente.
function parseDataFlex(v) {
  if (v == null || v === "") return "";
  if (typeof v === "number" && v > 20000 && v < 90000) { const d = new Date(Math.round((v - 25569) * 86400000)); return isNaN(d) ? "" : d.toISOString().slice(0, 10); }
  const s = String(v).trim();
  if (!s || s === "-" || s === "\u2014") return ""; // tra\u00E7o = c\u00E9lula sem informa\u00E7\u00E3o
  let m = s.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{2,4})/);
  if (m) { let yy = m[3]; if (yy.length === 2) yy = (Number(yy) > 50 ? "19" : "20") + yy; return `${yy}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`; }
  m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  // "18/jun", "18 jun 2026", "5 de julho"
  m = s.match(/^(\d{1,2})\s*(?:de\s+)?[\/\-. ]?\s*([A-Za-z\u00C0-\u00FF]{3,})\.?(?:\s*(?:de\s+)?[\/\-. ]?\s*(\d{2,4}))?$/);
  if (m) {
    const mes = MESES_NOME[normalizarTexto(m[2]).slice(0, 3)];
    if (mes) {
      let yy = m[3] || String(new Date().getFullYear());
      if (yy.length === 2) yy = (Number(yy) > 50 ? "19" : "20") + yy;
      return `${yy}-${String(mes).padStart(2, "0")}-${m[1].padStart(2, "0")}`;
    }
  }
  return "";
}
// Hor\u00E1rio em v\u00E1rios formatos: "16:30", "16h30", "16HRS", "12HR", "9h", "1630"
// e a fra\u00E7\u00E3o do dia usada pelo Excel (0,5 = 12:00). Devolve sempre "HH:MM".
function parseHoraFlex(v) {
  if (v == null || v === "") return "";
  const fracao = typeof v === "number" ? v : (/^0[.,]\d+$/.test(String(v).trim()) ? parseFloat(String(v).trim().replace(",", ".")) : NaN);
  if (!isNaN(fracao) && fracao > 0 && fracao < 1) {
    const min = Math.round(fracao * 24 * 60);
    return `${String(Math.floor(min / 60)).padStart(2, "0")}:${String(min % 60).padStart(2, "0")}`;
  }
  const s = String(v).trim();
  if (!s || s === "-" || s === "\u2014") return "";
  const m = s.match(/^(\d{1,2})\s*(?::|h|hrs?|hs)?\s*(\d{2})?/i);
  if (!m) return "";
  const h = Number(m[1]), mi = m[2] ? Number(m[2]) : 0;
  if (h > 23 || mi > 59) return "";
  return `${String(h).padStart(2, "0")}:${String(mi).padStart(2, "0")}`;
}
// Valor monet\u00E1rio: aceita "1.234,56", "1234.56", "R$ 1.980,00", n\u00FAmero puro.
// Ordena por NOME em pt-BR, ignorando acento e maiúscula/minúscula (para listas de pessoas).
const ordNome = (a, b) => (a?.nome || "").localeCompare(b?.nome || "", "pt-BR", { sensitivity: "base" });
// Casa um valor livre com uma lista conhecida (sem acento/caixa). Retorna o item da lista ou "".
function matchLista(v, lista) {
  const n = normalizarTexto(v); if (!n) return "";
  let achou = lista.find((x) => normalizarTexto(x) === n);
  if (achou) return achou;
  achou = lista.find((x) => { const nx = normalizarTexto(x); return nx && (n.includes(nx) || nx.includes(n)); });
  return achou || "";
}
// ---- \u00C1rea de Recrutamento ----
// Descobre a \u00E1rea a partir de textos livres (coluna \u00C1rea, Departamento, Setor, Vaga ou Cargo).
// Retorna "" quando n\u00E3o reconhece \u2014 quem chama decide o fallback (\u00E1rea padr\u00E3o da importa\u00E7\u00E3o).
function inferirArea(...textos) {
  for (const t of textos) {
    const direto = matchLista(t, AREAS_RECRUTAMENTO);
    if (direto) return direto;
  }
  const alvo = " " + textos.map((t) => normalizarTexto(t)).filter(Boolean).join(" ") + " ";
  if (alvo.trim() === "") return "";
  for (const [area, toks] of AREA_TOKENS) {
    if (toks.some((t) => alvo.includes(" " + t + " "))) return area;
  }
  return "";
}
// \u00C1rea efetiva de um candidato j\u00E1 cadastrado: usa o campo pr\u00F3prio; se estiver vazio
// (cadastros antigos, anteriores a este campo), deduz do cargo pretendido.
const areaDe = (c) => c?.area || inferirArea(c?.vaga, c?.cargo) || AREA_PADRAO;
// Auto-mapeamento: para cada campo do CRM, escolhe a melhor coluna da planilha pelos sin\u00F4nimos.
function autoMapear(headers, campos) {
  const nh = headers.map((h) => ({ h, n: normalizarTexto(h) }));
  const usados = new Set(); const mapa = {};
  const pontuar = (campo, n) => {
    let sc = 0;
    [campo.label, ...campo.syn].forEach((syn) => {
      const ns = normalizarTexto(syn); if (!ns) return;
      if (n === ns) sc = Math.max(sc, 100);
      else if (n.startsWith(ns) || ns.startsWith(n)) sc = Math.max(sc, 72);
      else if (n.includes(ns) || ns.includes(n)) sc = Math.max(sc, 55);
    });
    return sc;
  };
  // Duas passadas: primeiro fecha só os nomes EXATOS, depois os aproximados.
  // Sem isso o mapeamento seria guloso e um campo poderia levar a coluna de outro por
  // semelhança — ex.: "Data da entrevista" abocanhando a coluna "Data" (data de cadastro)
  // e deixando a entrevista sem data.
  [100, 55].forEach((minimo) => {
    campos.forEach((campo) => {
      if (mapa[campo.key]) return;
      let melhor = "", score = 0;
      nh.forEach(({ h, n }) => {
        if (usados.has(h) || !n) return;
        const sc = pontuar(campo, n);
        if (sc > score) { score = sc; melhor = h; }
      });
      if (melhor && score >= minimo) { mapa[campo.key] = melhor; usados.add(melhor); }
    });
  });
  campos.forEach((c) => { if (!mapa[c.key]) mapa[c.key] = ""; });
  return mapa;
}
// Texto vindo de planilha: "-" e "—" são preenchimento de célula vazia, não conteúdo.
const limpo = (v) => { const s = String(v ?? "").trim(); return s === "-" || s === "—" ? "" : s; };
const chaveNorm = (key, val) => (key === "email" ? String(val ?? "").trim().toLowerCase() : soDigitos(val));
// Escolhe a aba de origem: prioriza "Planilha 1"/"Planilha1"/"Sheet1"; sen\u00E3o, a primeira aba do arquivo.
function escolherAba(nomes) {
  const alvos = ["planilha1", "planilha 1", "plan1", "sheet1", "dados"];
  const achou = nomes.find((n) => { const nn = normalizarTexto(n); return alvos.includes(nn) || alvos.includes(nn.replace(/ /g, "")); });
  return achou || nomes[0];
}
// L\u00EA a aba escolhida e devolve { headers, linhas, aba, abas } (linhas = objetos por cabe\u00E7alho).
async function lerPlanilha(file) {
  const buf = await file.arrayBuffer();
  const wb = XLSX.read(buf, { type: "array", cellDates: false });
  const aba = escolherAba(wb.SheetNames);
  const ws = wb.Sheets[aba];
  const linhas = XLSX.utils.sheet_to_json(ws, { defval: "", raw: true });
  const headers = XLSX.utils.sheet_to_json(ws, { header: 1, range: 0 })[0] || [];
  return { headers: headers.map((h) => String(h)).filter((h) => h.trim() !== ""), linhas, aba, abas: wb.SheetNames };
}

// ---- Schemas de importa\u00E7\u00E3o (um por m\u00F3dulo) ----
const SCHEMA_FUNC = {
  titulo: "Importar funcion\u00E1rios",
  chave: "funcionarios",
  matchKeys: ["cpf", "telefone"],
  resolveDepto: true,
  campos: [
    { key: "nome", label: "Nome", obrig: true, syn: ["nome completo", "funcionario", "colaborador", "nome do funcionario"] },
    { key: "matricula", label: "Código/Matrícula", syn: ["matricula", "codigo", "cod", "chapa", "cod func", "codigo funcionario", "codigo do funcionario"] },
    { key: "cpf", label: "CPF", syn: ["documento", "cpf mf"] },
    { key: "rg", label: "RG", syn: ["identidade"] },
    { key: "pis", label: "PIS/PASEP", syn: ["pis", "pasep", "nis"] },
    { key: "ctps", label: "CTPS", syn: ["carteira de trabalho", "ctps numero"] },
    { key: "cnh", label: "CNH", syn: ["habilitacao", "carteira de motorista"] },
    { key: "cep", label: "CEP", syn: ["codigo postal"] },
    { key: "cargo", label: "Cargo", syn: ["funcao", "vaga", "posicao", "fun\u00E7ao"] },
    { key: "empresa", label: "Empresa", syn: ["filial", "local", "unidade", "razao social"] },
    { key: "departamento", label: "Departamento", syn: ["depto", "setor", "area"] },
    { key: "salarioBase", label: "Sal\u00E1rio", syn: ["salario base", "remuneracao", "vencimento", "salario"] },
    { key: "dataAdmissao", label: "Data de admiss\u00E3o", syn: ["admissao", "entrada", "data de entrada", "inicio", "data admissao"] },
    { key: "dataRegistro", label: "Data de registro", syn: ["registro", "registrado em"] },
    { key: "tipoContrato", label: "Tipo de contrata\u00E7\u00E3o", syn: ["contrato", "regime", "vinculo", "tipo contrato"] },
    { key: "status", label: "Status", syn: ["situacao"] },
    { key: "email", label: "E-mail", syn: ["email", "e mail"] },
    { key: "telefone", label: "Telefone", syn: ["celular", "whatsapp", "numero", "contato", "fone", "tel"] },
    { key: "dataNascimento", label: "Data de nascimento", syn: ["nascimento", "dt nascimento"] },
    { key: "gestor", label: "Gestor", syn: ["responsavel", "lider"] },
    { key: "dependentes", label: "Dependentes", syn: ["dependente"] },
    { key: "banco", label: "Banco", syn: [] },
    { key: "agencia", label: "Ag\u00EAncia", syn: [] },
    { key: "conta", label: "Conta", syn: ["conta corrente"] },
    { key: "chavePix", label: "Chave PIX", syn: ["pix"] },
    { key: "beneficios", label: "Benef\u00EDcios", syn: ["beneficio", "vt vr"] },
  ],
  transformar: (v) => {
    const empresaM = matchLista(v.empresa, [...EMPRESAS, ...EMPRESAS_ANTIGAS]);
    const empresa = empresaM || (String(v.empresa || "").trim()) || EMPRESAS[0];
    let tipo = mapContrato(matchLista(v.tipoContrato, TIPOS_CONTRATO) || v.tipoContrato || "");
    if (EMPRESAS_SO_ESTAGIO.includes(empresa)) tipo = "Est\u00E1gio";
    const status = matchLista(v.status, STATUS_LIST) || "Ativo";
    // Separa cargo composto (ex.: "Supervisor Comercial" -> cargo Supervisor + depto Comercial).
    const sep = separarCargoDepto(v.cargo, v.departamento);
    const benTxt = normalizarTexto(v.beneficios);
    const dados = {
      nome: String(v.nome || "").trim(), matricula: String(v.matricula || "").trim(), cpf: soDigitos(v.cpf), rg: soDigitos(v.rg), pis: soDigitos(v.pis),
      ctps: soDigitos(v.ctps), cnh: soDigitos(v.cnh), cep: soDigitos(v.cep),
      cargo: sep.cargo, empresa, departamento: sep.departamento, salarioBase: parseMoedaFlex(v.salarioBase),
      dataAdmissao: parseDataFlex(v.dataAdmissao), dataRegistro: parseDataFlex(v.dataRegistro), tipoContrato: tipo, status,
      email: String(v.email || "").trim(), telefone: soDigitos(v.telefone), dataNascimento: parseDataFlex(v.dataNascimento),
      gestor: String(v.gestor || "").trim(), dependentes: soDigitos(v.dependentes) ? Number(soDigitos(v.dependentes)) : 0,
      banco: String(v.banco || "").trim(), agencia: soDigitos(v.agencia), conta: soDigitos(v.conta), chavePix: String(v.chavePix || "").trim(),
    };
    if (benTxt.includes("vt") || benTxt.includes("vale transporte") || benTxt.includes("transporte")) dados._vt = true;
    if (benTxt.includes("vr") || benTxt.includes("vale refeicao") || benTxt.includes("refeicao") || benTxt.includes("alimentacao")) dados._vr = true;
    const erros = [];
    if (!dados.nome) erros.push("Nome obrigat\u00F3rio");
    if (v.empresa && !empresaM) erros.push(`Empresa "${String(v.empresa).trim()}" n\u00E3o reconhecida (usando "${empresa}")`);
    return { dados, erros, precisaDepto: sep.precisaDepto };
  },
  criar: (dados) => {
    const f = normalizeFunc({ ...dados });
    if (dados._vt) f.beneficios.vt.ativo = true;
    if (dados._vr) f.beneficios.vr.ativo = true;
    delete f._vt; delete f._vr;
    return f;
  },
};
// Deduz o status da entrevista a partir da observação escrita pelo RH na planilha.
// Sem isso toda entrevista importada virava "Realizada" — inclusive a de quem nunca
// atendeu o contato. Uma entrevista tem UM status, então a ordem abaixo é a prioridade.
function statusEntrevistaImport(observacao, dataEnt) {
  const n = normalizarTexto(observacao); // "Ñ RESPONDE" -> "n responde"
  if (n) {
    // Saiu do processo por conta própria: a entrevista não chegou a acontecer.
    if (/(desistiu|desistencia|desistiram|nao tem interesse|sem interesse|nao quis|recusou|recusa|declinou|arrumou outro|outro emprego|ja esta empregad|nao pode|indisponivel)/.test(n)) return "Cancelada";
    // Estava previsto e a pessoa não apareceu ou sumiu no contato.
    if (/(nao compareceu|n compareceu|nao compareceram|faltou|faltaram|nao veio|nao apareceu|no show|noshow|furou)/.test(n)) return "Não compareceu";
    if (/(nao responde|nao respondeu|n responde|n resp|nao retornou|sem retorno|nao atende|nao atendeu|nao deu retorno|numero errado|nao existe|caixa postal)/.test(n)) return "Não compareceu";
  }
  // Sem pista na observação: data futura = ainda vai acontecer; senão, aconteceu.
  return dataEnt && dataEnt >= hojeISO() ? "Agendada" : "Realizada";
}
// Etapa do funil na importação: a planilha do RH já traz o processo andado, então o
// candidato entra na coluna que corresponde ao que já aconteceu com ele — em vez de
// todo mundo cair em Triagem e ter que ser movido na mão.
function etapaImport(resultado, statusEnt) {
  // A observação pesa MAIS que o parecer: quem desistiu ou faltou está fora do processo,
  // ainda que o Resultado diga "S". Ex.: aprovada na entrevista, mas desistiu por ser
  // longe — o "S" descreve como ela foi na conversa, não que ela siga no funil.
  if (statusEnt === "Cancelada" || statusEnt === "Não compareceu") return "Não Qualificados";
  const r = normalizarTexto(resultado);
  if (/^(s|sim|aprovado|aprovada)$/.test(r)) return "Qualificados";
  if (/^(n|nao|reprovado|reprovada)$/.test(r)) return "Não Qualificados";
  if (statusEnt === "Realizada") return "Entrevista Realizada"; // entrevistado, sem parecer ainda
  if (statusEnt === "Agendada") return "Entrevista Agendada";
  return "Triagem"; // sem entrevista e sem parecer: começa do início
}
const SCHEMA_CAND = {
  titulo: "Importar candidatos",
  chave: "candidatos",
  // Duplicidade conferida por CPF, e-mail, telefone e WhatsApp.
  matchKeys: ["cpf", "email", "telefone", "whatsapp"],
  // Telefone e WhatsApp compartilham o mesmo "espa\u00E7o" de busca: um n\u00FAmero gravado como
  // telefone num cadastro casa com o mesmo n\u00FAmero vindo como WhatsApp na planilha.
  matchAlias: { telefone: ["telefone", "whatsapp"], whatsapp: ["whatsapp", "telefone"] },
  // Campos que NUNCA s\u00E3o sobrescritos ao atualizar um cadastro existente:
  // a etapa do candidato no funil \u00E9 do CRM, n\u00E3o da planilha.
  naoAtualizar: ["status"],
  resolveArea: true, // exige \u00C1rea de Recrutamento em todos os candidatos importados
  // Ordem espelhando a planilha de trabalho do RH (\u00E9 ela que gera o modelo para baixar).
  campos: [
    { key: "nome", label: "Nome", obrig: true, syn: ["candidato", "nome completo", "nome do candidato", "candidate", "applicant", "nome candidato"] },
    { key: "celular", label: "Celular", syn: ["cel", "celular contato", "mobile"] },
    { key: "dataCadastro", label: "Data", syn: ["data", "data de cadastro", "data cadastro", "cadastro", "recebido em", "data do contato"] },
    { key: "vaga", label: "Cargo pretendido", syn: ["cargo", "funcao", "vaga", "pretensao", "posicao", "position", "job"] },
    { key: "empresa", label: "Empresa", syn: ["filial", "local", "unidade", "razao social"] },
    { key: "origem", label: "Origem", syn: ["fonte", "canal", "midia"] },
    { key: "observacoesRH", label: "Observa\u00E7\u00F5es", syn: ["obs", "comentarios", "anotacoes", "observacao"] },
    { key: "dataEntrevista", label: "Data da entrevista", syn: ["entrevista", "data entrevista"] },
    { key: "horaEntrevista", label: "Hor\u00E1rio", syn: ["hora", "horario", "hora da entrevista"] },
    { key: "entrevistador", label: "Entrevistador", syn: ["avaliador", "recrutador", "responsavel"] },
    { key: "resultado", label: "Resultado", syn: ["parecer", "situacao entrevista", "conclusao"] },
    // Colunas extras (extra: true): n\u00E3o entram no modelo para baixar \u2014 a planilha de
    // trabalho do RH n\u00E3o as tem \u2014 mas continuam sendo reconhecidas se algu\u00E9m as trouxer.
    { key: "telefone", label: "Telefone", extra: true, syn: ["numero", "contato", "fone", "tel", "telefone fixo", "phone"] },
    { key: "whatsapp", label: "WhatsApp", extra: true, syn: ["whats", "zap", "whatsapp contato", "wpp"] },
    { key: "cpf", label: "CPF", extra: true, syn: ["documento"] },
    { key: "email", label: "E-mail", extra: true, syn: ["email", "e mail", "mail"] },
    { key: "cidade", label: "Cidade", extra: true, syn: ["municipio", "localidade", "city"] },
    { key: "estado", label: "Estado", extra: true, syn: ["uf", "estado sigla", "state"] },
    { key: "area", label: "\u00C1rea de recrutamento", extra: true, syn: ["area", "area de recrutamento", "departamento", "setor", "depto", "segmento", "area vaga"] },
    { key: "notaGeral", label: "Nota", extra: true, syn: ["avaliacao", "score", "pontuacao"] },
  ],
  transformar: (v) => {
    const origem = matchLista(v.origem, ORIGENS) || (String(v.origem || "").trim()) || "Site";
    const empresa = matchLista(v.empresa, [...EMPRESAS, ...EMPRESAS_ANTIGAS]) || (String(v.empresa || "").trim()) || EMPRESAS[0];
    // Telefone principal: usa a primeira coluna preenchida entre Telefone/Celular/WhatsApp.
    const tel = soDigitos(v.telefone), cel = soDigitos(v.celular), zap = soDigitos(v.whatsapp);
    const telefone = tel || cel || zap;
    const whatsapp = zap || (cel && cel !== telefone ? cel : "");
    const vaga = separarCargoDepto(v.vaga, "").cargo || String(v.vaga || "").trim();
    // \u00C1rea: da coluna pr\u00F3pria (\u00C1rea/Departamento/Setor); se n\u00E3o houver, deduz do cargo/vaga.
    const area = inferirArea(v.area, vaga);
    // A observa\u00E7\u00E3o e o resultado do RH definem o status da entrevista e a etapa do funil.
    const obs = limpo(v.observacoesRH), resultado = limpo(v.resultado);
    const dataEnt = parseDataFlex(v.dataEntrevista);
    const statusEnt = statusEntrevistaImport(obs, dataEnt);
    const dados = {
      nome: String(v.nome || "").trim(), telefone, whatsapp, cpf: soDigitos(v.cpf), email: String(v.email || "").trim().toLowerCase(),
      cidade: String(v.cidade || "").trim(), estado: String(v.estado || "").trim().toUpperCase(),
      vaga, area, empresa, origem,
      status: etapaImport(resultado, statusEnt), // etapa vem do que a planilha j\u00E1 registrou
      dataCadastro: parseDataFlex(v.dataCadastro),
      notaGeral: parseMoedaFlex(v.notaGeral), observacoesRH: obs,
      _dataEntrevista: dataEnt, _horaEntrevista: parseHoraFlex(v.horaEntrevista), _entrevistador: limpo(v.entrevistador), _resultado: resultado, _statusEnt: statusEnt,
    };
    const erros = []; if (!dados.nome) erros.push("Nome obrigat\u00F3rio");
    return { dados, erros, precisaArea: !area };
  },
  criar: (dados) => {
    const { _dataEntrevista, _horaEntrevista, _entrevistador, _resultado, _statusEnt, ...resto } = dados;
    const temEnt = _dataEntrevista || _entrevistador || _resultado;
    const hist = temEnt ? [{ id: uid(), data: _dataEntrevista, hora: _horaEntrevista || "", tipo: "Entrevista RH", avaliador: _entrevistador, local: "", status: _statusEnt, respostas: "", observacoes: _resultado ? `Resultado: ${_resultado}` : "", notaFinal: "" }] : [];
    // Mantém a data de cadastro da planilha quando houver; senão, hoje.
    return { ...CAND_VAZIO, ...resto, historicoEntrevistas: hist, id: uid(), dataCadastro: resto.dataCadastro || hojeISO() };
  },
};
function imprimirRelatorio(titulo, headers, rows, resumo) {
  const th = headers.map((h) => `<th>${h}</th>`).join("");
  const trs = rows.map((r) => `<tr>${r.map((c) => `<td>${c == null ? "" : String(c)}</td>`).join("")}</tr>`).join("");
  const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${titulo}</title>
  <style>body{font-family:Arial,Helvetica,sans-serif;color:#1e293b;margin:24px}h1{font-size:18px;margin:0 0 2px}.meta{color:#64748b;font-size:12px;margin-bottom:16px}.resumo{font-size:13px;margin:8px 0 16px;color:#334155}table{width:100%;border-collapse:collapse;font-size:12px}th,td{border:1px solid #e2e8f0;padding:6px 8px;text-align:left}th{background:#f1f5f9}tr:nth-child(even) td{background:#f8fafc}@media print{body{margin:0}}</style></head>
  <body><h1>${titulo}</h1><p class="meta">Grupo Zaytan · Gerado em ${new Date().toLocaleString("pt-BR")}</p>${resumo ? `<p class="resumo">${resumo}</p>` : ""}<table><thead><tr>${th}</tr></thead><tbody>${trs}</tbody></table></body></html>`;
  const w = window.open("", "_blank");
  if (w) { w.document.write(html); w.document.close(); w.focus(); setTimeout(() => w.print(), 400); }
  else { const blob = new Blob([html], { type: "text/html" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = `${titulo}.html`; a.click(); URL.revokeObjectURL(url); }
}
function gerarCartaDemissaoHTML(f) {
  const r = f.rescisao || {};
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Carta de Desligamento - ${f.nome}</title>
  <style>body{font-family:'Times New Roman',Georgia,serif;color:#111;max-width:720px;margin:40px auto;padding:0 32px;line-height:1.85;font-size:15px}h1{text-align:center;font-size:18px;text-transform:uppercase;letter-spacing:.05em;margin-bottom:36px}.local{text-align:right;margin:28px 0}.assinatura{margin-top:72px;text-align:center}.linha{margin:52px auto 6px;width:300px;border-top:1px solid #111}@media print{body{margin:0}}</style></head>
  <body><h1>Comunicado de Desligamento</h1>
  <p>À <strong>${f.empresa}</strong>,</p>
  <p>Prezado(a) <strong>${f.nome}</strong>,</p>
  <p>Comunicamos o encerramento do seu contrato de trabalho no cargo de <strong>${f.cargo || "—"}</strong>, na modalidade <strong>${r.tipo || "—"}</strong>, com data de desligamento em <strong>${fmtData(r.dataDesligamento)}</strong>.</p>
  ${r.motivo ? `<p><strong>Motivo:</strong> ${r.motivo}.</p>` : ""}
  <p>As verbas rescisórias, no valor líquido de <strong>${fmtBRL(r.valorLiquido)}</strong> (valor bruto de ${fmtBRL(r.valorBruto)}, com desconto de INSS de ${fmtBRL(r.valorInss)} e FGTS de ${fmtBRL(r.valorFgts)}), serão pagas até <strong>${fmtData(r.dataPagamento)}</strong>, conforme a legislação trabalhista vigente.</p>
  ${r.observacoes ? `<p>${r.observacoes}</p>` : ""}
  <p>Agradecemos pela sua dedicação e colaboração durante o período, e desejamos sucesso em seus próximos desafios profissionais.</p>
  <div class="local">${fmtData(r.dataDesligamento || hojeISO())}</div>
  <div class="assinatura"><div class="linha"></div><p>Departamento de Recursos Humanos<br>${f.empresa}</p></div>
  </body></html>`;
}
function abrirImprimirHTML(html, nomeArquivo) {
  const w = window.open("", "_blank");
  if (w) { w.document.write(html); w.document.close(); w.focus(); setTimeout(() => w.print(), 400); }
  else { const blob = new Blob([html], { type: "text/html" }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = nomeArquivo; a.click(); URL.revokeObjectURL(url); }
}
function exportarEntrevistaPDF(cand, ent) {
  const html = `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Entrevista - ${cand.nome}</title>
  <style>body{font-family:Arial,Helvetica,sans-serif;color:#1e293b;max-width:720px;margin:32px auto;padding:0 24px;line-height:1.5}h1{font-size:20px;margin:0 0 4px}h2{font-size:13px;text-transform:uppercase;letter-spacing:.05em;color:#64748b;margin:20px 0 6px;border-bottom:1px solid #e2e8f0;padding-bottom:4px}.meta{color:#64748b;font-size:13px}.nota{display:inline-block;background:#eff6ff;color:#1d4ed8;border-radius:999px;padding:4px 12px;font-weight:600;margin-top:8px}p{margin:6px 0;white-space:pre-wrap}@media print{body{margin:0}}</style></head>
  <body><h1>${cand.nome || "Candidato"}</h1><p class="meta">${cand.vaga || ""} · ${cand.empresa || ""} · Origem: ${cand.origem || ""}</p>
  <h2>Dados da entrevista</h2><p><strong>Tipo:</strong> ${ent.tipo}<br><strong>Data:</strong> ${fmtData(ent.data)}${ent.hora ? " às " + ent.hora : ""}<br><strong>Entrevistador:</strong> ${ent.avaliador || "—"}<br><strong>Local/Link:</strong> ${ent.local || "—"}<br><strong>Status:</strong> ${ent.status || "—"}</p>
  <h2>Respostas</h2><p>${ent.respostas || "—"}</p><h2>Observações</h2><p>${ent.observacoes || "—"}</p>
  <div class="nota">Nota final: ${ent.notaFinal !== "" && ent.notaFinal != null ? ent.notaFinal : "—"}</div></body></html>`;
  abrirImprimirHTML(html, `entrevista_${(cand.nome || "candidato").replace(/\s+/g, "_")}.html`);
}
// ---- Convite de entrevista por WhatsApp (manual — sem API, só copiar texto ou abrir link) ----
function mensagemConviteEntrevista(cand, ent, config) {
  const primeiroNome = (cand.nome || "").trim().split(/\s+/)[0] || "candidato(a)";
  const empresa = ent.empresa || cand.empresa || config?.nomeEmpresa || "";
  const cargo = ent.cargo || cand.vaga || "";
  const dataFmt = ent.data ? fmtData(ent.data) : "";
  const horaFmt = ent.hora ? horaLegivel(ent.hora) : "";
  const linhas = [
    `Olá, ${primeiroNome}! Tudo bem?`,
    `Sua entrevista${cargo ? ` para a vaga de ${cargo}` : ""}${empresa ? ` na ${empresa}` : ""} foi agendada${dataFmt ? ` para o dia ${dataFmt}` : ""}${horaFmt ? `, às ${horaFmt}` : ""}.`,
    ent.local ? `Local/Link: ${ent.local}` : "",
    "Por favor, confirme sua presença respondendo esta mensagem.",
  ].filter(Boolean);
  return linhas.join("\n");
}
function linkWhatsApp(telefone, texto) {
  return `https://wa.me/55${soDigitos(telefone)}?text=${encodeURIComponent(texto)}`;
}

/* ==================================================================
   DESIGN SYSTEM — componentes reutilizáveis (identidade do Zaytan Hub)
   As classes usam os tokens do Financeiro (src/styles.css); a conversão
   das cores antigas é feita por scripts/rh/converter-visual.mjs.
   ================================================================== */
// true quando o RH roda dentro do shell unificado (o título da página vem do shell).
const RhEmbutidoCtx = React.createContext(false);
const inputCls = "w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground outline-none transition-colors focus:border-primary focus:ring-2 focus:ring-primary/15 disabled:bg-secondary/50";
const labelCls = "block text-xs font-medium text-foreground/70 mb-1";
// Campo monetario com mascara R$: digite 1980 -> R$ 1.980,00 (sem precisar apagar 0,00).
function MoedaInput({ value, onChange, className = inputCls, disabled }) {
  const [foco, setFoco] = useState(false);
  const [raw, setRaw] = useState("");
  const display = foco ? raw : (num(value) ? fmtBRL(value) : "");
  const handle = (e) => {
    let s = e.target.value.replace(/[^\d,]/g, "");
    const parts = s.split(",");
    if (parts.length > 2) s = parts[0] + "," + parts.slice(1).join("");
    setRaw(s);
    onChange(parseFloat(s.replace(/\./g, "").replace(",", ".")) || 0);
  };
  return (
    <div className="relative">
      <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-sm text-muted-foreground/80">R$</span>
      <input inputMode="decimal" disabled={disabled} className={`${className} pl-9`} value={display} placeholder="0,00"
        onFocus={() => { setFoco(true); setRaw(num(value) ? String(arred2(num(value))).replace(".", ",") : ""); }}
        onBlur={() => setFoco(false)} onChange={handle} />
    </div>
  );
}
// Campo somente números: armazena apenas dígitos e exibe máscara visual conforme o tipo. Bloqueia letras.
const MASK_CFG = {
  cpf: { fmt: fmtCPF, max: 11, ph: "000.000.000-00" },
  telefone: { fmt: fmtTelefoneBR, max: 11, ph: "(00) 00000-0000" },
  cep: { fmt: fmtCEP, max: 8, ph: "00000-000" },
  pis: { fmt: fmtPIS, max: 11, ph: "000.00000.00-0" },
  num: { fmt: (v) => soDigitos(v), max: 20, ph: "Somente números" },
};
function MaskedInput({ value, onChange, tipo = "num", className = inputCls, placeholder, maxDigits, disabled }) {
  const cfg = MASK_CFG[tipo] || MASK_CFG.num;
  const lim = maxDigits || cfg.max;
  return (
    <input inputMode="numeric" disabled={disabled} className={className} placeholder={placeholder || cfg.ph}
      value={cfg.fmt(value || "")}
      onKeyDown={(e) => { if (e.key.length === 1 && !/[0-9]/.test(e.key) && !e.ctrlKey && !e.metaKey) e.preventDefault(); }}
      onChange={(e) => onChange(soDigitos(e.target.value).slice(0, lim))} />
  );
}

// title: texto de ajuda que aparece ao parar o mouse em cima. Sem repassar para o <button>,
// todo title escrito num <Btn> virava código morto (silenciosamente ignorado).
const Btn = ({ children, onClick, variant = "primary", type = "button", className = "", size = "md", disabled, title }) => {
  const v = {
    // Ação principal = botão "tinta" (preto), como no Financeiro; o laranja fica para destaques.
    primary: "bg-foreground hover:bg-foreground/90 text-background border border-transparent",
    secondary: "bg-card hover:bg-secondary text-foreground border border-input",
    success: "bg-success hover:bg-success/90 text-white border border-transparent",
    warning: "bg-warning hover:bg-warning/90 text-[oklch(0.16_0.005_286)] border border-transparent",
    danger: "bg-destructive hover:bg-destructive/90 text-white border border-transparent",
  };
  const s = size === "sm" ? "min-h-8 px-2.5 py-1 text-xs" : size === "lg" ? "min-h-10 px-4 py-2 text-sm" : "min-h-9 px-3.5 py-1.5 text-sm";
  return <button type={type} onClick={onClick} disabled={disabled} title={title} className={`inline-flex cursor-pointer items-center justify-center gap-2 rounded-md font-medium transition-colors disabled:opacity-50 disabled:pointer-events-none ${v[variant]} ${s} ${className}`}>{children}</button>;
};
const IconBtn = ({ icon: Icon, onClick, title, tone = "default" }) => {
  const t = tone === "danger" ? "text-muted-foreground hover:bg-destructive/10 hover:text-destructive" : "text-muted-foreground hover:bg-secondary hover:text-foreground";
  return <button type="button" title={title} onClick={onClick} className={`cursor-pointer rounded-md p-1.5 transition-colors ${t}`}><Icon size={15} /></button>;
};
const Card = ({ children, className = "" }) => (<div className={`rounded-xl border border-border/70 bg-card card-elevated ${className}`}>{children}</div>);
const Field = ({ label, children, hint }) => (<label className="block"><span className={labelCls}>{label}</span>{children}{hint && <span className="mt-1 block text-xs text-muted-foreground/80">{hint}</span>}</label>);
const Empty = ({ texto, icon: Icon }) => (<div className="flex flex-col items-center justify-center gap-2 rounded-md border border-dashed border-border py-10 text-center text-sm text-muted-foreground/80">{Icon && <Icon size={22} className="text-muted-foreground/50" />}{texto}</div>);
const Badge = ({ children, cls = "bg-secondary text-foreground/70" }) => (<span className={`inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-xs font-medium ${cls}`}>{children}</span>);
// No shell unificado, o título grande é do shell (e a aba diz qual tela é); aqui fica a
// linha de contexto da tela: nome em destaque discreto, descrição e ações à direita.
const PageHeader = ({ titulo, subtitulo, children }) => {
  const embutido = React.useContext(RhEmbutidoCtx);
  if (embutido) {
    return (
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="min-w-0">
          <h2 className="font-display text-base font-semibold tracking-tight text-foreground">{titulo}</h2>
          {subtitulo && <p className="mt-0.5 text-[13px] text-muted-foreground">{subtitulo}</p>}
        </div>
        {children && <div className="flex flex-wrap items-center gap-2">{children}</div>}
      </div>
    );
  }
  return (
    <div className="flex flex-wrap items-end justify-between gap-3">
      <div><h1 className="font-display text-2xl font-bold tracking-tight text-foreground">{titulo}</h1>{subtitulo && <p className="mt-1 text-sm text-muted-foreground">{subtitulo}</p>}</div>
      {children && <div className="flex flex-wrap items-center gap-2">{children}</div>}
    </div>
  );
};
const SearchInput = ({ valor, onChange, placeholder = "Buscar...", className = "" }) => (
  <div className={`relative ${className}`}><Search size={15} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground/80" /><input className={`${inputCls} pl-9`} placeholder={placeholder} value={valor} onChange={(e) => onChange(e.target.value)} /></div>
);
// Combobox pesquisavel: lista de selecao com busca embutida. Carrega opcoes do banco/config.
// allowCustom=true permite digitar um valor livre alem das opcoes.
function Combobox({ value, onChange, options = [], placeholder = "Selecione...", allowCustom = false, disabled, className = inputCls }) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const ref = useRef(null);
  useEffect(() => {
    if (!open) return;
    const h = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    window.addEventListener("mousedown", h);
    return () => window.removeEventListener("mousedown", h);
  }, [open]);
  const opts = [...new Set(options.filter(Boolean).map(String))];
  const term = q.trim().toLowerCase();
  const filtradas = term ? opts.filter((o) => o.toLowerCase().includes(term)) : opts;
  const escolher = (v) => { onChange(v); setOpen(false); setQ(""); };
  return (
    <div className="relative" ref={ref}>
      <button type="button" disabled={disabled} onClick={() => { setOpen((o) => !o); setQ(""); }}
        className={`${className} flex items-center justify-between text-left ${disabled ? "" : "cursor-pointer"}`}>
        <span className={`truncate ${value ? "text-foreground" : "text-muted-foreground/80"}`}>{value || placeholder}</span>
        <ChevronDown size={15} className="ml-1 shrink-0 text-muted-foreground/80" />
      </button>
      {open && !disabled && (
        <div className="absolute z-30 mt-1 w-full overflow-hidden rounded-md border border-border bg-card shadow-lg">
          <div className="border-b border-border/60 p-2"><div className="relative"><Search size={14} className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground/80" /><input autoFocus className="w-full rounded-md border border-border bg-secondary/50 py-1.5 pl-8 pr-2 text-sm outline-none focus:border-primary/70 focus:bg-card" placeholder="Pesquisar..." value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter" && allowCustom && q.trim()) escolher(q.trim()); }} /></div></div>
          <ul className="max-h-56 overflow-y-auto py-1">
            {filtradas.length === 0 && !allowCustom && <li className="px-3 py-2 text-sm text-muted-foreground/80">Nada encontrado.</li>}
            {allowCustom && term && !opts.some((o) => o.toLowerCase() === term) && (
              <li><button type="button" onMouseDown={(e) => e.preventDefault()} onClick={() => escolher(q.trim())} className="flex w-full items-center gap-2 px-3 py-2 text-left text-sm text-primary hover:bg-primary/8"><Plus size={13} /> Usar “{q.trim()}”</button></li>
            )}
            {filtradas.map((o) => (
              <li key={o}><button type="button" onMouseDown={(e) => e.preventDefault()} onClick={() => escolher(o)} className={`flex w-full items-center justify-between px-3 py-1.5 text-left text-sm hover:bg-secondary/50 ${o === value ? "font-medium text-primary" : "text-foreground/80"}`}>{o}{o === value && <Check size={14} className="text-primary" />}</button></li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

function Modal({ title, subtitle, onClose, children, footer, max = "max-w-2xl" }) {
  useEffect(() => { const h = (e) => e.key === "Escape" && onClose(); window.addEventListener("keydown", h); return () => window.removeEventListener("keydown", h); }, [onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/50 p-4 backdrop-blur-[1px]" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className={`my-6 w-full ${max} rounded-2xl border border-border bg-card shadow-2xl`}>
        <div className="flex items-start justify-between border-b border-border/60 px-6 py-4"><div><h3 className="font-display text-lg font-semibold text-foreground">{title}</h3>{subtitle && <p className="text-xs text-muted-foreground">{subtitle}</p>}</div><button onClick={onClose} className="cursor-pointer rounded-md p-1.5 text-muted-foreground hover:bg-secondary hover:text-foreground"><X size={18} /></button></div>
        <div className="overflow-y-auto px-6 py-5" style={{ maxHeight: "72vh" }}>{children}</div>
        {footer && <div className="flex justify-end gap-2 border-t border-border/60 bg-secondary/30 px-6 py-3.5">{footer}</div>}
      </div>
    </div>
  );
}
function Tabs({ tabs, active, onChange }) {
  return (
    <div className="inline-flex max-w-full flex-wrap gap-1 rounded-lg bg-secondary/70 p-1">
      {tabs.map((t) => (<button key={t.id} onClick={() => onChange(t.id)} className={`flex cursor-pointer items-center gap-1.5 rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${active === t.id ? "bg-card text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"}`}>{t.icon && <t.icon size={14} />}{t.label}</button>))}
    </div>
  );
}
// Encolhe automaticamente a fonte ate o valor caber na largura do card (sem estourar nem cortar).
function FitText({ children, className = "", title, max = 18, min = 11 }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const fit = () => {
      el.style.fontSize = max + "px";
      let s = max, guard = 0;
      while (el.scrollWidth > el.clientWidth + 0.5 && s > min && guard < 24) { s -= 0.5; el.style.fontSize = s + "px"; guard++; }
    };
    fit();
    if (typeof ResizeObserver === "undefined") return;
    const ro = new ResizeObserver(fit); ro.observe(el);
    return () => ro.disconnect();
  }, [children, max, min]);
  return <span ref={ref} title={title} className={`block overflow-hidden whitespace-nowrap ${className}`}>{children}</span>;
}
const Kpi = ({ icon: Icon, label, value, tone = "slate", onClick }) => {
  // "rose" era usado (DashboardTreinoCards) mas faltava no mapa e virava a classe "undefined".
  // Tom "blue" (informativo) usa a tinta, como os KPIs do Financeiro: o laranja fica para destaques.
  const c = { slate: "text-foreground", blue: "text-foreground", emerald: "text-success", amber: "text-warning-ink", red: "text-destructive", rose: "text-destructive" }[tone] || "text-foreground";
  return (
    <button type="button" onClick={onClick} disabled={!onClick} title={typeof label === "string" ? label : undefined} className={`group flex min-w-0 items-center gap-2.5 rounded-xl border border-border/70 bg-card card-elevated px-3 py-3 text-left transition-all ${onClick ? "cursor-pointer hover:-translate-y-0.5" : "cursor-default"}`}>
      <span className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-secondary text-muted-foreground transition-colors ${onClick ? "group-hover:bg-primary/10 group-hover:text-primary" : ""}`}><Icon size={15} strokeWidth={1.8} /></span>
      <span className="min-w-0 flex-1"><span className="line-clamp-2 break-words text-[11.5px] leading-tight text-muted-foreground">{label}</span><FitText title={typeof value === "string" ? value : String(value ?? "")} max={20} className={`font-numeric mt-1 font-semibold leading-tight tabular-nums ${c}`}>{value}</FitText></span>
    </button>
  );
};
// Menu "Exportar": Excel (.xlsx), CSV e PDF/Imprimir. Respeita as linhas recebidas (já filtradas).
function ExportButtons({ titulo, headers, rows, resumo, size = "sm" }) {
  const [open, setOpen] = useState(false);
  useEffect(() => { if (!open) return; const h = () => setOpen(false); window.addEventListener("click", h); return () => window.removeEventListener("click", h); }, [open]);
  const Item = ({ icon: Icon, children, onClick }) => (<button onClick={() => { onClick(); setOpen(false); }} className="flex w-full items-center gap-2 px-3 py-2 text-left text-sm text-foreground/80 hover:bg-secondary/50"><Icon size={14} className="text-muted-foreground/80" />{children}</button>);
  return (
    <div className="relative inline-block" onClick={(e) => e.stopPropagation()}>
      <Btn size={size} variant="secondary" onClick={() => setOpen((o) => !o)}><Download size={13} /> Exportar <ChevronDown size={12} /></Btn>
      {open && (
        <div className="absolute right-0 z-30 mt-1 w-44 overflow-hidden rounded-md border border-border bg-card py-1 shadow-lg">
          <Item icon={FileDown} onClick={() => baixarXLSX(titulo, headers, rows)}>Excel (.xlsx)</Item>
          <Item icon={Download} onClick={() => baixarCSV(titulo, headers, rows)}>CSV</Item>
          <Item icon={FileText} onClick={() => imprimirRelatorio(titulo, headers, rows, resumo)}>PDF</Item>
          <Item icon={Printer} onClick={() => imprimirRelatorio(titulo, headers, rows, resumo)}>Imprimir</Item>
        </div>
      )}
    </div>
  );
}
// Exportação com SELEÇÃO DE COLUNAS: o usuário marca só os campos que quer levar.
// `campos` = [{ key, label, get(item) }]; `itens` já vem filtrado (respeita os filtros da tela).
function ExportColunas({ titulo, campos, itens, resumo, size = "sm" }) {
  const [aberto, setAberto] = useState(false);
  const [sel, setSel] = useState(() => new Set(campos.map((c) => c.key)));
  const toggle = (k) => setSel((s) => { const n = new Set(s); n.has(k) ? n.delete(k) : n.add(k); return n; });
  const escolhidos = campos.filter((c) => sel.has(c.key));
  const headers = escolhidos.map((c) => c.label);
  const linhas = itens.map((it) => escolhidos.map((c) => { const v = c.get(it); return v == null ? "" : v; }));
  const exportar = (fn) => { if (!escolhidos.length) { alert("Escolha ao menos uma coluna."); return; } fn(titulo, headers, linhas, resumo); setAberto(false); };
  return (
    <>
      <Btn size={size} variant="secondary" onClick={() => setAberto(true)}><Download size={13} /> Exportar</Btn>
      {aberto && (
        <Modal title="Exportar" subtitle={`${itens.length} registro(s) · escolha as colunas`} onClose={() => setAberto(false)} max="max-w-lg"
          footer={<>
            <Btn variant="secondary" onClick={() => setAberto(false)}>Cancelar</Btn>
            <Btn variant="secondary" onClick={() => exportar(baixarCSV)}><Download size={15} /> CSV</Btn>
            <Btn variant="secondary" onClick={() => exportar(imprimirRelatorio)}><FileText size={15} /> PDF</Btn>
            <Btn onClick={() => exportar(baixarXLSX)}><FileDown size={15} /> Excel</Btn>
          </>}>
          <div className="space-y-3">
            <div className="flex items-center justify-between text-xs">
              <span className="text-muted-foreground">{escolhidos.length} de {campos.length} colunas selecionadas</span>
              <span className="flex gap-2">
                <button onClick={() => setSel(new Set(campos.map((c) => c.key)))} className="font-medium text-primary hover:text-primary">Marcar todas</button>
                <button onClick={() => setSel(new Set())} className="font-medium text-muted-foreground hover:text-foreground/80">Limpar</button>
              </span>
            </div>
            <div className="grid grid-cols-1 gap-1.5 sm:grid-cols-2">
              {campos.map((c) => (
                <label key={c.key} className="flex cursor-pointer items-center gap-2 rounded-md border border-border px-3 py-2 text-sm text-foreground/80 hover:bg-secondary/50">
                  <input type="checkbox" checked={sel.has(c.key)} onChange={() => toggle(c.key)} className="h-4 w-4 rounded border-input text-primary" />
                  {c.label}
                </label>
              ))}
            </div>
            <p className="text-xs text-muted-foreground/80">Só os candidatos que estão na tela agora (com os filtros atuais) serão exportados.</p>
          </div>
        </Modal>
      )}
    </>
  );
}

/* --------- DataTable: ordenação, paginação, busca, seleção, ações --- */
function DataTable({ columns, rows, getId = (r) => r.id, searchPlaceholder = "Buscar na tabela...", pageSize = 10, selectable = false, bulkActions, actions, filtros, toolbarRight, initialSort, initialQuery = "", vazio = "Nenhum registro encontrado.", dense = false, rowClassName = () => "", rodape }) {
  const [q, setQ] = useState(initialQuery);
  useEffect(() => { if (initialQuery) setQ(initialQuery); }, [initialQuery]);
  const [sortKey, setSortKey] = useState(initialSort?.key || null);
  const [sortDir, setSortDir] = useState(initialSort?.dir || "asc");
  const [page, setPage] = useState(1);
  const [sel, setSel] = useState(() => new Set());
  const searchCols = columns.filter((c) => c.searchable !== false);
  const getVal = (col, r) => (col.get ? col.get(r) : r[col.key]);

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    if (!term) return rows;
    return rows.filter((r) => searchCols.some((c) => String(getVal(c, r) ?? "").toLowerCase().includes(term)));
  }, [rows, q, columns]);

  const sorted = useMemo(() => {
    if (!sortKey) return filtered;
    const col = columns.find((c) => c.key === sortKey); if (!col) return filtered;
    const dir = sortDir === "asc" ? 1 : -1;
    return [...filtered].sort((a, b) => {
      let va = getVal(col, a), vb = getVal(col, b);
      if (col.type === "number") { va = num(va); vb = num(vb); return (va - vb) * dir; }
      va = String(va ?? ""); vb = String(vb ?? "");
      return va.localeCompare(vb, "pt-BR", { numeric: true }) * dir;
    });
  }, [filtered, sortKey, sortDir, columns]);

  const totalPages = Math.max(1, Math.ceil(sorted.length / pageSize));
  const curPage = Math.min(page, totalPages);
  const pageRows = sorted.slice((curPage - 1) * pageSize, curPage * pageSize);
  useEffect(() => { setPage(1); }, [q, rows.length]);

  const toggleSort = (col) => { if (col.sortable === false) return; if (sortKey === col.key) setSortDir((d) => (d === "asc" ? "desc" : "asc")); else { setSortKey(col.key); setSortDir("asc"); } };
  const pageIds = pageRows.map(getId);
  const allChecked = pageIds.length > 0 && pageIds.every((id) => sel.has(id));
  const toggleAll = () => setSel((prev) => { const n = new Set(prev); if (allChecked) pageIds.forEach((id) => n.delete(id)); else pageIds.forEach((id) => n.add(id)); return n; });
  const toggleOne = (id) => setSel((prev) => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });
  const clearSel = () => setSel(new Set());
  const pad = dense ? "px-3 py-2" : "px-4 py-2.5";

  return (
    <Card className="overflow-hidden">
      <div className="flex flex-wrap items-center gap-2 border-b border-border/60 p-3">
        <SearchInput valor={q} onChange={setQ} placeholder={searchPlaceholder} className="min-w-[220px] flex-1" />
        {filtros}
        <div className="ml-auto flex items-center gap-2">{toolbarRight}</div>
      </div>
      {selectable && sel.size > 0 && (
        <div className="flex items-center gap-3 border-b border-primary/20 bg-primary/5 px-4 py-2 text-sm text-primary">
          <span className="font-medium">{sel.size} selecionado(s)</span>
          {bulkActions && bulkActions([...sel], clearSel)}
          <button onClick={clearSel} className="ml-auto text-xs text-primary hover:underline">Limpar seleção</button>
        </div>
      )}
      {/* Altura limitada + rolagem interna: mantém a barra de rolagem horizontal sempre
          ao alcance (no rodapé da tabela) em vez de exigir descer a página até a última
          linha para conseguir ver as colunas da direita. O cabeçalho fica fixo no topo. */}
      <div className="overflow-auto max-h-[calc(100vh-16rem)]" style={{ scrollbarGutter: "stable" }}>
        <table className="w-full text-sm">
          <thead className="sticky top-0 z-10 bg-secondary text-left text-[11px] font-medium uppercase tracking-wider text-muted-foreground">
            <tr>
              {selectable && <th className={`${pad} w-10`}><input type="checkbox" checked={allChecked} onChange={toggleAll} className="h-4 w-4 rounded border-input text-primary" /></th>}
              {columns.map((c) => (
                <th key={c.key} className={`${pad} ${c.align === "right" ? "text-right" : c.align === "center" ? "text-center" : ""} ${(c.type === "number" || c.align === "right") ? "tabular-nums" : ""} ${c.sortable === false ? "" : "cursor-pointer select-none hover:text-foreground/80"}`} onClick={() => toggleSort(c)}>
                  <span className={`inline-flex items-center gap-1 ${c.align === "right" ? "flex-row-reverse" : ""}`}>{c.header}{c.sortable === false ? null : sortKey === c.key ? (sortDir === "asc" ? <ArrowUp size={12} /> : <ArrowDown size={12} />) : <ArrowUpDown size={12} className="text-muted-foreground/50" />}</span>
                </th>
              ))}
              {actions && <th className={`${pad} w-1 text-right`}>Ações</th>}
            </tr>
          </thead>
          <tbody className="divide-y divide-border/60">
            {pageRows.length === 0 ? (
              <tr><td colSpan={columns.length + (selectable ? 1 : 0) + (actions ? 1 : 0)} className="px-4 py-10"><Empty texto={vazio} /></td></tr>
            ) : pageRows.map((r) => {
              const id = getId(r);
              return (
                <tr key={id} className={`hover:bg-secondary/35 ${sel.has(id) ? "bg-primary/5" : rowClassName(r) || ""}`}>
                  {selectable && <td className={pad}><input type="checkbox" checked={sel.has(id)} onChange={() => toggleOne(id)} className="h-4 w-4 rounded border-input text-primary" /></td>}
                  {columns.map((c) => (<td key={c.key} className={`${pad} ${c.align === "right" ? "text-right" : c.align === "center" ? "text-center" : ""} ${(c.type === "number" || c.align === "right") ? "whitespace-nowrap tabular-nums" : ""} ${c.className || "text-foreground/70"}`}>{c.cell ? c.cell(r) : getVal(c, r)}</td>))}
                  {actions && <td className={`${pad} text-right`}><div className="flex justify-end gap-0.5">{actions(r)}</div></td>}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {/* Rodapé de totais: acompanha o que está FILTRADO na tela (não o total bruto da base). */}
      {rodape && <div className="border-t border-border bg-secondary/35 px-4 py-2.5">{typeof rodape === "function" ? rodape(sorted) : rodape}</div>}
      <div className="flex flex-wrap items-center justify-between gap-2 border-t border-border/60 px-4 py-2.5 text-xs text-muted-foreground">
        <span>{sorted.length} registro(s){sorted.length !== rows.length ? ` (de ${rows.length})` : ""}</span>
        {totalPages > 1 && (
          <div className="flex items-center gap-1">
            <button onClick={() => setPage(1)} disabled={curPage === 1} className="rounded p-1 hover:bg-secondary disabled:opacity-30"><ChevronsLeft size={15} /></button>
            <button onClick={() => setPage((p) => Math.max(1, p - 1))} disabled={curPage === 1} className="rounded p-1 hover:bg-secondary disabled:opacity-30"><ChevronLeft size={15} /></button>
            <span className="px-2 font-medium text-foreground/70">Página {curPage} de {totalPages}</span>
            <button onClick={() => setPage((p) => Math.min(totalPages, p + 1))} disabled={curPage === totalPages} className="rounded p-1 hover:bg-secondary disabled:opacity-30"><ChevronRight size={15} /></button>
            <button onClick={() => setPage(totalPages)} disabled={curPage === totalPages} className="rounded p-1 hover:bg-secondary disabled:opacity-30"><ChevronsRight size={15} /></button>
          </div>
        )}
      </div>
    </Card>
  );
}
const RowActions = ({ onView, onEdit, onDelete, extra }) => (
  <>
    {onView && <IconBtn icon={Eye} title="Visualizar" onClick={onView} />}
    {onEdit && <IconBtn icon={Pencil} title="Editar" onClick={onEdit} />}
    {extra}
    {onDelete && <IconBtn icon={Trash2} title="Excluir" tone="danger" onClick={onDelete} />}
  </>
);
function MoreMenu({ children }) {
  const [open, setOpen] = useState(false);
  useEffect(() => { if (!open) return; const h = () => setOpen(false); window.addEventListener("click", h); return () => window.removeEventListener("click", h); }, [open]);
  return (
    <div className="relative inline-block" onClick={(e) => e.stopPropagation()}>
      <IconBtn icon={MoreHorizontal} title="Mais opções" onClick={() => setOpen((o) => !o)} />
      {open && <div className="absolute right-0 z-20 mt-1 w-44 overflow-hidden rounded-md border border-border bg-card py-1 shadow-lg" onClick={() => setOpen(false)}>{children}</div>}
    </div>
  );
}
const MoreItem = ({ icon: Icon, children, onClick, danger }) => (
  <button onClick={onClick} className={`flex w-full items-center gap-2 px-3 py-1.5 text-left text-sm ${danger ? "text-destructive hover:bg-destructive/8" : "text-foreground/80 hover:bg-secondary/50"}`}>{Icon && <Icon size={14} />}{children}</button>
);

/* ==================================================================
   SHELL — Sidebar por categorias (recolhível) + Header fixo
   ================================================================== */
const NAV = [
  { item: { id: "dashboard", label: "Dashboard", icon: LayoutDashboard } },
  { grupo: "RH", itens: [
    { id: "funcionarios", label: "Funcionários", icon: Users },
    { id: "recrutamento", label: "Recrutamento", icon: Briefcase },
    { id: "atestados", label: "Atestados e Faltas", icon: Stethoscope },
  ]},
  { grupo: "Financeiro", itens: [
    { id: "pagamentos", label: "Folha de Pagamento", icon: Banknote },
  ]},
  { grupo: "Relatórios", itens: [
    { id: "indicadores", label: "Indicadores", icon: BarChart3 },
    { id: "relatorios", label: "Relatórios", icon: FileText },
  ]},
  { item: { id: "config", label: "Configurações", icon: Settings } },
];
const FLAT_NAV = NAV.flatMap((s) => (s.item ? [s.item] : s.itens));

// Submenus internos de cada modulo (navegacao fixa a esquerda do conteudo).
const MODULES = {
  funcionarios: [
    { id: "lista", label: "Lista de funcionários", icon: Users },
    { id: "treinamento", label: "Treinamento", icon: CalendarClock },
    { id: "turmas", label: "Turmas de Treinamento", icon: GraduationCap },
    { id: "documentos", label: "Documentos", icon: FolderCheck },
  ],
  recrutamento: [
    { id: "candidatos", label: "Candidatos", icon: Users },
    { id: "agenda", label: "Agenda e Entrevistas", icon: CalendarRange },
    { id: "talentos", label: "Banco de Talentos", icon: Star },
    { id: "roteiro", label: "Roteiro", icon: FileText },
  ],
  pagamentos: [
    { id: "demonstrativos", label: "Extrato Mensal", icon: ClipboardList },
    { id: "folha", label: "Folha de Repasse", icon: Banknote },
    { id: "diario", label: "Pagamento Diário", icon: Wallet },
    { id: "treinamento", label: "Proc. Treinamento", icon: GraduationCap },
    { id: "beneficios", label: "Benefícios", icon: Gift },
    { id: "rescisoes", label: "Rescisões", icon: LogOut },
  ],
};
const MODULE_LABEL = { funcionarios: "Funcionários", recrutamento: "Recrutamento", pagamentos: "Folha de Pagamento", atestados: "Atestados e Faltas" };
// Perfis de acesso: definem quais módulos (abas) aparecem no menu. Sem perfil = admin (vê tudo).
// RH e Financeiro: operadores — veem tudo MENOS Configurações; podem apagar, mas não reabrir (só admin).
const MODULOS_OPERADOR = ["dashboard", "funcionarios", "recrutamento", "atestados", "pagamentos", "indicadores", "relatorios"];
const PERFIS = {
  recrutamento: ["dashboard", "recrutamento"],
  rh: MODULOS_OPERADOR,
  financeiro: MODULOS_OPERADOR,
};
const subPadrao = (aba) => (MODULES[aba] ? MODULES[aba][0].id : "");

// Submenu interno fixo: navega dentro do modulo enquanto so o conteudo a direita rola.
function SubNav({ modulo, sub, setSub }) {
  const itens = MODULES[modulo];
  if (!itens) return null;
  return (
    <aside className="hidden w-52 shrink-0 lg:block">
      <div className="sticky top-[4.5rem]">
        <p className="mb-2 px-2.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/80">{MODULE_LABEL[modulo]}</p>
        <nav className="space-y-0.5">
          {itens.map((n) => n.children
            ? <SubNavGroup key={n.id} item={n} sub={sub} setSub={setSub} />
            : (
              <button key={n.id} onClick={() => setSub(n.id)}
                className={`group flex w-full items-center gap-2.5 rounded-md px-2.5 py-2 text-sm font-medium transition-colors ${sub === n.id ? "bg-primary/8 text-primary" : "text-foreground/70 hover:bg-secondary hover:text-foreground"}`}>
                <n.icon size={16} className={sub === n.id ? "text-primary" : "text-muted-foreground/80 group-hover:text-foreground/70"} />
                <span className="truncate">{n.label}</span>
              </button>
            ))}
        </nav>
      </div>
    </aside>
  );
}
// Item de submenu com filhos (acordeao). Abre sozinho quando um filho esta ativo; anima via grid-rows.
function SubNavGroup({ item, sub, setSub }) {
  const childActive = item.children.some((c) => c.id === sub);
  const [open, setOpen] = useState(childActive);
  useEffect(() => { if (childActive) setOpen(true); }, [childActive]);
  return (
    <div>
      <button onClick={() => { const willOpen = !open; setOpen(willOpen); if (willOpen && !childActive) setSub(item.children[0].id); }}
        className={`group flex w-full items-center gap-2.5 rounded-md px-2.5 py-2 text-sm font-medium transition-colors ${childActive ? "text-primary" : "text-foreground/70 hover:bg-secondary hover:text-foreground"}`}>
        <item.icon size={16} className={childActive ? "text-primary" : "text-muted-foreground/80 group-hover:text-foreground/70"} />
        <span className="truncate">{item.label}</span>
        <ChevronDown size={14} className={`ml-auto shrink-0 text-muted-foreground/80 transition-transform duration-200 ${open ? "rotate-180" : ""}`} />
      </button>
      <div className={`grid transition-all duration-200 ease-in-out ${open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"}`}>
        <div className="overflow-hidden">
          <div className="ml-3 mt-0.5 space-y-0.5 border-l border-border pl-2.5">
            {item.children.map((c) => (
              <button key={c.id} onClick={() => setSub(c.id)}
                className={`group flex w-full items-center gap-2 rounded-md px-2.5 py-1.5 text-sm transition-colors ${sub === c.id ? "bg-primary/8 font-medium text-primary" : "text-muted-foreground hover:bg-secondary hover:text-foreground"}`}>
                <c.icon size={14} className={sub === c.id ? "text-primary" : "text-muted-foreground/80 group-hover:text-foreground/70"} />
                <span className="truncate">{c.label}</span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
// Submenu compacto em pilulas para telas menores (rola horizontalmente).
function SubNavMobile({ modulo, sub, setSub }) {
  const itens = MODULES[modulo];
  if (!itens) return null;
  return (
    <div className="mb-4 flex gap-1.5 overflow-x-auto pb-1 lg:hidden">
      {itens.flatMap((n) => n.children ? n.children : [n]).map((n) => {
        const active = sub === n.id;
        return (
          <button key={n.id} onClick={() => setSub(n.id)}
            className={`inline-flex shrink-0 items-center gap-1.5 rounded-full border px-3 py-1.5 text-sm font-medium ${active ? "border-primary/30 bg-primary/8 text-primary" : "border-border bg-card text-foreground/70"}`}>
            <n.icon size={14} />{n.label}
          </button>
        );
      })}
    </div>
  );
}

function SidebarNav({ aba, sub, irPara, collapsed, permitidos, navBase = NAV }) {
  // Item pode ter só `id` (módulo) ou `aba`+`sub` (etapa interna que vira item de menu).
  const ok = (n) => !permitidos || permitidos.includes(n.aba || n.id);
  const Item = ({ n }) => {
    const alvo = n.aba || n.id;
    const active = aba === alvo && (n.sub ? sub === n.sub : !n.aba);
    return (
      <button onClick={() => irPara(alvo, n.sub)} title={collapsed ? n.label : undefined}
        className={`group flex w-full items-center gap-3 rounded-md px-2.5 py-2 text-sm font-medium transition-colors ${collapsed ? "justify-center" : ""} ${active ? "bg-primary/8 text-primary" : "text-foreground/70 hover:bg-secondary hover:text-foreground"}`}>
        <n.icon size={18} className={active ? "text-primary" : "text-muted-foreground/80 group-hover:text-foreground/70"} />
        {!collapsed && <span className="truncate">{n.label}</span>}
      </button>
    );
  };
  // Filtra os itens/grupos conforme o perfil (esconde grupos que ficaram vazios).
  const nav = navBase.map((sec) => sec.item ? (ok(sec.item) ? sec : null) : { ...sec, itens: sec.itens.filter((n) => ok(n)) })
    .filter((sec) => sec && (sec.item || sec.itens.length));
  return (
    <nav className="flex-1 space-y-1 overflow-y-auto px-3 py-3">
      {nav.map((sec, i) => sec.item ? <Item key={sec.item.id} n={sec.item} /> : (
        <div key={sec.grupo} className={i > 0 ? "pt-3" : ""}>
          {!collapsed && <p className="px-2.5 pb-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/80">{sec.grupo}</p>}
          {collapsed && i > 0 && <div className="mx-2 mb-2 border-t border-border/60" />}
          <div className="space-y-0.5">{sec.itens.map((n) => <Item key={n.id} n={n} />)}</div>
        </div>
      ))}
    </nav>
  );
}

function HeaderBar({ secLabel, onToggleSidebar, onToggleMobile, notificacoes, irPara, abrirNotificacao, globalQuery, setGlobalQuery, nomeUsuario = "Administrador", empresaPermitida = "", onSair, mostrarBusca = true, podeConfig = true }) {
  const [q, setQ] = useState(globalQuery || "");
  const [openN, setOpenN] = useState(false);
  const [openU, setOpenU] = useState(false);
  useEffect(() => { const h = () => { setOpenN(false); setOpenU(false); }; window.addEventListener("click", h); return () => window.removeEventListener("click", h); }, []);
  const toneCls = { red: "text-destructive", amber: "text-warning", blue: "text-primary", slate: "text-muted-foreground/80" };
  return (
    <header className="sticky top-0 z-30 flex h-14 items-center gap-3 border-b border-border bg-card px-3 md:px-5">
      <button onClick={onToggleMobile} className="rounded-md p-2 text-muted-foreground hover:bg-secondary md:hidden"><Menu size={18} /></button>
      <button onClick={onToggleSidebar} className="hidden rounded-md p-2 text-muted-foreground hover:bg-secondary md:block" title="Recolher menu"><Menu size={18} /></button>
      <div className="hidden items-center gap-2 md:flex">
        <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary text-white"><Building2 size={15} /></div>
        <div className="leading-tight"><p className="text-sm font-semibold text-foreground">Grupo Zaytan</p><p className="text-[11px] text-muted-foreground/80">{secLabel}</p></div>
      </div>
      {mostrarBusca ? (
        <div className="relative mx-auto w-full max-w-md">
          <Search size={15} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground/80" />
          <input value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") { setGlobalQuery(q); irPara("funcionarios", "lista"); } }}
            placeholder="Pesquisa global (funcionários)..." className="w-full rounded-md border border-border bg-secondary/50 py-2 pl-9 pr-3 text-sm outline-none focus:border-primary/70 focus:bg-card focus:ring-2 focus:ring-primary/15" />
        </div>
      ) : <div className="flex-1" />}
      <div className="relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={() => { setOpenN((o) => !o); setOpenU(false); }} className="relative rounded-md p-2 text-muted-foreground hover:bg-secondary"><Bell size={18} />{notificacoes.length > 0 && <span className="absolute right-1 top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-destructive px-1 text-[10px] font-bold text-white">{notificacoes.length}</span>}</button>
        {openN && (
          <div className="absolute right-0 z-40 mt-1 w-80 overflow-hidden rounded-lg border border-border bg-card shadow-xl">
            <div className="border-b border-border/60 px-4 py-2.5 text-sm font-semibold text-foreground/80">Notificações</div>
            <div className="max-h-80 overflow-y-auto">{notificacoes.length === 0 ? <p className="px-4 py-6 text-center text-sm text-muted-foreground/80">Nada pendente.</p> : notificacoes.map((n) => (
              <button key={n.id} onClick={() => { abrirNotificacao ? abrirNotificacao(n) : irPara(n.aba, n.subId); setOpenN(false); }} className="flex w-full items-start gap-2.5 border-b border-border/40 px-4 py-2.5 text-left hover:bg-secondary/50">
                <AlertTriangle size={15} className={`mt-0.5 shrink-0 ${toneCls[n.tone] || "text-muted-foreground/80"}`} />
                <span><span className="block text-sm text-foreground/80">{n.texto}</span>{n.sub && <span className="block text-xs text-muted-foreground/80">{n.sub}</span>}</span>
              </button>
            ))}</div>
          </div>
        )}
      </div>
      {podeConfig && <button onClick={() => irPara("config")} className="rounded-md p-2 text-muted-foreground hover:bg-secondary" title="Configurações"><Settings size={18} /></button>}
      <div className="relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={() => { setOpenU((o) => !o); setOpenN(false); }} className="flex items-center gap-2 rounded-md p-1 pr-2 hover:bg-secondary">
          <span className="flex h-8 w-8 items-center justify-center rounded-full bg-foreground/80 text-xs font-semibold text-white">{(nomeUsuario[0] || "U").toUpperCase()}</span>
          <span className="hidden text-left leading-tight md:block"><span className="block max-w-[160px] truncate text-sm font-medium text-foreground/80">{nomeUsuario}</span><span className="block text-[11px] text-muted-foreground/80">{empresaPermitida ? empresaPermitida : "Acesso total"}</span></span>
          <ChevronDown size={14} className="hidden text-muted-foreground/80 md:block" />
        </button>
        {openU && (
          <div className="absolute right-0 z-40 mt-1 w-56 overflow-hidden rounded-lg border border-border bg-card py-1 shadow-xl">
            <div className="border-b border-border/60 px-4 py-2"><p className="truncate text-sm font-medium text-foreground/80">{nomeUsuario}</p><p className="text-xs text-muted-foreground/80">{empresaPermitida ? "Acesso: " + empresaPermitida : "Acesso total"}</p></div>
            {podeConfig && <button onClick={() => { irPara("config"); setOpenU(false); }} className="flex w-full items-center gap-2 px-4 py-2 text-left text-sm text-foreground/80 hover:bg-secondary/50"><Settings size={14} /> Configurações</button>}
            <button onClick={() => onSair && onSair()} className="flex w-full items-center gap-2 px-4 py-2 text-left text-sm text-destructive hover:bg-destructive/8"><LogOut size={14} /> Sair</button>
          </div>
        )}
      </div>
    </header>
  );
}

// Barra do RH dentro do shell unificado: abas da seção (vindas da rota), busca global de
// funcionários, notificações do RH e o status de gravação — o que antes vivia no HeaderBar.
function BarraRh({ abas, notificacoes, abrirNotificacao, irPara, globalQuery, setGlobalQuery, mostrarBusca, storageOk }) {
  const [q, setQ] = useState(globalQuery || "");
  const [openN, setOpenN] = useState(false);
  useEffect(() => { const h = () => setOpenN(false); window.addEventListener("click", h); return () => window.removeEventListener("click", h); }, []);
  const toneCls = { red: "text-destructive", amber: "text-warning-ink", blue: "text-primary", slate: "text-muted-foreground" };
  return (
    <div className="flex flex-wrap items-center gap-3">
      <div className="min-w-0 flex-1">{abas}</div>
      {mostrarBusca && (
        <div className="relative w-full sm:w-64">
          <Search size={15} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <input value={q} onChange={(e) => setQ(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") { setGlobalQuery(q); irPara("funcionarios", "lista"); } }}
            placeholder="Buscar funcionário (Enter)" className="h-9 w-full rounded-md border border-transparent bg-secondary/60 pl-9 pr-3 text-sm outline-none focus:border-input focus:bg-card" />
        </div>
      )}
      <div className="relative" onClick={(e) => e.stopPropagation()}>
        <button onClick={() => setOpenN((o) => !o)} title="Notificações do RH" className="relative grid h-9 w-9 cursor-pointer place-items-center rounded-lg text-muted-foreground hover:bg-secondary hover:text-foreground">
          <Bell size={18} strokeWidth={1.6} />
          {notificacoes.length > 0 && <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-4 items-center justify-center rounded-full bg-primary px-1 text-[10px] font-semibold text-primary-foreground tabular-nums">{notificacoes.length}</span>}
        </button>
        {openN && (
          <div className="absolute right-0 z-40 mt-1 w-80 overflow-hidden rounded-xl border border-border bg-popover shadow-xl">
            <div className="border-b border-border/60 px-4 py-2.5 text-sm font-semibold text-foreground">Notificações do RH</div>
            <div className="max-h-80 overflow-y-auto">{notificacoes.length === 0 ? <p className="px-4 py-6 text-center text-sm text-muted-foreground">Nada pendente.</p> : notificacoes.map((n) => (
              <button key={n.id} onClick={() => { abrirNotificacao(n); setOpenN(false); }} className="flex w-full cursor-pointer items-start gap-2.5 border-b border-border/40 px-4 py-2.5 text-left hover:bg-secondary/50">
                <AlertTriangle size={15} className={`mt-0.5 shrink-0 ${toneCls[n.tone] || "text-muted-foreground"}`} />
                <span><span className="block text-sm text-foreground">{n.texto}</span>{n.sub && <span className="block text-xs text-muted-foreground">{n.sub}</span>}</span>
              </button>
            ))}</div>
          </div>
        )}
      </div>
      <span title={storageOk ? "As alterações do RH são gravadas automaticamente" : "Falha ao gravar: as alterações ficam só nesta sessão"}
        className={`hidden items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-medium md:inline-flex ${storageOk ? "bg-success/10 text-success" : "bg-destructive/10 text-destructive"}`}>
        <span className={`h-1.5 w-1.5 rounded-full ${storageOk ? "bg-success" : "bg-destructive"}`} />{storageOk ? "Salvo automaticamente" : "Somente nesta sessão"}
      </span>
    </div>
  );
}

// `embutido`: o RH roda dentro do shell unificado (Zaytan Hub). Nesse modo o módulo/sub-aba
// vêm da ROTA (abaExterna/subExterna) e toda navegação interna vira navegação de rota
// (onNavegar). Sem `embutido`, o comportamento é o do CRM RH original (menu próprio).
export default function App({ usuario, onSair, embutido = false, abaExterna, subExterna, onNavegar, abasSlot, empresas }) {
  if (embutido) usarEmpresasDoCadastro(empresas);
  // Acesso por empresa: se o usuário tiver "empresa" definida no metadata, ele só enxerga essa empresa.
  // app_metadata PRIMEIRO: user_metadata é editável pelo próprio usuário (auth.updateUser), então não
  // pode mandar em acesso. Quem define perfil/empresa grava em app_metadata (painel do Supabase).
  const empresaPermitida = usuario?.app_metadata?.empresa || usuario?.user_metadata?.empresa || "";
  const nomeUsuario = usuario?.user_metadata?.nome || usuario?.email || "Administrador";
  // Acesso por perfil: limita quais módulos aparecem no menu. Sem perfil = admin (vê tudo).
  const perfil = usuario?.app_metadata?.perfil || usuario?.user_metadata?.perfil || "";
  // Sem perfil = admin (vê tudo). Perfil DESCONHECIDO falha FECHADO (só dashboard), nunca aberto.
  const modulosPermitidos = !perfil ? null : (PERFIS[perfil] || ["dashboard"]);
  const isAdmin = !perfil; // sem perfil = administrador: acesso total, inclusive reabrir/desfazer
  const podeVer = (a) => !modulosPermitidos || modulosPermitidos.includes(a);
  const [abaInterna, setAbaInterna] = useState("dashboard");
  const [subInterna, setSubInterna] = useState("");
  const aba = embutido ? (abaExterna || "dashboard") : abaInterna;
  const sub = embutido ? (subExterna || subPadrao(aba)) : subInterna;
  const setSub = embutido ? (s) => onNavegar && onNavegar(aba, s) : setSubInterna;
  // Área de recrutamento em foco: fica aqui (e não dentro do Recrutamento) para que o
  // Dashboard consiga abrir o Kanban já filtrado ao clicar numa área.
  const [areaFoco, setAreaFoco] = useState("Todas");
  // Filtro inicial para abrir a tela Funcionários já filtrada a partir dos KPIs do Dashboard.
  const [funcFiltroInicial, setFuncFiltroInicial] = useState(null);
  // Aba de Beneficios a abrir (atalho do Dashboard: "vt" | "vr" | "vale" | "geral").
  const [beneficioFoco, setBeneficioFoco] = useState("");
  // Abrir o cadastro de um funcionário numa aba específica (a partir de uma notificação).
  const [abrirFunc, setAbrirFunc] = useState(null); // { id, view: 'form'|'docs', tab }
  const [collapsed, setCollapsed] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [globalQuery, setGlobalQuery] = useState("");
  const [loaded, setLoaded] = useState(false);
  const [storageOk, setStorageOk] = useState(true);
  const [funcionarios, setFuncionarios] = useState([]);
  const [candidatos, setCandidatos] = useState([]);
  const [pagamentos, setPagamentos] = useState([]);
  const [documentos, setDocumentos] = useState([]);
  const [atestados, setAtestados] = useState([]);
  const [perguntas, setPerguntas] = useState(PERGUNTAS_PADRAO);
  const [treinamentos, setTreinamentos] = useState([]);   // turmas de treinamento (custo por turma)
  const [pagamentosDiarios, setPagamentosDiarios] = useState([]); // pagamentos avulsos (Pix/dinheiro, sem competência)
  const [config, setConfig] = useState(CONFIG_PADRAO);
  const [folhasDP, setFolhasDP] = useState([]); // folhas importadas (tabelas folhas/folha_itens) — só leitura na tela
  // "Abrir na Folha de Repasse" a partir do Extrato Mensal: competência + CPF de quem abrir lá.
  const [repasseFoco, setRepasseFoco] = useState(null);
  const dirtyRef = useRef(false); // true quando há mudanças locais ainda não gravadas no Supabase
  const modoRef = useRef("legacy"); // "tabelas" quando as tabelas separadas existem; senão usa app_state
  const prevIdsRef = useRef({ funcionarios: new Set(), candidatos: new Set(), pagamentos: new Set(), documentos: new Set(), atestados: new Set(), perguntas: new Set(), treinamentos: new Set(), pagamentosDiarios: new Set() });
  // Último objeto enviado de cada registro (por tabela): o que não mudou não é reenviado.
  const enviadosRef = useRef({});

  useEffect(() => {
    let m = true;
    const aplicar = (d) => {
      // Migra nomenclatura de cargos (ex.: "Vendedor" -> "Atendente de Negócio") nos
      // cadastros existentes, ao carregar. Persiste sozinho no próximo salvamento.
      const fun = (d.funcionarios || []).map(normalizeFunc).map((f) => ({ ...f, cargo: renomearCargo(f.cargo) }));
      setFuncionarios(fun);
      // Banco de Talentos agora é definido por AVALIAÇÃO (>= 4 estrelas), não mais por estar
      // em "Qualificados". Migra os cadastros antigos: quem não tem 4+ estrelas sai do banco.
      const cands = (d.candidatos || []).map((c) => ({ ...c, bancoTalentos: num(c.estrelas) >= 4 }));
      setCandidatos(cands);
      setPagamentos(d.pagamentos || []);
      setDocumentos(d.documentos || []);
      setAtestados(d.atestados || []);
      setPerguntas(d.perguntas && d.perguntas.length ? d.perguntas : PERGUNTAS_PADRAO);
      setTreinamentos(d.treinamentos || []);
      setPagamentosDiarios(d.pagamentosDiarios || []);
      const cfg = { ...CONFIG_PADRAO, ...(d.config || {}) };
      cfg.cargos = migrarListaCargos(cfg.cargos); // renomeia e remove cargos aposentados da lista
      if (cfg.salariosPorCargo) { const sp = {}; Object.entries(cfg.salariosPorCargo).forEach(([k, v]) => { const nk = renomearCargo(k); if (!CARGO_REMOVER.has(nk)) sp[nk] = v; }); cfg.salariosPorCargo = sp; }
      setConfig(cfg);
      prevIdsRef.current = {
        funcionarios: new Set(fun.map((x) => x.id)),
        candidatos: new Set((d.candidatos || []).map((x) => x.id)),
        pagamentos: new Set((d.pagamentos || []).map((x) => x.id)),
        documentos: new Set((d.documentos || []).map((x) => x.id)),
        atestados: new Set((d.atestados || []).map((x) => x.id)),
        perguntas: new Set((d.perguntas || []).map((x) => x.id)),
        treinamentos: new Set((d.treinamentos || []).map((x) => x.id)),
        pagamentosDiarios: new Set((d.pagamentosDiarios || []).map((x) => x.id)),
      };
      // O que ACABOU de vir do banco já está gravado: guardar a identidade de cada objeto para o
      // próximo salvamento mandar só o que o usuário realmente mexeu (e não reescrever, com dados
      // velhos, o que outra aba/pessoa gravou enquanto isso).
      const porId = (lista) => new Map((lista || []).map((x) => [x.id, x]));
      enviadosRef.current = {
        funcionarios: porId(fun), candidatos: porId(cands), pagamentos: porId(d.pagamentos),
        documentos: porId(d.documentos), atestados: porId(d.atestados), perguntas: porId(d.perguntas),
        treinamentos: porId(d.treinamentos), pagamentos_diarios: porId(d.pagamentosDiarios),
      };
    };
    // Carrega das TABELAS separadas; se elas ainda não existirem, cai no app_state (modo legado).
    const carregarTabelas = async () => {
      const sel = (t) => supabase.from(t).select("data");
      const [f, c, p, dc, at, pq] = await Promise.all([sel("funcionarios"), sel("candidatos"), sel("pagamentos"), sel("documentos"), sel("atestados"), sel("perguntas")]);
      const cfg = await supabase.from("config").select("data").eq("id", 1).maybeSingle();
      const err = f.error || c.error || p.error || dc.error || at.error || pq.error || cfg.error;
      if (err) throw err;
      // Turmas de treinamento: tabela nova. Se ela ainda não existir no banco, o app segue
      // funcionando normalmente (lista vazia) em vez de cair inteiro para o modo legado.
      let treinamentos = [];
      try { const tr = await sel("treinamentos"); if (!tr.error) treinamentos = (tr.data || []).map((r) => r.data); } catch (_) {}
      // Pagamentos avulsos: tabela nova. Se ainda não existir no banco, o app segue
      // funcionando normalmente (lista vazia) em vez de cair inteiro para o modo legado.
      let pagamentosDiarios = [];
      try { const pd = await sel("pagamentos_diarios"); if (!pd.error) pagamentosDiarios = (pd.data || []).map((r) => r.data); } catch (_) {}
      return {
        funcionarios: (f.data || []).map((r) => r.data), candidatos: (c.data || []).map((r) => r.data),
        pagamentos: (p.data || []).map((r) => r.data), documentos: (dc.data || []).map((r) => r.data),
        atestados: (at.data || []).map((r) => r.data), perguntas: (pq.data || []).map((r) => r.data),
        treinamentos, pagamentosDiarios, config: cfg.data ? cfg.data.data : {},
      };
    };
    const carregarLegacy = async () => {
      const { data, error } = await supabase.from("app_state").select("data").eq("id", 1).maybeSingle();
      if (error) throw error;
      return data && data.data ? data.data : {};
    };
    const carregar = async () => {
      let estado, modo;
      try { estado = await carregarTabelas(); modo = "tabelas"; }
      catch { estado = await carregarLegacy(); modo = "legacy"; }
      modoRef.current = modo;
      if (m && !dirtyRef.current) aplicar(estado);
    };
    (async () => {
      try { await carregar(); setStorageOk(true); }
      catch (e) { if (m) setStorageOk(false); }
      finally { if (m) setLoaded(true); }
    })();
    const onFocus = () => { if (dirtyRef.current) return; carregar().catch(() => {}); };
    window.addEventListener("focus", onFocus);
    return () => { m = false; window.removeEventListener("focus", onFocus); };
  }, []);
  useEffect(() => {
    if (!loaded) return;
    dirtyRef.current = true; // há mudança local ainda não persistida
    const t = setTimeout(async () => {
      try {
        const docsMeta = documentos.map(({ dataUrl, ...meta }) => meta);
        if (modoRef.current === "tabelas") {
          const funcById = {}; funcionarios.forEach((f) => { funcById[f.id] = f; });
          const empDe = (id) => funcById[id]?.empresa || "";
          const prev = prevIdsRef.current;
          // Sincroniza uma tabela: apaga só os que sumiram e faz upsert só do que MUDOU.
          // Reenviar a tabela inteira a cada mudança fazia uma aba aberta há horas sobrescrever, com
          // dados velhos, o que outra aba tinha acabado de gravar. Como o estado é imutável, o objeto
          // só muda de identidade quando alguém mexeu nele — é esse o critério.
          const sync = async (tabela, itens, extrair) => {
            const atuais = new Set(itens.map((i) => i.id));
            const removidos = [...(prev[tabela] || new Set())].filter((id) => !atuais.has(id));
            if (removidos.length) { const r = await supabase.from(tabela).delete().in("id", removidos); if (r.error) throw r.error; }
            const enviados = enviadosRef.current[tabela];
            const mudaram = enviados ? itens.filter((i) => enviados.get(i.id) !== i) : itens;
            for (let i = 0; i < mudaram.length; i += 400) { const r = await supabase.from(tabela).upsert(mudaram.slice(i, i + 400).map(extrair)); if (r.error) throw r.error; }
            enviadosRef.current[tabela] = new Map(itens.map((i) => [i.id, i]));
            prev[tabela] = atuais;
          };
          await sync("funcionarios", funcionarios, (f) => ({ id: f.id, nome: f.nome || "", empresa: f.empresa || "", cargo: f.cargo || "", departamento: f.departamento || "", status: f.status || "", data: f, updated_at: new Date().toISOString() }));
          await sync("candidatos", candidatos, (c) => ({ id: c.id, nome: c.nome || "", empresa: c.empresa || "", telefone: c.telefone || "", area: areaDe(c), vaga: c.vaga || "", origem: c.origem || "", status: c.status || "", data: c, updated_at: new Date().toISOString() }));
          await sync("pagamentos", pagamentos, (p) => ({ id: p.id, funcionario_id: p.funcionarioId || "", empresa: empDe(p.funcionarioId) || p.empresa || "", competencia: p.competencia || "", tipo: p.tipo || "", valor: num(p.valor), data: p, updated_at: new Date().toISOString() }));
          await sync("documentos", docsMeta, (d) => ({ id: d.id, func_id: d.funcId || "", empresa: empDe(d.funcId) || "", categoria: d.categoria || "", data: d, updated_at: new Date().toISOString() }));
          await sync("atestados", atestados, (a) => ({ id: a.id, func_id: a.funcId || "", empresa: empDe(a.funcId) || "", tipo: a.tipo || "", data: a, updated_at: new Date().toISOString() }));
          await sync("perguntas", perguntas, (q) => ({ id: q.id, data: q }));
          // Turmas: se a tabela ainda não existe no banco, a falha fica isolada aqui e não
          // derruba o salvamento do resto (funcionários, folha, etc.).
          try { await sync("treinamentos", treinamentos, (t) => ({ id: t.id, nome: t.nome || "", empresa: t.empresa || "", data_inicio: t.dataInicio || null, data: t, updated_at: new Date().toISOString() })); } catch (_) {}
          // Pagamentos avulsos: mesma tolerância — se a tabela ainda não existe no banco, não
          // derruba o salvamento do resto.
          try { await sync("pagamentos_diarios", pagamentosDiarios, (p) => ({ id: p.id, data_pagamento: p.dataPagamento || null, empresa: p.empresa || "", pessoa: p.pessoa || "", valor: num(p.valor), data: p, updated_at: new Date().toISOString() })); } catch (_) {}
          const rc = await supabase.from("config").upsert({ id: 1, data: config }); if (rc.error) throw rc.error;
        } else {
          const payload = { funcionarios, candidatos, pagamentos, documentos: docsMeta, atestados, perguntas, treinamentos, pagamentosDiarios, config };
          const { error } = await supabase.from("app_state").upsert({ id: 1, data: payload, updated_at: new Date().toISOString() });
          if (error) throw error;
        }
        dirtyRef.current = false; // gravado com sucesso
        setStorageOk(true);
      } catch (e) { setStorageOk(false); }
    }, 800);
    return () => clearTimeout(t);
  }, [funcionarios, candidatos, pagamentos, documentos, atestados, perguntas, treinamentos, pagamentosDiarios, config, loaded]);

  // Folha (DP): carrega as folhas importadas do Supabase. O n8n grava; a tela só apresenta.
  const recarregarFolhas = useCallback(async () => {
    try {
      const [fh, it] = await Promise.all([
        supabase.from("folhas").select("*").order("competencia", { ascending: false }),
        supabase.from("folha_itens").select("*"),
      ]);
      if (fh.error || it.error) return;
      const porFolha = {};
      (it.data || []).forEach((i) => { (porFolha[i.folha_id] = porFolha[i.folha_id] || []).push(i); });
      setFolhasDP((fh.data || []).map((f) => ({ ...f, itens: (porFolha[f.id] || []).sort((a, b) => (a.ordem ?? 0) - (b.ordem ?? 0)) })));
    } catch { /* tabelas de folha podem ainda não existir */ }
  }, []);
  useEffect(() => { recarregarFolhas(); }, [recarregarFolhas]);

  const atualizarFunc = (id, patch) => setFuncionarios((p) => p.map((f) => (f.id === id ? { ...f, ...patch } : f)));
  // Escopo por empresa (quando o usuário é restrito a uma empresa) + ORDEM ALFABÉTICA por nome na
  // fonte única — propaga a todas as telas, dropdowns e listas. Memoizado p/ manter a identidade
  // do array estável (views por data/urgência reordenam depois; a tabela permite reordenar por coluna).
  const funcionariosV = useMemo(() => (empresaPermitida ? funcionarios.filter((f) => (f.empresa || "") === empresaPermitida) : funcionarios).slice().sort(ordNome), [funcionarios, empresaPermitida]);
  const idsEmpresa = useMemo(() => new Set(funcionariosV.map((f) => f.id)), [funcionariosV]);
  const candidatosV = useMemo(() => (empresaPermitida ? candidatos.filter((c) => (c.empresa || "") === empresaPermitida) : candidatos).slice().sort(ordNome), [candidatos, empresaPermitida]);
  const pagamentosV = empresaPermitida ? pagamentos.filter((p) => idsEmpresa.has(p.funcionarioId)) : pagamentos;
  const atestadosV = empresaPermitida ? atestados.filter((a) => idsEmpresa.has(a.funcId)) : atestados;
  const documentosV = empresaPermitida ? documentos.filter((d) => idsEmpresa.has(d.funcId)) : documentos;
  const treinamentosV = empresaPermitida ? treinamentos.filter((t) => (t.empresa || "") === empresaPermitida) : treinamentos;
  const pagamentosDiariosV = empresaPermitida ? pagamentosDiarios.filter((p) => (p.empresa || "") === empresaPermitida) : pagamentosDiarios;
  const ativos = funcionariosV.filter((f) => f.status !== "Desligado");
  const secLabel = FLAT_NAV.find((n) => n.id === aba)?.label || "";
  // Navegação respeita o perfil: se tentar ir a um módulo não permitido, volta ao Dashboard.
  // irPara(modulo, submenu, area?) — o 3º parâmetro deixa o Dashboard abrir o Kanban já numa área.
  const irPara = (id, s, area) => {
    const alvo = podeVer(id) ? id : "dashboard";
    const novoSub = s || subPadrao(alvo);
    if (embutido) { if (onNavegar) onNavegar(alvo, novoSub); }
    else { setAbaInterna(alvo); setSubInterna(novoSub); }
    if (area) setAreaFoco(area);
    setMobileOpen(false);
  };
  // Clique numa notificação: se aponta um funcionário, abre o cadastro dele já na aba certa.
  const abrirNotificacao = (n) => {
    if (n.funcId) { setAbrirFunc({ id: n.funcId, view: n.view || "form", tab: n.tab || "pessoais" }); irPara("funcionarios"); }
    else irPara(n.aba, n.subId);
  };

  const notificacoes = useMemo(() => {
    const out = [];
    // Entrevistas pendentes (agendadas, data já passou, card ainda em "Entrevista Agendada").
    // Aparece para o admin E para o perfil de recrutamento — é uma pendência do processo seletivo.
    const entPend = candidatosV.filter(candTemEntrevistaPendente).length;
    if (entPend) out.push({ id: "entpend", texto: `${entPend} entrevista(s) pendente(s) de atualização`, sub: "Recrutamento · mova o card ou registre o resultado no Kanban", aba: "recrutamento", subId: "candidatos", tone: "red" });
    if (perfil === "recrutamento") return out; // recrutamento: só alertas de recrutamento (RH/Financeiro veem tudo)
    ativos.forEach((f) => { const t = calcTreinamento(f); if (t && t.emTreinamento && t.diasRestantes != null && t.diasRestantes <= 15) out.push({ id: "trein" + f.id, texto: t.diasRestantes < 0 ? `Treinamento de ${f.nome} terminou há ${Math.abs(t.diasRestantes)} dia(s)` : `Treinamento de ${f.nome} termina em ${t.diasRestantes} dia(s)`, sub: `${f.cargo || ""} · ${f.empresa}`, aba: "funcionarios", funcId: f.id, view: "form", tab: "contrato", tone: t.diasRestantes <= 1 ? "red" : "amber" }); });
    funcionariosV.forEach((f) => { const r = rescisaoPendente(f); if (r) out.push({ id: "resc" + f.id, texto: `Rescisão pendente de ${f.nome}`, sub: `${fmtBRL(r.valor)}${r.dataPagamento ? " · pagar em " + fmtData(r.dataPagamento) : ""}`, aba: "pagamentos", subId: "rescisoes", tone: "red" }); });
    const pagPend = pagamentosV.filter((p) => p.status === "Pendente" && p.origem !== "falta").length;   // descontos de falta não são repasses
    if (pagPend) out.push({ id: "pag", texto: `${pagPend} pagamento(s) pendente(s)`, sub: "Folha", aba: "pagamentos", subId: "folha", tone: "amber" });
    return out;
  }, [funcionariosV, pagamentosV, documentosV, candidatosV, config, modulosPermitidos]);

  const props = { funcionarios: funcionariosV, funcionariosTodos: funcionarios, setFuncionarios, ativos, atualizarFunc, config, setConfig, candidatos: candidatosV, setCandidatos, pagamentos: pagamentosV, setPagamentos, documentos: documentosV, setDocumentos, atestados: atestadosV, setAtestados, perguntas, setPerguntas, treinamentos: treinamentosV, setTreinamentos, pagamentosDiarios: pagamentosDiariosV, setPagamentosDiarios, setAba: irPara, sub, setSub, areaFoco, setAreaFoco, funcFiltroInicial, setFuncFiltroInicial, beneficioFoco, setBeneficioFoco, abrirFunc, setAbrirFunc, globalQuery, setGlobalQuery, empresaPermitida, restrito: perfil === "recrutamento", admin: isAdmin, nomeUsuario, perfil, repasseFoco, setRepasseFoco };

  const conteudo = () => {
    const dash = perfil === "recrutamento" ? <DashboardRecrutamento {...props} /> : <Dashboard {...props} />;
    if (!podeVer(aba)) return dash; // segurança: bloqueia módulos fora do perfil
    switch (aba) {
      case "dashboard": return dash;
      case "funcionarios":
        if (sub === "documentos") return <Documentos {...props} />;
        if (sub === "treinamento") return <Treinamento {...props} />;
        if (sub === "turmas") return <Turmas {...props} />;
        return <Funcionarios {...props} />;
      case "recrutamento":
        if (sub === "agenda") return <AgendaView {...props} />;
        if (sub === "roteiro") return <RoteiroEntrevista perguntas={perguntas} setPerguntas={setPerguntas} />;
        return <Recrutamento {...props} sub={sub} />;
      case "atestados": return <Atestados {...props} />;
      case "pagamentos":
        if (sub === "demonstrativos") return <FolhaDP folhas={folhasDP} recarregar={recarregarFolhas} empresaPermitida={empresaPermitida} nomeUsuario={nomeUsuario} funcionarios={funcionariosV} config={config} setConfig={setConfig} admin={isAdmin} perfil={perfil} irPara={irPara} setRepasseFoco={setRepasseFoco} />;
        if (sub === "diario") return <PagamentosDiarios {...props} />;
        if (sub === "treinamento") return <ProcessamentoTreino ativos={ativos} config={config} atualizarFunc={atualizarFunc} empresaPermitida={empresaPermitida} nomeUsuario={nomeUsuario} />;
        if (sub === "beneficios") return <Beneficios {...props} />;
        if (sub === "rescisoes") return <Rescisao {...props} />;
        return <Pagamentos {...props} />;
      case "indicadores": return <Indicadores {...props} />;
      case "relatorios": return <Relatorios {...props} />;
      case "config": return <Configuracoes {...props} />;
      default: return dash;
    }
  };
  // Etapas de Recrutamento como itens de barra lateral (Candidatos, Agenda e Entrevistas,
  // Banco de Talentos, Roteiro). Mesmo formato para o gerente e para o admin.
  const recGrupo = { grupo: "Recrutamento", itens: MODULES.recrutamento.map((m) => ({ id: "rec_" + m.id, label: m.label, icon: m.icon, aba: "recrutamento", sub: m.id })) };
  // Perfil "recrutamento" (gerente): só Dashboard + as etapas de Recrutamento na lateral.
  // Admin e demais perfis: menu completo, mas com Recrutamento também expandido na lateral
  // (igual ao gerente), em vez de um único item que abre o submenu no meio da tela.
  const navSidebar = perfil === "recrutamento"
    ? [
        { item: { id: "dashboard", label: "Dashboard", icon: LayoutDashboard } },
        recGrupo,
      ]
    : NAV.flatMap((sec) => {
        if (sec.itens && sec.itens.some((n) => n.id === "recrutamento")) {
          const semRec = sec.itens.filter((n) => n.id !== "recrutamento");
          return semRec.length ? [{ ...sec, itens: semRec }, recGrupo] : [recGrupo];
        }
        return [sec];
      });
  // Só a Folha (pagamentos) mantém o submenu no meio da tela; Recrutamento vive na barra lateral.
  const temSub = !!MODULES[aba] && aba !== "recrutamento";

  if (embutido) {
    return (
      <RhEmbutidoCtx.Provider value={true}>
        <div className="min-w-0">
          <BarraRh abas={abasSlot} notificacoes={notificacoes} abrirNotificacao={abrirNotificacao} irPara={irPara}
            globalQuery={globalQuery} setGlobalQuery={setGlobalQuery} mostrarBusca={perfil !== "recrutamento"} storageOk={storageOk} />
          {/* key: ao trocar a empresa no topo, só as telas recomeçam (filtros e formulários);
              os dados e o salvamento automático continuam neste componente. */}
          <div className="mt-5 min-w-0" key={empresaPermitida || "todas"}>
            {loaded ? conteudo() : <div className="flex items-center justify-center py-20 text-sm text-muted-foreground"><RefreshCw size={16} className="mr-2 animate-spin" />Carregando dados do RH…</div>}
          </div>
        </div>
      </RhEmbutidoCtx.Provider>
    );
  }

  return (
    <div className="flex min-h-screen bg-secondary/50 font-sans text-foreground antialiased">
      <style>{`html{scroll-behavior:smooth}`}</style>

      {/* Sidebar desktop */}
      <aside className={`sticky top-0 hidden h-screen shrink-0 flex-col border-r border-border bg-card transition-[width] duration-200 md:flex ${collapsed ? "w-16" : "w-60"}`}>
        <div className={`flex h-14 items-center border-b border-border/60 ${collapsed ? "justify-center px-2" : "px-4"}`}>
          <div className="flex items-center gap-2">{config.logo ? <img src={config.logo} alt="logo" className="h-8 w-8 rounded-md object-contain" /> : <div className="flex h-8 w-8 items-center justify-center rounded-md bg-primary text-white"><Building2 size={17} /></div>}{!collapsed && <div className="leading-tight"><p className="text-sm font-bold text-foreground">{config.nomeEmpresa || "Finance HUB"}</p><p className="text-[11px] text-muted-foreground/80">RH · Corporativo</p></div>}</div>
        </div>
        <SidebarNav aba={aba} sub={sub} irPara={irPara} collapsed={collapsed} permitidos={modulosPermitidos} navBase={navSidebar} />
        <div className={`border-t border-border/60 px-3 py-2.5 text-[11px] text-muted-foreground/80 ${collapsed ? "text-center" : ""}`}>{collapsed ? "•" : storageOk ? "Salvo automaticamente" : "Somente nesta sessão"}</div>
      </aside>

      {/* Drawer mobile */}
      {mobileOpen && (
        <div className="fixed inset-0 z-40 md:hidden">
          <div className="absolute inset-0 bg-foreground/50" onClick={() => setMobileOpen(false)} />
          <aside className="absolute inset-y-0 left-0 flex w-64 flex-col bg-card shadow-xl">
            <div className="flex h-14 items-center justify-between border-b border-border/60 px-4"><div className="flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-md bg-primary text-white"><Building2 size={17} /></div><p className="text-sm font-bold text-foreground">Finance HUB</p></div><button onClick={() => setMobileOpen(false)} className="rounded-md p-1.5 text-muted-foreground/80 hover:bg-secondary"><X size={18} /></button></div>
            <SidebarNav aba={aba} sub={sub} irPara={irPara} collapsed={false} permitidos={modulosPermitidos} navBase={navSidebar} />
          </aside>
        </div>
      )}

      <div className="flex min-w-0 flex-1 flex-col">
        <HeaderBar secLabel={secLabel} onToggleSidebar={() => setCollapsed((c) => !c)} onToggleMobile={() => setMobileOpen(true)} notificacoes={notificacoes} irPara={irPara} abrirNotificacao={abrirNotificacao} globalQuery={globalQuery} setGlobalQuery={setGlobalQuery} nomeUsuario={nomeUsuario} empresaPermitida={empresaPermitida} onSair={onSair} mostrarBusca={perfil !== "recrutamento"} podeConfig={podeVer("config")} />
        <main className="flex-1 overflow-x-clip">
          <div className={`mx-auto p-4 md:p-6 ${(collapsed || aba === "pagamentos") ? "max-w-none" : "max-w-screen-2xl"}`}>
            {temSub ? (
              <div className="flex gap-6">
                <SubNav modulo={aba} sub={sub} setSub={setSub} />
                <div className="min-w-0 flex-1">
                  <SubNavMobile modulo={aba} sub={sub} setSub={setSub} />
                  {conteudo()}
                </div>
              </div>
            ) : conteudo()}
          </div>
        </main>
      </div>
    </div>
  );
}

/* ==================================================================
   DASHBOARD — KPIs compactos + painéis objetivos
   ================================================================== */
function Dashboard({ funcionarios, ativos, config, pagamentos, documentos, candidatos, atestados = [], treinamentos = [], setAba, setFuncFiltroInicial = () => {}, setBeneficioFoco = () => {} }) {
  // Mês do painel: abre no atual. Muda os números do mês (contratações,
  // desligamentos, ausências, VT, VR, vale e custo); as listas de pendências
  // continuam mostrando o que está em aberto hoje.
  const [comp, setComp] = useState(compAtual);
  // Abre a lista de Funcionários já filtrada (o patch é mesclado a FILTRO_VAZIO na própria tela).
  const abrirFuncFiltro = (patch) => { setFuncFiltroInicial(patch); setAba("funcionarios"); };
  const ausenciasMes = atestados.filter((a) => (a.dataInicio || "").slice(0, 7) === comp).reduce((s, a) => s + atestadoDias(a), 0);
  const registrados = ativos.filter(isRegistrado);
  const naoRegistrados = ativos.filter((f) => !isRegistrado(f));
  const funcById = {}; funcionarios.forEach((f) => { funcById[f.id] = f; });
  const adm = funcionarios.filter((f) => (f.dataAdmissao || "").slice(0, 7) === comp).length;
  const desl = funcionarios.filter((f) => f.rescisao && (f.rescisao.dataDesligamento || "").slice(0, 7) === comp).length;
  const folha = ativos.reduce((s, f) => s + num(f.salarioBase), 0);
  const totVT = ativos.reduce((s, f) => s + calcVTDetalhe(f, config, comp).empresa, 0);
  const totVR = ativos.reduce((s, f) => s + (f.beneficios.vr.ativo ? vrInfo(f, config, comp).valorMensal : 0), 0);
  // Custo mensal cheio: salário cadastrado + VT (valor cheio) + VR, pessoa por pessoa.
  const custoMes = custoMensalTotal(ativos, config, comp);
  // VALE (adiantamento) do mes: mesma conta da aba Beneficios > Vale — CLT e treinamento
  // juntos, com o valor lancado/importado mandando sobre o previsto.
  const valeLinhas = ativos
    .map((f) => valeInfo(f, config, comp, pagamentos.find((p) => p.competencia === comp && p.funcionarioId === f.id && p.tipo === "Adiantamento"),
      FR.descontoFaltaNoVale(pagamentos.filter((p) => p.origem === "falta" && p.funcionarioId === f.id), comp).descontoCentavos / 100))
    .filter((v) => v.ativo && v.total > 0);
  const valeTotal = arred2(valeLinhas.reduce((s, v) => s + v.total, 0));
  // Treinamento (etapa de admissão): total, vencendo (≤15d) e finalizados (prazo passou).
  const treinos = ativos.map((f) => ({ f, t: calcTreinamento(f) })).filter((x) => x.t && x.t.emTreinamento);
  const treinTotal = treinos.length;
  const treinVencendo = treinos.filter((x) => x.t.vencendo).length;
  const treinFinalizados = treinos.filter((x) => x.t.finalizado).length;
  // Estagiários ativos (por tipo de contrato).
  const estagiarios = ativos.filter((f) => f.tipoContrato === "Estágio").length;
  // Treinamentos: nada é digitado aqui no Dashboard. O custo vem de duas fontes que o
  // sistema já tem — as TURMAS registradas e o treinamento de ADMISSÃO de cada pessoa
  // (calcTreino, que é o mesmo cálculo da tela de Processamento de Treinamento).
  // Quem está numa turma não é contado de novo pelo individual (nada entra duas vezes).
  const turmas = treinamentos.map((t) => ({ t, c: custoTurma(t, funcById, config) })).sort((a, b) => String(b.t.dataInicio || "").localeCompare(String(a.t.dataInicio || "")));
  const idsEmTurma = new Set(treinamentos.flatMap((t) => t.participantes || []));
  const treinoIndiv = treinos.filter((x) => !idsEmTurma.has(x.f.id)).map((x) => ({ f: x.f, c: calcTreino(x.f, config) }));
  const vtIndiv = treinoIndiv.reduce((s, x) => s + num(x.c.vtDevido), 0);
  const custoIndiv = treinoIndiv.reduce((s, x) => s + num(x.c.total), 0);
  const vtTreinamentos = turmas.reduce((s, x) => s + x.c.vt, 0) + vtIndiv;
  const custoTreinamentos = turmas.reduce((s, x) => s + x.c.total, 0) + custoIndiv;
  const entrevistasAg = candidatos.reduce((s, c) => s + (c.historicoEntrevistas || []).filter((h) => h.status === "Agendada").length, 0);

  const alertasTrein = treinos.filter((x) => x.t.diasRestantes != null && x.t.diasRestantes <= 15).sort((a, b) => a.t.diasRestantes - b.t.diasRestantes);
  const vtPend = ativos.map((f) => ({ f, i: vtInfo(f, config) })).filter((x) => x.i && x.i.pendente).sort((a, b) => (a.i.proximo || "").localeCompare(b.i.proximo || ""));
  const docsPend = ativos.map((f) => ({ f, faltam: docsFaltantes(f.id, documentos) })).filter((x) => x.faltam.length > 0);
  // Descontos de falta não são repasses. Ordem fixa — competência mais antiga
  // primeiro (a mais atrasada), depois o maior valor: sem isso a lista saía na
  // ordem física do banco, e o cartão mostrava 5 pendências quaisquer.
  const pagPend = pagamentos
    .filter((p) => p.status === "Pendente" && p.origem !== "falta")
    .sort((a, b) => String(a.competencia || "").localeCompare(String(b.competencia || ""))
      || (Number(b.valor) || 0) - (Number(a.valor) || 0)
      || String(funcById[a.funcionarioId]?.nome || a.nome || "").localeCompare(String(funcById[b.funcionarioId]?.nome || b.nome || ""), "pt-BR"));
  const rescPend = funcionarios.map((f) => ({ f, r: rescisaoPendente(f) })).filter((x) => x.r).sort((a, b) => (a.r.dias ?? 999) - (b.r.dias ?? 999));
  const porEmpresa = empresasComGente(ativos).map((e) => ({ nome: e, v: ativos.filter((f) => f.empresa === e).length }));
  const maxEmp = Math.max(1, ...porEmpresa.map((e) => e.v));

  return (
    <div className="space-y-4">
      <PageHeader titulo="Dashboard" subtitulo={`Visão geral · ${compLabel(comp)}`}>
        <input type="month" aria-label="Mês do painel" className={selCls} value={comp} onChange={(e) => setComp(e.target.value || compAtual())} />
        {comp !== compAtual() && <Btn variant="secondary" onClick={() => setComp(compAtual())}>Mês atual</Btn>}
      </PageHeader>
      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
        <Kpi icon={Users} label="Funcionários ativos" value={ativos.length} onClick={() => abrirFuncFiltro({})} />
        <Kpi icon={CalendarClock} label="Em treinamento" value={treinTotal} tone="amber" onClick={() => abrirFuncFiltro({ situacao: "Em treinamento" })} />
        <Kpi icon={GraduationCap} label="Estagiários" value={estagiarios} tone="blue" onClick={() => abrirFuncFiltro({ contrato: "Estágio" })} />
        <Kpi icon={Bus} label="VT por treinamento" value={fmtBRLc(vtTreinamentos)} tone="blue" onClick={() => setAba("funcionarios", "turmas")} />
        <Kpi icon={Calculator} label="Gasto com treinamento" value={fmtBRLc(custoTreinamentos)} tone="amber" onClick={() => setAba("funcionarios", "turmas")} />
        <Kpi icon={UserPlus} label="Contratações do mês" value={adm} tone="blue" onClick={() => abrirFuncFiltro({ situacao: "Todos", admDe: comp + "-01", admAte: comp + "-" + String(new Date(+comp.slice(0, 4), +comp.slice(5, 7), 0).getDate()).padStart(2, "0") })} />
        <Kpi icon={UserMinus} label="Desligamentos" value={desl} tone="red" onClick={() => setAba("pagamentos", "rescisoes")} />
        <Kpi icon={CheckCircle2} label="Registrados" value={registrados.length} tone="emerald" onClick={() => abrirFuncFiltro({ registro: "Registrado" })} />
        <Kpi icon={AlertTriangle} label="Não registrados" value={naoRegistrados.length} tone="amber" onClick={() => abrirFuncFiltro({ registro: "Não Registrado" })} />
        <Kpi icon={Bus} label="Gasto com VT" value={fmtBRLc(totVT)} tone="blue" onClick={() => abrirFuncFiltro({ beneficio: "VT" })} />
        <Kpi icon={Utensils} label="Gasto com VR" value={fmtBRLc(totVR)} tone="blue" onClick={() => abrirFuncFiltro({ beneficio: "VR" })} />
        <Kpi icon={Wallet} label="Vale do mês" value={fmtBRLc(valeTotal)} tone="amber" onClick={() => { setBeneficioFoco("vale"); setAba("pagamentos", "beneficios"); }} />
        <Kpi icon={Banknote} label="Folha" value={fmtBRLc(folha)} onClick={() => setAba("pagamentos", "folha")} />
        <Kpi icon={Calculator} label={`Custo mensal total (${custoMes.pessoas} pessoas · salário + VT + VR)`} value={fmtBRLc(custoMes.total)} tone="emerald" onClick={() => setAba("pagamentos", "folha")} />
        <Kpi icon={CalendarDays} label="Entrevistas" value={entrevistasAg} tone="blue" onClick={() => setAba("recrutamento", "entrevistas")} />
        <Kpi icon={Stethoscope} label="Ausências (mês)" value={ausenciasMes} tone="amber" onClick={() => setAba("atestados")} />
      </div>

      <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
        <Card className="p-4 lg:col-span-2">
          <div className="mb-3 flex items-center justify-between"><h3 className="flex items-center gap-2 text-sm font-semibold text-foreground/80"><Building2 size={15} className="text-muted-foreground/80" /> Funcionários por empresa</h3><button onClick={() => setAba("indicadores")} className="text-xs font-medium text-primary hover:text-primary">Ver indicadores</button></div>
          <div className="grid grid-cols-1 gap-x-8 gap-y-2.5 sm:grid-cols-2">{porEmpresa.map((e) => (<button key={e.nome} type="button" onClick={() => abrirFuncFiltro({ empresa: e.nome })} className="-m-1 w-full rounded-md p-1 text-left transition-colors hover:bg-secondary/50" title={`Ver funcionários de ${e.nome}`}><div className="flex justify-between text-sm"><span className="text-foreground/70">{e.nome}</span><span className="font-semibold text-foreground">{e.v}</span></div><div className="mt-1 h-1.5 w-full rounded-full bg-secondary"><div className="h-1.5 rounded-full bg-primary" style={{ width: `${(e.v / maxEmp) * 100}%` }} /></div></button>))}</div>
          <div className="mt-4 grid grid-cols-2 gap-3 border-t border-border/60 pt-3 text-sm"><div className="flex items-center justify-between rounded-md bg-success/8 px-3 py-2"><span className="text-success">Registrados</span><span className="font-semibold text-success">{registrados.length}</span></div><div className="flex items-center justify-between rounded-md bg-warning/8 px-3 py-2"><span className="text-warning-ink">Não registrados</span><span className="font-semibold text-warning-ink">{naoRegistrados.length}</span></div></div>
        </Card>
        <PainelMini titulo="Rescisões pendentes" icon={AlertTriangle} onVer={() => setAba("pagamentos", "rescisoes")} vazio="Nenhuma pendência." itens={rescPend.slice(0, 5).map(({ f, r }) => (
          <LinhaMini key={f.id} titulo={f.nome} sub={`${fmtBRL(r.valor)} · ${r.dataPagamento ? fmtData(r.dataPagamento) : "sem data"}`} right={r.dias == null ? <Badge>—</Badge> : <TagDias dias={r.dias} />} />
        ))} />
      </div>

      <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-4">
        <PainelMini titulo="Pagamentos pendentes" icon={Banknote} onVer={() => setAba("pagamentos", "folha")} vazio="Tudo pago." itens={pagPend.slice(0, 5).map((p) => (<LinhaMini key={p.id} titulo={funcById[p.funcionarioId]?.nome || p.nome} sub={`${p.tipo} · ${p.competencia}`} right={<span className="text-sm font-semibold text-foreground/80">{fmtBRL(p.valor)}</span>} />))} />
        <PainelMini titulo="VT a pagar" icon={Bus} onVer={() => setAba("pagamentos", "beneficios")} vazio="Nenhum VT pendente." itens={vtPend.slice(0, 5).map(({ f, i }) => (<LinhaMini key={f.id} titulo={f.nome} sub={`${i.freq.label} · ${fmtData(i.proximo)}`} right={<span className="text-sm font-semibold text-foreground/80">{fmtBRL(i.valorPeriodo)}</span>} />))} />
        <PainelMini titulo="VT por treinamento" icon={GraduationCap} onVer={() => setAba("funcionarios", "turmas")} vazio="Nenhum treinamento com custo no período." itens={[
          ...turmas.slice(0, 4).map(({ t, c }) => (
            <LinhaMini key={t.id} titulo={t.nome || "Sem nome"} sub={`${t.turma ? t.turma + " · " : ""}${c.n} participante(s) · total ${fmtBRL(c.total)}`} right={<span className="text-sm font-semibold tabular-nums text-foreground/80">{fmtBRL(c.vt)}</span>} />
          )),
          ...(treinoIndiv.length ? [<LinhaMini key="__indiv" titulo="Treinamento de admissão" sub={`${treinoIndiv.length} pessoa(s) em treinamento · total ${fmtBRL(custoIndiv)}`} right={<span className="text-sm font-semibold tabular-nums text-foreground/80">{fmtBRL(vtIndiv)}</span>} />] : []),
        ]} />
        <Card className="p-4">
          <div className="mb-2 flex items-center justify-between">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-foreground/80"><CalendarClock size={15} className="text-muted-foreground/80" /> Pessoas em treinamento</h3>
            <button onClick={() => abrirFuncFiltro({ situacao: "Em treinamento" })} className="text-xs font-medium text-primary hover:text-primary">Ver</button>
          </div>
          <button type="button" onClick={() => abrirFuncFiltro({ situacao: "Em treinamento" })} className="grid w-full grid-cols-3 gap-2 rounded-md py-1 text-center transition-colors hover:bg-secondary/50">
            <div><p className="text-2xl font-bold tabular-nums text-foreground">{treinTotal}</p><p className="text-[11px] text-muted-foreground/80">Total</p></div>
            <div><p className="text-2xl font-bold tabular-nums text-warning-ink">{treinVencendo}</p><p className="text-[11px] text-muted-foreground/80">Vencendo</p></div>
            <div><p className="text-2xl font-bold tabular-nums text-destructive">{treinFinalizados}</p><p className="text-[11px] text-muted-foreground/80">Finalizados</p></div>
          </button>
          <div className="mt-2 divide-y divide-border/60 border-t border-border/60 pt-1">{alertasTrein.length ? alertasTrein.slice(0, 4).map(({ f, t }) => (<LinhaMini key={f.id} titulo={f.nome} sub={f.cargo || f.empresa} right={t.diasRestantes == null ? <Badge>—</Badge> : <TagDias dias={t.diasRestantes} />} />)) : <p className="py-3 text-center text-sm text-muted-foreground/80">Sem vencimentos próximos.</p>}</div>
        </Card>
      </div>
    </div>
  );
}
const PainelMini = ({ titulo, icon: Icon, itens, onVer, vazio }) => (
  <Card className="p-4"><div className="mb-2 flex items-center justify-between"><h3 className="flex items-center gap-2 text-sm font-semibold text-foreground/80"><Icon size={15} className="text-muted-foreground/80" />{titulo}</h3>{onVer && <button onClick={onVer} className="text-xs font-medium text-primary hover:text-primary">Ver</button>}</div><div className="divide-y divide-border/60">{itens.length ? itens : <p className="py-4 text-center text-sm text-muted-foreground/80">{vazio}</p>}</div></Card>
);
const LinhaMini = ({ titulo, sub, right }) => (<div className="flex items-center justify-between gap-2 py-1.5"><div className="min-w-0"><p className="truncate text-sm font-medium text-foreground/80">{titulo}</p>{sub && <p className="truncate text-xs text-muted-foreground/80">{sub}</p>}</div><div className="shrink-0">{right}</div></div>);
const TagDias = ({ dias }) => {
  const cls = dias <= 1 ? "bg-destructive/8 text-destructive" : dias <= 3 ? "bg-warning/8 text-warning-ink" : dias <= 5 ? "bg-yellow-50 dark:bg-yellow-500/15 text-yellow-700 dark:text-yellow-300" : "bg-secondary text-muted-foreground";
  const txt = dias < 0 ? `-${Math.abs(dias)}d` : dias === 0 ? "Hoje" : `${dias}d`;
  return <Badge cls={cls}>{txt}</Badge>;
};

// Dashboard focado em Recrutamento (usado por perfis de acesso restrito ao recrutamento).
function DashboardRecrutamento({ candidatos = [], setAba, empresaPermitida = "" }) {
  const total = candidatos.length;
  const porEtapa = KANBAN_COLS.map((k) => ({ id: k.id, n: candidatos.filter((c) => (c.status || KANBAN_COLS[0].id) === k.id).length }));
  const maxEtapa = Math.max(1, ...porEtapa.map((e) => e.n));
  const entrevistasAg = candidatos.reduce((s, c) => s + (c.historicoEntrevistas || []).filter((h) => (h.status || "Agendada") === "Agendada").length, 0);
  const contratados = candidatos.filter((c) => /contratad/i.test(c.status || "")).length;
  const talentos = candidatos.filter((c) => c.bancoTalentos).length;
  const hoje = hojeISO();
  // "Próximas" = só o que ainda vai acontecer: entrevista já realizada/cancelada não é próxima.
  const proximas = candidatos.flatMap((c) => (c.historicoEntrevistas || []).filter((h) => h.data && !entrevistaConcluida(h.status)).map((h) => ({ ...h, cand: c.nome }))).filter((e) => e.data >= hoje).sort((a, b) => ((a.data || "") + (a.hora || "")).localeCompare((b.data || "") + (b.hora || ""))).slice(0, 6);
  const porOrigem = ORIGENS.map((o) => ({ o, n: candidatos.filter((c) => c.origem === o).length })).filter((x) => x.n > 0);
  const maxOrig = Math.max(1, ...porOrigem.map((x) => x.n));
  // Candidatos por Área de recrutamento — recalculado a cada importação/alteração.
  const porArea = AREAS_RECRUTAMENTO.map((a) => ({ a, n: candidatos.filter((c) => areaDe(c) === a).length })).filter((x) => x.n > 0).sort((x, y) => y.n - x.n);
  const maxArea = Math.max(1, ...porArea.map((x) => x.n));
  return (
    <div className="space-y-4">
      <PageHeader titulo="Dashboard — Recrutamento" subtitulo={empresaPermitida ? `Recrutamento · ${empresaPermitida}` : "Visão geral do recrutamento"}>
        <Btn onClick={() => setAba("recrutamento", "candidatos", "Todas")}><Briefcase size={16} /> Ir para Recrutamento</Btn>
      </PageHeader>
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        {/* Os atalhos do total levam sempre à visão completa (limpam a área em foco). */}
        <Kpi icon={Users} label="Candidatos" value={total} onClick={() => setAba("recrutamento", "candidatos", "Todas")} />
        <Kpi icon={CalendarDays} label="Entrevistas agendadas" value={entrevistasAg} tone="blue" onClick={() => setAba("recrutamento", "agenda")} />
        <Kpi icon={CheckCircle2} label="Contratados" value={contratados} tone="emerald" />
        <Kpi icon={Star} label="Banco de talentos" value={talentos} tone="amber" onClick={() => setAba("recrutamento", "talentos")} />
      </div>
      {/* ORGANIZAÇÃO PRINCIPAL: por ÁREA da empresa. Clicar numa área abre o
          Recrutamento já filtrado, mostrando só os candidatos daquela área. */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
        <Card className="p-4 lg:col-span-2">
          <div className="mb-3 flex items-center justify-between">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-foreground/80"><Briefcase size={15} className="text-muted-foreground/80" /> Candidatos por área</h3>
            <button onClick={() => setAba("recrutamento", "candidatos", "Todas")} className="text-xs font-medium text-primary hover:text-primary">Ver todos</button>
          </div>
          {porArea.length === 0 ? <Empty texto="Nenhum candidato cadastrado." icon={Briefcase} /> : (
            <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
              {porArea.map((x) => (
                <button key={x.a} onClick={() => setAba("recrutamento", "candidatos", x.a)}
                  className="group rounded-md border border-border p-2.5 text-left transition-colors hover:border-violet-300 hover:bg-violet-50/40">
                  <div className="flex items-baseline justify-between gap-2">
                    <span className="truncate text-sm font-medium text-foreground/80 group-hover:text-violet-700">{x.a}</span>
                    <span className="shrink-0 text-lg font-semibold text-foreground">{x.n}</span>
                  </div>
                  <div className="mt-1.5 h-1.5 w-full rounded-full bg-secondary"><div className="h-1.5 rounded-full bg-violet-500" style={{ width: `${(x.n / maxArea) * 100}%` }} /></div>
                </button>
              ))}
            </div>
          )}
        </Card>
        <PainelMini titulo="Próximas entrevistas" icon={CalendarDays} onVer={() => setAba("recrutamento", "agenda")} vazio="Nenhuma entrevista futura." itens={proximas.map((e, i) => (<LinhaMini key={i} titulo={`${horaLegivel(e.hora) ? horaLegivel(e.hora) + " · " : ""}${e.cand || "—"}`} sub={`${e.tipo || "Entrevista"}${e.avaliador ? " · " + e.avaliador : ""}`} right={<span className="text-xs text-muted-foreground/80">{fmtData(e.data)}</span>} />))} />
      </div>
      {/* Visões complementares: as etapas do funil continuam disponíveis, só não são mais a organização principal. */}
      <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
        <Card className="p-4">
          <div className="mb-3 flex items-center justify-between"><h3 className="flex items-center gap-2 text-sm font-semibold text-foreground/80"><Columns size={15} className="text-muted-foreground/80" /> Candidatos por etapa do funil</h3><button onClick={() => setAba("recrutamento", "candidatos")} className="text-xs font-medium text-primary hover:text-primary">Ver funil</button></div>
          <div className="space-y-2.5">{porEtapa.map((e) => (<div key={e.id}><div className="flex justify-between text-sm"><span className="text-foreground/70">{e.id}</span><span className="font-semibold text-foreground">{e.n}</span></div><div className="mt-1 h-1.5 w-full rounded-full bg-secondary"><div className="h-1.5 rounded-full bg-primary" style={{ width: `${(e.n / maxEtapa) * 100}%` }} /></div></div>))}</div>
        </Card>
        {porOrigem.length > 0 && (
          <Card className="p-4"><h3 className="mb-3 text-sm font-semibold text-foreground/80">Candidatos por origem</h3><div className="grid grid-cols-1 gap-x-8 gap-y-2.5">{porOrigem.map((x) => (<div key={x.o}><div className="flex justify-between text-sm"><span className="text-foreground/70">{x.o}</span><span className="font-semibold text-foreground">{x.n}</span></div><div className="mt-1 h-1.5 w-full rounded-full bg-secondary"><div className="h-1.5 rounded-full bg-indigo-500" style={{ width: `${(x.n / maxOrig) * 100}%` }} /></div></div>))}</div></Card>
        )}
      </div>
    </div>
  );
}

/* ==================================================================
   FUNCIONÁRIOS (tabela profissional + formulário em abas)
   ================================================================== */
const FILTRO_VAZIO = { situacao: "Ativos", empresa: "Todas", cargo: "", departamento: "Todos", status: "Todos", registro: "Todos", contrato: "Todos", beneficio: "Todos", gestor: "", admDe: "", admAte: "", regDe: "", regAte: "" };
function aplicaFiltros(f, ft) {
  if (ft.situacao === "Ativos" && f.status === "Desligado") return false;
  if (ft.situacao === "Desligados" && f.status !== "Desligado") return false;
  if (ft.situacao === "Em treinamento") { const t = calcTreinamento(f); if (!t || !t.emTreinamento) return false; }
  if (ft.empresa !== "Todas" && f.empresa !== ft.empresa) return false;
  if (ft.cargo && !(f.cargo || "").toLowerCase().includes(ft.cargo.toLowerCase())) return false;
  if (ft.departamento !== "Todos" && (f.departamento || "") !== ft.departamento) return false;
  if (ft.status !== "Todos" && f.status !== ft.status) return false;
  if (ft.registro === "Registrado" && !isRegistrado(f)) return false;
  if (ft.registro === "Não Registrado" && isRegistrado(f)) return false;
  if (ft.contrato && ft.contrato !== "Todos" && f.tipoContrato !== ft.contrato) return false;
  if (ft.beneficio === "VT" && !(f.beneficios && f.beneficios.vt && f.beneficios.vt.ativo)) return false;
  if (ft.beneficio === "VR" && !(f.beneficios && f.beneficios.vr && f.beneficios.vr.ativo)) return false;
  if (ft.gestor && !(f.gestor || "").toLowerCase().includes(ft.gestor.toLowerCase())) return false;
  if (ft.admDe && (f.dataAdmissao || "") < ft.admDe) return false;
  if (ft.admAte && (f.dataAdmissao || "") > ft.admAte) return false;
  if (ft.regDe && (f.dataRegistro || "") < ft.regDe) return false;
  if (ft.regAte && (f.dataRegistro || "") > ft.regAte) return false;
  return true;
}
const selCls = "rounded-md border border-input bg-card px-2.5 py-2 text-sm text-foreground/80 outline-none focus:border-primary focus:ring-2 focus:ring-primary/15";
// Filtro rapido de empresa reutilizavel (usado em varias telas).
const SelectEmpresa = ({ value, onChange }) => (<select className={selCls} value={value} onChange={(e) => onChange(e.target.value)}><option>Todas</option>{EMPRESAS.map((x) => <option key={x}>{x}</option>)}</select>);
function novoFunc(config, patch = {}) { return normalizeFunc({ beneficios: { adiantamento: { ativo: true, tipo: "padrao", percentual: config.percentualAdiant } }, ...patch }); }

// Assistente de importacao inteligente reutilizavel: le a planilha, mapeia colunas por sinonimos,
// mostra previa, detecta duplicidades (por CPF/telefone/e-mail) e permite atualizar/ignorar/criar.
// Tamanho mínimo de um valor para servir como chave de duplicidade (evita falso positivo).
const minChave = (key) => (key === "email" ? 5 : key === "cpf" ? 11 : 8);
// Valor de um campo para exibir na prévia, já formatado como o usuário vê na planilha.
// Os campos de entrevista ficam guardados com prefixo "_" no objeto transformado (são
// montados depois dentro do histórico), por isso a busca também tenta "_" + chave.
function valorPrevia(dados, key) {
  if (key === "celular") return dados.telefone ? fmtTelefoneBR(dados.telefone) : ""; // celular alimenta o telefone principal
  const v = dados[key] !== undefined ? dados[key] : dados["_" + key];
  if (v === undefined || v === null || v === "") return "";
  if (key === "salarioBase") return fmtBRL(v);
  if (/^data/i.test(key)) return fmtData(v);
  if (key === "telefone" || key === "whatsapp") return fmtTelefoneBR(v);
  if (key === "cpf") return fmtCPF(v);
  return String(v);
}
function SmartImport({ schema, existentes, onClose, onImportar }) {
  const [etapa, setEtapa] = useState("upload"); // upload | mapa | resultado
  const [nomeArq, setNomeArq] = useState("");
  const [headers, setHeaders] = useState([]);
  const [linhas, setLinhas] = useState([]);
  const [mapa, setMapa] = useState({});
  const [policy, setPolicy] = useState("atualizar");
  const [erroArq, setErroArq] = useState("");
  const [defaultDepto, setDefaultDepto] = useState("");
  const [defaultArea, setDefaultArea] = useState(""); // área única aplicada a quem não tem
  const [overrides, setOverrides] = useState({});
  const [abaInfo, setAbaInfo] = useState({ aba: "", abas: [] });
  const [processadas, setProcessadas] = useState([]);
  const [prog, setProg] = useState(null); // { fase, feito, total } — barra de progresso
  const [resultado, setResultado] = useState(null); // estatísticas finais
  const campos = schema.campos;
  const execRef = useRef(0); // cancela análises antigas quando o mapeamento muda

  async function aoEscolher(e) {
    const file = e.target.files?.[0]; if (!file) return;
    setNomeArq(file.name); setErroArq("");
    try {
      const { headers: hs, linhas: ls, aba, abas } = await lerPlanilha(file);
      if (!hs.length || !ls.length) { setErroArq("Planilha vazia ou sem cabeçalho reconhecível."); return; }
      setHeaders(hs); setLinhas(ls); setMapa(autoMapear(hs, campos)); setAbaInfo({ aba, abas: abas || [] }); setEtapa("mapa");
    } catch { setErroArq("Não foi possível ler o arquivo. Use .xlsx, .xls ou .csv."); }
    e.target.value = "";
  }
  // O modelo traz só as colunas da planilha de trabalho (as marcadas como `extra` ficam
  // de fora para o arquivo sair igual ao que o RH já usa).
  function baixarModelo() { baixarXLSX(`modelo_${schema.chave}`, campos.filter((c) => !c.key.startsWith("_") && !c.extra).map((c) => c.label), []); }

  // Índice dos cadastros existentes por chave (CPF/e-mail/telefone/WhatsApp).
  // Busca em O(1) por linha — é o que permite importar milhares de registros sem travar.
  const indices = useMemo(() => {
    const idx = {};
    (schema.matchKeys || []).forEach((k) => {
      const m = new Map();
      const alias = (schema.matchAlias && schema.matchAlias[k]) || [k];
      existentes.forEach((ex) => alias.forEach((a) => {
        const v = chaveNorm(k, ex[a]);
        if (v && v.length >= minChave(k) && !m.has(v)) m.set(v, ex);
      }));
      idx[k] = m;
    });
    return idx;
  }, [existentes, schema]);

  // Análise da planilha em lotes: processa 500 linhas por vez e devolve o controle ao
  // navegador entre os lotes, mantendo a tela responsiva e alimentando a barra de progresso.
  useEffect(() => {
    if (etapa !== "mapa") return;
    const token = ++execRef.current;
    let vivo = true;
    (async () => {
      const total = linhas.length;
      const out = [];
      const vistos = new Map(); // duplicados DENTRO da própria planilha
      setProg({ fase: "Analisando planilha", feito: 0, total });
      const LOTE = 500;
      for (let ini = 0; ini < total; ini += LOTE) {
        if (!vivo || execRef.current !== token) return;
        linhas.slice(ini, ini + LOTE).forEach((linha, j) => {
          const i = ini + j;
          const bruto = {}; campos.forEach((c) => { const col = mapa[c.key]; bruto[c.key] = col ? linha[col] : ""; });
          const { dados, erros, precisaDepto, precisaArea } = schema.transformar(bruto);
          // Departamento (funcionários): resolve cargos sem departamento identificado.
          if (schema.resolveDepto && precisaDepto) { const dep = overrides[i] || defaultDepto; if (dep) dados.departamento = dep; }
          const semDepto = !!(schema.resolveDepto && precisaDepto && !dados.departamento);
          // Área (candidatos): a planilha manda; se não trouxer, usa a área única escolhida.
          if (schema.resolveArea && precisaArea && defaultArea) dados.area = defaultArea;
          const semArea = !!(schema.resolveArea && !dados.area);
          // Duplicidade: primeiro contra os cadastros existentes, depois dentro da planilha.
          let match = null, chaveMatch = "", dupArquivo = false;
          const chavesLinha = [];
          for (const key of (schema.matchKeys || [])) {
            const alias = (schema.matchAlias && schema.matchAlias[key]) || [key];
            for (const a of alias) {
              const v = chaveNorm(key, dados[a]);
              if (!v || v.length < minChave(key)) continue;
              chavesLinha.push(key + ":" + v);
              if (!match) { const achou = indices[key]?.get(v); if (achou) { match = achou; chaveMatch = key; } }
            }
          }
          if (!match) { const rep = chavesLinha.find((c) => vistos.has(c)); if (rep) { dupArquivo = true; chaveMatch = rep.split(":")[0]; } }
          chavesLinha.forEach((c) => { if (!vistos.has(c)) vistos.set(c, i); });
          out.push({ i, dados, erros, match, chaveMatch, dupArquivo, semDepto, semArea });
        });
        setProg({ fase: "Analisando planilha", feito: Math.min(ini + LOTE, total), total });
        await new Promise((r) => setTimeout(r, 0)); // libera a interface entre os lotes
      }
      if (!vivo || execRef.current !== token) return;
      setProcessadas(out); setProg(null);
    })();
    return () => { vivo = false; };
  }, [etapa, linhas, mapa, overrides, defaultDepto, defaultArea, indices]);

  const validas = processadas.filter((p) => p.erros.length === 0);
  const dups = validas.filter((p) => p.match);
  const dupsArquivo = validas.filter((p) => p.dupArquivo);
  const novos = validas.filter((p) => !p.match && !p.dupArquivo);
  const comErro = processadas.filter((p) => p.erros.length > 0);
  const pendentesDepto = validas.filter((p) => p.semDepto);
  const pendentesArea = validas.filter((p) => p.semArea);
  const totalImportar = novos.length + (policy === "ignorar" ? 0 : dups.length);
  // Campos reconhecidos (mapeados) x colunas da planilha não aproveitadas.
  const usadas = new Set(Object.values(mapa).filter(Boolean));
  const reconhecidos = campos.filter((c) => !c.key.startsWith("_") && mapa[c.key]);
  const naoReconhecidas = headers.filter((h) => !usadas.has(h));
  const bloqueado = !!prog || totalImportar === 0 || pendentesArea.length > 0;

  // Importação em lotes, com progresso. Ao final mostra o resumo (etapa "resultado").
  async function importar() {
    const t0 = Date.now();
    const criar = [], atualizar = [];
    let ignorados = 0;
    setProg({ fase: "Importando", feito: 0, total: validas.length });
    const LOTE = 500;
    for (let ini = 0; ini < validas.length; ini += LOTE) {
      validas.slice(ini, ini + LOTE).forEach((p) => {
        if (p.dupArquivo) { ignorados++; return; } // repetido na própria planilha: entra uma vez só
        if (p.match && policy === "ignorar") { ignorados++; return; }
        if (p.match && policy === "atualizar") {
          const patch = {};
          Object.entries(p.dados).forEach(([k, val]) => {
            if (k.startsWith("_")) return;
            if ((schema.naoAtualizar || []).includes(k)) return; // ex.: não volta a etapa do candidato para Triagem
            if (val !== "" && val !== 0 && val != null) patch[k] = val;
          });
          atualizar.push({ id: p.match.id, patch }); return;
        }
        criar.push(schema.criar(p.dados));
      });
      setProg({ fase: "Importando", feito: Math.min(ini + LOTE, validas.length), total: validas.length });
      await new Promise((r) => setTimeout(r, 0));
    }
    onImportar({ criar, atualizar });
    setProg(null);
    setResultado({
      criados: criar.length, atualizados: atualizar.length, ignorados,
      duplicados: dups.length + dupsArquivo.length, erros: comErro.length,
      total: linhas.length, tempo: (Date.now() - t0) / 1000,
    });
    setEtapa("resultado");
  }

  // A prévia espelha a planilha: só as colunas que ela realmente tem, na ordem em que
  // aparecem no arquivo. Colunas do CRM que a planilha não trouxe ficam de fora — não
  // adianta mostrar 8 colunas vazias.
  const camposPrevia = useMemo(() => {
    const pos = (c) => headers.indexOf(mapa[c.key]);
    return campos.filter((c) => !c.key.startsWith("_") && mapa[c.key]).sort((a, b) => pos(a) - pos(b));
  }, [campos, mapa, headers]);
  const previa = processadas.slice(0, 50);
  return (
    <Modal title={schema.titulo} subtitle="Reconhecimento automático de colunas · prévia e duplicidades" onClose={onClose} max="max-w-5xl"
      footer={etapa === "mapa"
        ? <><Btn variant="secondary" onClick={onClose}>Cancelar</Btn><Btn variant="secondary" onClick={() => setEtapa("upload")}>Voltar</Btn><Btn onClick={importar} disabled={bloqueado}><Upload size={16} /> {prog ? "Importando..." : `Importar ${totalImportar} registro(s)`}</Btn></>
        : etapa === "resultado" ? <Btn onClick={onClose}><CheckCircle2 size={16} /> Concluir</Btn>
        : <Btn variant="secondary" onClick={onClose}>Cancelar</Btn>}>
      {etapa === "resultado" && resultado ? (
        <div className="space-y-4">
          <div className="rounded-lg border border-success/30 bg-success/5 p-4 text-center">
            <CheckCircle2 size={30} className="mx-auto mb-2 text-success" />
            <p className="text-lg font-semibold text-success">Importação concluída</p>
            <p className="text-sm text-success">{resultado.criados} registro(s) criado(s) · {resultado.atualizados} atualizado(s)</p>
          </div>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
            {[
              { l: "Linhas na planilha", v: resultado.total, c: "text-foreground/80" },
              { l: "Importados (novos)", v: resultado.criados, c: "text-success" },
              { l: "Atualizados", v: resultado.atualizados, c: "text-primary" },
              { l: "Duplicados encontrados", v: resultado.duplicados, c: "text-warning-ink" },
              { l: "Ignorados", v: resultado.ignorados, c: "text-muted-foreground" },
              { l: "Com erro", v: resultado.erros, c: resultado.erros ? "text-destructive" : "text-muted-foreground" },
            ].map((x) => (
              <div key={x.l} className="rounded-md border border-border bg-card p-3 text-center">
                <p className={`text-2xl font-semibold ${x.c}`}>{x.v}</p>
                <p className="mt-0.5 text-xs text-muted-foreground">{x.l}</p>
              </div>
            ))}
          </div>
          <p className="flex items-center justify-center gap-1.5 text-sm text-muted-foreground"><Clock size={14} /> Tempo de importação: <strong className="text-foreground/80">{resultado.tempo.toFixed(1)}s</strong></p>
          {schema.resolveArea && <p className="rounded-md bg-primary/8 px-3 py-2 text-center text-xs text-primary">Todos os candidatos entraram na etapa <strong>Triagem</strong>, já classificados por Área de recrutamento.</p>}
        </div>
      ) : etapa === "upload" ? (
        <div className="space-y-4">
          <div className="rounded-lg border-2 border-dashed border-border p-8 text-center">
            <Upload size={28} className="mx-auto mb-3 text-muted-foreground/50" />
            <label className="inline-flex cursor-pointer items-center gap-2 rounded-md bg-foreground px-4 py-2.5 text-sm font-medium text-background hover:bg-foreground/90"><Upload size={15} /> Escolher planilha<input type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={aoEscolher} /></label>
            <p className="mt-3 text-xs text-muted-foreground/80">Excel (.xlsx, .xls) ou CSV. Não precisa ajustar os cabeçalhos — o sistema reconhece as colunas automaticamente. Suporta planilhas grandes (5.000+ linhas).</p>
            {schema.resolveArea && <p className="mt-1.5 text-xs text-primary">Todos os candidatos entram em <strong>Triagem</strong> e são classificados por <strong>Área de recrutamento</strong>.</p>}
            {erroArq && <p className="mt-2 text-sm font-medium text-destructive">{erroArq}</p>}
          </div>
          <div className="flex items-center justify-between rounded-md bg-secondary/50 px-3 py-2 text-xs text-muted-foreground">
            <span>Colunas reconhecidas automaticamente: {campos.filter((c) => !c.key.startsWith("_")).map((c) => c.label).join(", ")}.</span>
            <Btn size="sm" variant="secondary" onClick={baixarModelo}><Download size={13} /> Modelo</Btn>
          </div>
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex flex-wrap items-center gap-2 text-sm">
            <span className="text-muted-foreground">{nomeArq}</span>
            {abaInfo.aba && <Badge cls="bg-primary/8 text-primary">Aba: {abaInfo.aba}{abaInfo.abas.length > 1 ? ` (de ${abaInfo.abas.length})` : ""}</Badge>}
            <Badge cls="bg-secondary text-foreground/70">{linhas.length} linha(s)</Badge>
            <Badge cls="bg-secondary text-foreground/70">{validas.length} válido(s)</Badge>
            {comErro.length > 0 && <Badge cls="bg-destructive/8 text-destructive">{comErro.length} inválido(s)</Badge>}
            <Badge cls="bg-success/8 text-success">{novos.length} novo(s)</Badge>
            <Badge cls="bg-warning/8 text-warning-ink">{dups.length + dupsArquivo.length} duplicado(s)</Badge>
            {pendentesDepto.length > 0 && <Badge cls="bg-orange-50 dark:bg-orange-500/15 text-orange-700 dark:text-orange-300">{pendentesDepto.length} sem departamento</Badge>}
            {pendentesArea.length > 0 && <Badge cls="bg-orange-50 dark:bg-orange-500/15 text-orange-700 dark:text-orange-300">{pendentesArea.length} sem área</Badge>}
          </div>
          {prog && (
            <div className="rounded-md border border-primary/30 bg-primary/5 p-3">
              <div className="mb-1.5 flex justify-between text-xs font-medium text-primary"><span>{prog.fase}...</span><span>{prog.feito} de {prog.total}</span></div>
              <div className="h-2 w-full overflow-hidden rounded-full bg-primary/15">
                <div className="h-2 rounded-full bg-primary transition-all" style={{ width: `${prog.total ? (prog.feito / prog.total) * 100 : 0}%` }} />
              </div>
            </div>
          )}
          {/* Área de recrutamento: a planilha manda; se faltar, o usuário escolhe UMA área para todos. */}
          {schema.resolveArea && pendentesArea.length > 0 && (
            <div className="rounded-md border border-orange-200 dark:border-orange-500/30 bg-orange-50/60 dark:bg-orange-500/15 p-3">
              <p className="mb-2 flex items-center gap-1.5 text-sm font-medium text-orange-800 dark:text-orange-300"><AlertTriangle size={14} /> {pendentesArea.length} candidato(s) sem Área de recrutamento identificada na planilha.</p>
              <div className="flex flex-wrap items-center gap-2 text-sm">
                <span className="text-foreground/70">Aplicar esta área a todos eles:</span>
                <select className={selCls} value={defaultArea} onChange={(e) => setDefaultArea(e.target.value)}>
                  <option value="">— escolher área —</option>
                  {AREAS_RECRUTAMENTO.map((a) => <option key={a}>{a}</option>)}
                </select>
              </div>
              <p className="mt-2 text-xs text-orange-700 dark:text-orange-300">Obrigatório: nenhum candidato pode ser importado sem área.</p>
            </div>
          )}
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
            <div className="rounded-md border border-success/20 bg-success/5 p-3 text-xs"><p className="mb-1 font-semibold text-success">Campos reconhecidos ({reconhecidos.length})</p><p className="text-foreground/70">{reconhecidos.map((c) => c.label).join(", ") || "—"}</p></div>
            <div className="rounded-md border border-border bg-secondary/30 p-3 text-xs"><p className="mb-1 font-semibold text-foreground/70">Colunas não reconhecidas ({naoReconhecidas.length})</p><p className="text-muted-foreground">{naoReconhecidas.join(", ") || "Nenhuma — tudo mapeado."}</p></div>
          </div>

          {schema.resolveDepto && pendentesDepto.length > 0 && (
            <div className="rounded-md border border-orange-200 dark:border-orange-500/30 bg-orange-50/60 dark:bg-orange-500/15 p-3">
              <p className="mb-2 flex items-center gap-1.5 text-sm font-medium text-orange-800 dark:text-orange-300"><AlertTriangle size={14} /> {pendentesDepto.length} cargo(s) sem departamento identificado. Escolha a correspondência:</p>
              <div className="mb-3 flex items-center gap-2 text-sm"><span className="text-foreground/70">Departamento padrão:</span><select className={selCls} value={defaultDepto} onChange={(e) => setDefaultDepto(e.target.value)}><option value="">— escolher —</option>{DEPARTAMENTOS.map((x) => <option key={x}>{x}</option>)}</select><span className="text-xs text-muted-foreground/80">aplica a todos os pendentes</span></div>
              <div className="max-h-40 space-y-1.5 overflow-auto">
                {pendentesDepto.slice(0, 12).map((p) => (
                  <div key={p.i} className="flex items-center justify-between gap-2 rounded bg-card px-2.5 py-1.5 text-sm">
                    <span className="truncate text-foreground/80">{p.dados.nome} · <span className="text-muted-foreground">{p.dados.cargo || "—"}</span></span>
                    <select className={`${selCls} py-1`} value={overrides[p.i] || ""} onChange={(e) => setOverrides((o) => ({ ...o, [p.i]: e.target.value }))}><option value="">Departamento...</option>{DEPARTAMENTOS.map((x) => <option key={x}>{x}</option>)}</select>
                  </div>
                ))}
                {pendentesDepto.length > 12 && <p className="text-center text-xs text-muted-foreground/80">+{pendentesDepto.length - 12} — use o departamento padrão acima.</p>}
              </div>
            </div>
          )}

          <details className="rounded-md border border-border p-3">
            <summary className="cursor-pointer text-sm font-medium text-foreground/80">Mapeamento de colunas (detectado automaticamente — clique para ajustar)</summary>
            <div className="mt-3 grid grid-cols-1 gap-2 sm:grid-cols-2 lg:grid-cols-3">
              {campos.map((c) => (
                <label key={c.key} className="text-xs">
                  <span className="mb-0.5 block font-medium text-muted-foreground">{c.label}{c.obrig && <span className="text-destructive"> *</span>}</span>
                  <select className={`${selCls} w-full`} value={mapa[c.key] || ""} onChange={(e) => setMapa((m) => ({ ...m, [c.key]: e.target.value }))}>
                    <option value="">— não importar —</option>
                    {headers.map((h) => <option key={h} value={h}>{h}</option>)}
                  </select>
                </label>
              ))}
            </div>
          </details>

          {dups.length > 0 && (
            <div className="rounded-md border border-warning/30 bg-warning/5 p-3">
              <p className="mb-2 flex items-center gap-1.5 text-sm font-medium text-warning-ink"><AlertTriangle size={14} /> {dups.length} cadastro(s) semelhante(s) já existem ({(schema.matchKeys || []).map((k) => ({ cpf: "CPF", email: "e-mail", telefone: "telefone", whatsapp: "WhatsApp" }[k] || k)).join(" / ")}). O que fazer?</p>
              <div className="flex flex-wrap gap-3 text-sm">
                {[{ v: "atualizar", l: "Atualizar cadastro existente" }, { v: "criar", l: "Criar novo mesmo assim" }, { v: "ignorar", l: "Ignorar duplicados" }].map((o) => (
                  <label key={o.v} className="inline-flex items-center gap-1.5 text-foreground/80"><input type="radio" name="policy" checked={policy === o.v} onChange={() => setPolicy(o.v)} className="text-primary" /> {o.l}</label>
                ))}
              </div>
            </div>
          )}
          {dupsArquivo.length > 0 && (
            <p className="rounded-md border border-orange-200 dark:border-orange-500/30 bg-orange-50/60 dark:bg-orange-500/15 px-3 py-2 text-xs text-orange-800 dark:text-orange-300">{dupsArquivo.length} linha(s) estão repetidas dentro da própria planilha — cada pessoa entra uma vez só.</p>
          )}

          {/* Prévia em formato de planilha: linha numerada + cabeçalho fixo + rolagem nos 2 eixos. */}
          <div className="overflow-hidden rounded-md border border-input">
            <div className="flex items-center justify-between border-b border-border bg-secondary px-3 py-1.5 text-xs font-medium text-foreground/70">
              <span>Pré-visualização</span>
              <span className="text-muted-foreground/80">{Math.min(50, processadas.length)} de {processadas.length} linha(s)</span>
            </div>
            <div className="max-h-80 overflow-auto">
              <table className="min-w-full border-collapse text-xs">
                <thead className="sticky top-0 z-10 bg-secondary text-left text-foreground/70">
                  <tr>
                    <th className="sticky left-0 z-20 border-b border-r border-border bg-secondary px-2 py-1.5 text-center font-semibold">#</th>
                    <th className="whitespace-nowrap border-b border-r border-border px-2 py-1.5 font-semibold">Situação</th>
                    {/* Cabeçalho com o nome da coluna como está na planilha do usuário. */}
                    {camposPrevia.map((c) => <th key={c.key} className="whitespace-nowrap border-b border-r border-border px-2 py-1.5 font-semibold" title={`Importado como: ${c.label}`}>{mapa[c.key]}</th>)}
                  </tr>
                </thead>
                <tbody>{previa.map((p) => (
                  <tr key={p.i} className={p.erros.length ? "bg-destructive/5" : p.dupArquivo ? "bg-orange-50/50 dark:bg-orange-500/15" : p.match ? "bg-warning/5" : "odd:bg-card even:bg-secondary/25"}>
                    <td className="sticky left-0 border-b border-r border-border bg-secondary px-2 py-1 text-center font-medium text-muted-foreground/80">{p.i + 1}</td>
                    <td className="whitespace-nowrap border-b border-r border-border px-2 py-1">
                      {p.erros.length ? <span className="text-destructive">{p.erros.join("; ")}</span>
                        : p.dupArquivo ? <Badge cls="bg-orange-50 dark:bg-orange-500/15 text-orange-700 dark:text-orange-300">Repetido na planilha</Badge>
                        : p.match ? <Badge cls="bg-warning/8 text-warning-ink">Já existe: {p.match.nome}</Badge>
                        : <Badge cls="bg-success/8 text-success">Novo</Badge>}
                    </td>
                    {camposPrevia.map((c) => (
                      <td key={c.key} className={`whitespace-nowrap border-b border-r border-border px-2 py-1 ${c.key === "area" && !p.dados.area ? "bg-orange-100/60 dark:bg-orange-500/15 text-orange-700 dark:text-orange-300" : "text-foreground/70"}`}>
                        {valorPrevia(p.dados, c.key) || "—"}
                      </td>
                    ))}
                  </tr>
                ))}</tbody>
              </table>
            </div>
          </div>
          {processadas.length > 50 && <p className="text-center text-xs text-muted-foreground/80">Mostrando as 50 primeiras de {processadas.length} linhas. Todas as válidas serão importadas.</p>}
        </div>
      )}
    </Modal>
  );
}
function Funcionarios({ funcionarios, setFuncionarios, ativos, atualizarFunc, config, globalQuery, documentos, setDocumentos, setPagamentos = () => {}, setAtestados = () => {}, empresaPermitida = "", funcFiltroInicial = null, setFuncFiltroInicial = () => {}, abrirFunc = null, setAbrirFunc = () => {}, nomeUsuario = "Administrador" }) {
  const [aberto, setAberto] = useState(false);
  const [edit, setEdit] = useState(null);
  // Apagar em FONTE ÚNICA: remove o funcionário E tudo que aponta pra ele (pagamentos, atestados,
  // documentos) — assim ninguém apagado sobra em nenhuma outra tela.
  const purgar = (ids) => {
    const s = new Set(ids);
    // Limpa também os arquivos FÍSICOS no Storage (documentos + anexos de atestados) — senão ficam órfãos no bucket.
    (documentos || []).forEach((x) => { if (s.has(x.funcId) && x.storagePath) docRemove(x); });
    setFuncionarios((p) => p.filter((f) => !s.has(f.id)));
    setPagamentos((p) => (p || []).filter((x) => !s.has(x.funcionarioId)));
    setAtestados((p) => { (p || []).forEach((x) => { if (s.has(x.funcId)) (x.anexos || []).forEach((an) => { if (an.storagePath) docRemove(an); }); }); return (p || []).filter((x) => !s.has(x.funcId)); });
    setDocumentos((p) => (p || []).filter((x) => !s.has(x.funcId)));
  };
  const [ver, setVer] = useState(null);
  const [ft, setFt] = useState(() => (funcFiltroInicial ? { ...FILTRO_VAZIO, ...funcFiltroInicial } : FILTRO_VAZIO));
  const [maisFiltros, setMaisFiltros] = useState(!!(funcFiltroInicial && (funcFiltroInicial.admDe || funcFiltroInicial.admAte)));
  const [importar, setImportar] = useState(false);
  const [formTab, setFormTab] = useState("pessoais"); // aba do FuncForm ao abrir por notificação
  const [verTab, setVerTab] = useState("resumo");      // aba do FuncView ao abrir por notificação
  // Consome o filtro inicial vindo do Dashboard (KPIs clicáveis) e o zera para não "grudar".
  useEffect(() => {
    if (!funcFiltroInicial) return;
    setFt({ ...FILTRO_VAZIO, ...funcFiltroInicial });
    if (funcFiltroInicial.admDe || funcFiltroInicial.admAte) setMaisFiltros(true);
    setFuncFiltroInicial(null);
  }, [funcFiltroInicial]);
  // Abre o cadastro/visualização de um funcionário na aba certa (a partir de uma notificação).
  useEffect(() => {
    if (!abrirFunc?.id) return;
    const f = funcionarios.find((x) => x.id === abrirFunc.id);
    if (f) {
      if (abrirFunc.view === "docs") { setVerTab("docs"); setVer(f); }
      else { setFormTab(abrirFunc.tab || "pessoais"); setEdit(f); setAberto(true); }
    }
    setAbrirFunc(null);
  }, [abrirFunc]);
  const aplicarImport = ({ criar, atualizar }) => setFuncionarios((p) => {
    const byId = new Map((atualizar || []).map((a) => [a.id, a.patch]));
    const atualizados = p.map((f) => (byId.has(f.id) ? { ...f, ...byId.get(f.id) } : f));
    return [...atualizados, ...(criar || [])];
  });
  const lista = funcionarios.filter((f) => aplicaFiltros(f, ft));
  const setF = (k, v) => setFt((p) => ({ ...p, [k]: v }));
  function salvar(d) { setFuncionarios((p) => (p.some((f) => f.id === d.id) ? p.map((f) => (f.id === d.id ? d : f)) : [...p, d])); setAberto(false); setEdit(null); setFormTab("pessoais"); }
  // Efetivar/Estender pela lista usam a MESMA fonte única do painel Treinamento (sem divergência).
  const [efetivarFunc, setEfetivarFunc] = useState(null);
  const efetivar = (f) => setEfetivarFunc(f); // abre a tela manual de efetivação (escolher contrato/datas)
  const estender = (f) => { const t = f.treinamento || {}; const ini = toISODate(t.data_inicio || f.dataAdmissao || ""); gravarTreinamento(atualizarFunc, f, { data_inicio: ini, dias_treinamento: 30, data_fim: dataFimTreino(ini, 30), status: "Prorrogado" }); };
  const rowsExport = lista.map((f) => [f.nome, f.empresa, f.departamento || "—", f.cargo || "—", f.tipoContrato, f.gestor || "—", isRegistrado(f) ? "Registrado" : "Não reg.", f.status, fmtBRL(f.salarioBase)]);
  const filtrosAtivos = Object.entries(ft).filter(([k, v]) => v && v !== "Todas" && v !== "Todos" && !(k === "situacao" && v === "Ativos")).length;
  const nDocs = (fid) => documentos.filter((d) => d.funcId === fid && !d.pagamentoId).length;

  const columns = [
    { key: "nome", header: "Funcionário", get: (f) => f.nome, cell: (f) => (<button type="button" onClick={() => { setEdit(f); setAberto(true); }} className="text-left hover:text-primary"><p className="font-medium text-foreground hover:text-primary">{f.nome || "—"}</p><p className="text-xs text-muted-foreground/80">{f.tipoContrato}{f.gestor ? " · " + f.gestor : ""}</p></button>) },
    { key: "empresa", header: "Empresa", get: (f) => f.empresa },
    { key: "departamento", header: "Departamento", get: (f) => f.departamento || "" , cell: (f) => f.departamento || "—" },
    { key: "cargo", header: "Cargo", get: (f) => f.cargo || "", cell: (f) => f.cargo || "—" },
    { key: "trein", header: "Treinamento", sortable: false, get: () => "", cell: (f) => { const t = calcTreinamento(f); if (!t || !t.emTreinamento) return <span className="text-muted-foreground/50">—</span>; return t.diasRestantes == null ? <Badge cls="bg-warning/8 text-warning-ink">em treino</Badge> : <TagDias dias={t.diasRestantes} />; } },
    { key: "status", header: "Status", get: (f) => f.status, cell: (f) => <Badge cls={STATUS_COR[f.status]}>{f.status}</Badge> },
    { key: "salarioBase", header: "Salário", type: "number", align: "right", get: (f) => num(f.salarioBase), cell: (f) => <span className="font-medium text-foreground">{fmtBRL(f.salarioBase)}</span> },
  ];
  const filtros = (
    <>
      <select className={selCls} value={ft.situacao} onChange={(e) => setF("situacao", e.target.value)}><option>Ativos</option><option>Todos</option><option>Em treinamento</option><option>Desligados</option></select>
      {!empresaPermitida && <select className={selCls} value={ft.empresa} onChange={(e) => setF("empresa", e.target.value)}><option>Todas</option>{EMPRESAS.map((x) => <option key={x}>{x}</option>)}</select>}
      <select className={selCls} value={ft.departamento} onChange={(e) => setF("departamento", e.target.value)}><option>Todos</option>{DEPARTAMENTOS.map((x) => <option key={x}>{x}</option>)}</select>
      <select className={selCls} value={ft.registro} onChange={(e) => setF("registro", e.target.value)}><option>Todos</option><option>Registrado</option><option>Não Registrado</option></select>
      <select className={selCls} value={ft.contrato} onChange={(e) => setF("contrato", e.target.value)}><option value="Todos">Contrato: todos</option>{TIPOS_CONTRATO.map((x) => <option key={x} value={x}>{x}</option>)}</select>
      <select className={selCls} value={ft.beneficio} onChange={(e) => setF("beneficio", e.target.value)}><option value="Todos">Benefício: todos</option><option value="VT">Recebe VT</option><option value="VR">Recebe VR</option></select>
      <Btn size="sm" variant="secondary" onClick={() => setMaisFiltros((m) => !m)}><Filter size={13} /> Filtros{filtrosAtivos > 0 && <span className="ml-1 rounded-full bg-primary/15 px-1.5 text-primary">{filtrosAtivos}</span>}</Btn>
      {filtrosAtivos > 0 && <Btn size="sm" variant="secondary" onClick={() => setFt(FILTRO_VAZIO)}><X size={13} /></Btn>}
    </>
  );
  const novo = () => { setEdit(novoFunc(config, empresaPermitida ? { empresa: empresaPermitida } : {})); setAberto(true); };

  return (
    <div className="space-y-4">
      <PageHeader titulo="Funcionários" subtitulo={`${lista.length} registro(s) · ${ft.situacao}`}>
        <ExportButtons titulo="Funcionarios" headers={["Nome", "Empresa", "Departamento", "Cargo", "Contrato", "Gestor", "Registro", "Status", "Salário"]} rows={rowsExport} resumo={`${lista.length} funcionário(s).`} />
        <Btn variant="secondary" onClick={() => setImportar(true)}><Upload size={16} /> Importar</Btn>
        <Btn onClick={novo}><UserPlus size={16} /> Novo funcionário</Btn>
      </PageHeader>
      {maisFiltros && (
        <Card className="p-4"><div className="grid grid-cols-1 gap-3 sm:grid-cols-3 lg:grid-cols-5">
          <Field label="Cargo"><Combobox value={ft.cargo} onChange={(v) => setF("cargo", v)} options={config.cargos || CARGOS_LISTA} placeholder="Todos" allowCustom /></Field>
          <Field label="Status"><select className={inputCls} value={ft.status} onChange={(e) => setF("status", e.target.value)}><option>Todos</option>{STATUS_LIST.map((s) => <option key={s}>{s}</option>)}</select></Field>
          <Field label="Gestor"><input className={inputCls} value={ft.gestor} onChange={(e) => setF("gestor", e.target.value)} /></Field>
          <Field label="Admissão de"><input type="date" className={inputCls} value={ft.admDe} onChange={(e) => setF("admDe", e.target.value)} /></Field>
          <Field label="Admissão até"><input type="date" className={inputCls} value={ft.admAte} onChange={(e) => setF("admAte", e.target.value)} /></Field>
        </div></Card>
      )}
      <DataTable columns={columns} rows={lista} initialQuery={globalQuery} searchPlaceholder="Buscar por nome, cargo, departamento..." selectable pageSize={12}
        filtros={filtros}
        bulkActions={(ids, clear) => (<Btn size="sm" variant="danger" onClick={() => { const travados = funcionarios.filter((f) => ids.includes(f.id) && f.treinamento?.encerramento?.fechado); if (travados.length) alert(`${travados.length} funcionário(s) com encerramento de treinamento FECHADO (registro imutável) não podem ser excluídos e serão mantidos.`); const excluir = ids.filter((id) => !travados.some((t) => t.id === id)); if (excluir.length && confirm(`Excluir ${excluir.length} funcionário(s)? Isso remove também pagamentos, atestados e documentos ligados a eles.`)) { purgar(excluir); clear(); } }}><Trash2 size={13} /> Excluir</Btn>)}
        actions={(f) => { const t = calcTreinamento(f); const emTrein = t && t.emTreinamento; return (
          <RowActions onView={() => setVer(f)} onEdit={() => { setEdit(f); setAberto(true); }} onDelete={() => { if (f.treinamento?.encerramento?.fechado) { alert("Este funcionário tem um encerramento de treinamento FECHADO (registro imutável) e não pode ser excluído."); return; } if (confirm(`Excluir ${f.nome}? Isso remove também pagamentos, atestados e documentos ligados a ele.`)) purgar([f.id]); }}
            extra={emTrein && <MoreMenu><MoreItem icon={CheckCircle2} onClick={() => efetivar(f)}>Efetivar (CLT)</MoreItem>{num(f.treinamentoDias) === 15 && <MoreItem icon={Clock} onClick={() => estender(f)}>Estender p/ 30 dias</MoreItem>}</MoreMenu>} />
        ); }}
        vazio="Nenhum funcionário encontrado." />
      {aberto && <FuncForm inicial={edit} onSalvar={salvar} onFechar={() => { setAberto(false); setEdit(null); setFormTab("pessoais"); }} config={config} empresaPermitida={empresaPermitida} initialTab={formTab} />}
      {importar && <SmartImport schema={SCHEMA_FUNC} existentes={funcionarios} onClose={() => setImportar(false)} onImportar={aplicarImport} />}
      {efetivarFunc && <EfetivarTreinoModal func={efetivarFunc} nomeUsuario={nomeUsuario} atualizarFunc={atualizarFunc} onClose={() => setEfetivarFunc(null)} />}
      {ver && <FuncView func={ver} config={config} documentos={documentos} setDocumentos={setDocumentos} onClose={() => { setVer(null); setVerTab("resumo"); }} onEditar={() => { setEdit(ver); setVer(null); setAberto(true); }} initialTab={verTab} />}
    </div>
  );
}

const BenefToggle = ({ label, ativo, onToggle, children }) => (
  <div className="rounded-md border border-border p-3"><label className="flex items-center gap-2 text-sm font-medium text-foreground/80"><input type="checkbox" checked={ativo} onChange={(e) => onToggle(e.target.checked)} className="h-4 w-4 rounded border-input text-primary" />{label}</label>{ativo && <div className="mt-3">{children}</div>}</div>
);

function FuncForm({ inicial, onSalvar, onFechar, config, initialTab = "pessoais", empresaPermitida = "" }) {
  const [d, setD] = useState(inicial);
  const [tab, setTab] = useState(initialTab);
  const set = (k, v) => setD((p) => ({ ...p, [k]: v }));
  const setB = (chave, patch) => setD((p) => ({ ...p, beneficios: { ...p.beneficios, [chave]: { ...p.beneficios[chave], ...patch } } }));
  const setConducao = (key, patch) => setD((p) => ({ ...p, beneficios: { ...p.beneficios, vt: { ...p.beneficios.vt, conducoes: { ...p.beneficios.vt.conducoes, [key]: { ...p.beneficios.vt.conducoes[key], ...patch } } } } }));
  const setTipo = (v) => setD((p) => ({ ...p, tipoContrato: v, dataRegistro: v === "CLT Ativo" && !p.dataRegistro && p.dataAdmissao ? p.dataAdmissao : p.dataRegistro, treinamentoDias: v === "Treinamento" ? (p.treinamentoDias || 30) : p.treinamentoDias }));
  // Empresa Alexandre so aceita estagiarios: ao selecionar, forca o tipo para Estagio.
  const setEmpresa = (v) => setD((p) => ({ ...p, empresa: v, tipoContrato: EMPRESAS_SO_ESTAGIO.includes(v) ? "Estágio" : p.tipoContrato }));
  const soEstagio = EMPRESAS_SO_ESTAGIO.includes(d.empresa);
  const cargosOpc = [...new Set([...(config.cargos || CARGOS_LISTA), d.cargo].filter(Boolean))];
  // Ao escolher o cargo, sugere o salario padrao (config.salariosPorCargo) SE o campo estiver vazio ou ainda no padrao do cargo anterior.
  const salPorCargo = config.salariosPorCargo || SALARIOS_PADRAO;
  const setCargo = (v) => setD((p) => {
    const padrao = salPorCargo[(v || "").trim()];
    const atual = num(p.salarioBase);
    const anteriorPadrao = salPorCargo[(p.cargo || "").trim()];
    const podePreencher = padrao != null && (atual === 0 || (anteriorPadrao != null && atual === anteriorPadrao));
    return { ...p, cargo: v, salarioBase: podePreencher ? padrao : p.salarioBase };
  });
  const det = calcVTDetalhe(d, config);
  const vt = d.beneficios.vt;
  const adi = d.beneficios.adiantamento;
  const autoReg = CONTRATOS_REGISTRADOS.includes(d.tipoContrato);
  const ehTreinamento = d.tipoContrato === "Treinamento";
  const setTrein = (patch) => setD((p) => ({ ...p, treinamento: { ...(p.treinamento || {}), ...patch } }));
  const treinInicio = d.treinamento?.data_inicio || d.dataAdmissao || "";
  const treinFim = dataFimTreino(treinInicio, num(d.treinamentoDias) || 30);
  // Ao salvar um Treinamento, consolida o registro único f.treinamento (início/término/duração + VT/VR).
  const salvar = () => {
    if (d.tipoContrato !== "Treinamento") return onSalvar(d);
    const dur = num(d.treinamentoDias) || 30;
    onSalvar({ ...d, dataAdmissao: d.dataAdmissao || treinInicio, treinamento: { ...(d.treinamento || {}), data_inicio: treinInicio, dias_treinamento: dur, data_fim: dataFimTreino(treinInicio, dur), dias_corridos: dur, vt_ativo: !!d.beneficios?.vt?.ativo, vr_ativo: !!d.beneficios?.vr?.ativo, status: d.treinamento?.status || TREIN_STATUS[0], atualizado_em: hojeISO() } });
  };
  // Busca de endereço pelo CEP (ViaCEP). Preenche rua/bairro/cidade/estado; número e
  // complemento continuam por conta do usuário. Não trava o cadastro se a API falhar.
  const [buscandoCep, setBuscandoCep] = useState(false);
  const [cepErro, setCepErro] = useState("");
  const buscarCep = async (cepRaw) => {
    const cep = soDigitos(cepRaw); if (cep.length !== 8) return;
    setBuscandoCep(true); setCepErro("");
    try {
      const r = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
      const j = await r.json();
      if (j.erro) { setCepErro("CEP não encontrado."); return; }
      setD((p) => ({ ...p, rua: j.logradouro || p.rua, bairro: j.bairro || p.bairro, cidade: j.localidade || p.cidade, estado: j.uf || p.estado }));
    } catch { setCepErro("Não foi possível consultar o CEP agora."); }
    finally { setBuscandoCep(false); }
  };
  const conv = d.convenio || {};
  const setConv = (patch) => setD((p) => ({ ...p, convenio: { ...p.convenio, ...patch } }));
  const convI = convenioInfo(d);
  const tabs = [{ id: "pessoais", label: "Dados Pessoais", icon: User }, { id: "contrato", label: "Contrato", icon: Briefcase }, { id: "beneficios", label: "Benefícios", icon: Gift }, { id: "convenio", label: "Convênio Médico", icon: Stethoscope }, { id: "pagamento", label: "Pagamento", icon: Banknote }];
  return (
    <Modal title={inicial.nome ? "Editar funcionário" : "Novo funcionário"} subtitle={inicial.nome ? `${inicial.cargo || ""} · ${inicial.empresa}` : "Cadastro completo"} onClose={onFechar} max="max-w-3xl"
      footer={<><Btn variant="secondary" onClick={onFechar}>Cancelar</Btn><Btn onClick={salvar}><Save size={16} /> Salvar</Btn></>}>
      <div className="mb-4"><Tabs tabs={tabs} active={tab} onChange={setTab} /></div>
      {tab === "pessoais" && (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <Field label="Nome completo"><input className={inputCls} value={d.nome} onChange={(e) => set("nome", e.target.value)} /></Field>
          <Field label="CPF"><MaskedInput tipo="cpf" value={d.cpf} onChange={(v) => set("cpf", v)} /></Field>
          <Field label="Código / Matrícula" hint="usado para casar as planilhas da contabilidade"><input className={inputCls} value={d.matricula || ""} onChange={(e) => set("matricula", e.target.value)} placeholder="ex.: 1042" /></Field>
          <Field label="RG" hint="somente números"><MaskedInput tipo="num" maxDigits={12} value={d.rg} onChange={(v) => set("rg", v)} /></Field>
          <Field label="PIS/PASEP"><MaskedInput tipo="pis" value={d.pis} onChange={(v) => set("pis", v)} /></Field>
          <Field label="CTPS (número)"><MaskedInput tipo="num" maxDigits={12} value={d.ctps} onChange={(v) => set("ctps", v)} /></Field>
          <Field label="CNH (número)"><MaskedInput tipo="num" maxDigits={11} value={d.cnh} onChange={(v) => set("cnh", v)} /></Field>
          <Field label="Data de nascimento"><input type="date" className={inputCls} value={d.dataNascimento} onChange={(e) => set("dataNascimento", e.target.value)} /></Field>
          <Field label="Dependentes"><input type="number" className={inputCls} value={d.dependentes} onChange={(e) => set("dependentes", e.target.value)} /></Field>
          <Field label="E-mail"><input className={inputCls} value={d.email} onChange={(e) => set("email", e.target.value)} placeholder="nome@email.com" /></Field>
          <Field label="Telefone"><MaskedInput tipo="telefone" value={d.telefone} onChange={(v) => set("telefone", v)} /></Field>
          {/* Endereço completo. Ao digitar o CEP (8 dígitos), preenche rua/bairro/cidade/estado. */}
          <div className="sm:col-span-2 mt-1 border-t border-border/60 pt-3"><p className="mb-2 flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground/80"><MapPin size={13} /> Endereço</p>
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <Field label="CEP" hint={buscandoCep ? "buscando..." : cepErro || "preenche o endereço"}><MaskedInput tipo="cep" value={d.cep} onChange={(v) => { set("cep", v); if (soDigitos(v).length === 8) buscarCep(v); }} /></Field>
              <Field label="Rua / Logradouro"><input className={inputCls} value={d.rua || ""} onChange={(e) => set("rua", e.target.value)} /></Field>
              <Field label="Número"><input className={inputCls} value={d.numero || ""} onChange={(e) => set("numero", e.target.value)} /></Field>
              <Field label="Complemento"><input className={inputCls} value={d.complemento || ""} onChange={(e) => set("complemento", e.target.value)} placeholder="Apto, bloco..." /></Field>
              <Field label="Bairro"><input className={inputCls} value={d.bairro || ""} onChange={(e) => set("bairro", e.target.value)} /></Field>
              <Field label="Cidade"><input className={inputCls} value={d.cidade || ""} onChange={(e) => set("cidade", e.target.value)} /></Field>
              <Field label="Estado (UF)"><input className={inputCls} maxLength={2} value={d.estado || ""} onChange={(e) => set("estado", e.target.value.toUpperCase())} placeholder="SP" /></Field>
            </div>
          </div>
        </div>
      )}
      {tab === "contrato" && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <Field label="Empresa"><select className={inputCls} value={empresaPermitida || d.empresa} onChange={(e) => setEmpresa(e.target.value)} disabled={!!empresaPermitida}>{(empresaPermitida ? [empresaPermitida] : empresasCom(d.empresa)).map((x) => <option key={x}>{x}</option>)}</select></Field>
            <Field label="Departamento"><Combobox value={d.departamento} onChange={(v) => set("departamento", v)} options={DEPARTAMENTOS} placeholder="Selecione..." /></Field>
            <Field label="Cargo" hint="Lista padronizada · sugere o salário"><Combobox value={d.cargo} onChange={setCargo} options={cargosOpc} placeholder="Selecione..." /></Field>
            <Field label="Gestor responsável"><input className={inputCls} value={d.gestor} onChange={(e) => set("gestor", e.target.value)} /></Field>
            <Field label="Tipo de contratação" hint={soEstagio ? `${d.empresa}: somente Estágio` : undefined}><select className={inputCls} value={d.tipoContrato} onChange={(e) => setTipo(e.target.value)} disabled={soEstagio}>{(soEstagio ? ["Estágio"] : TIPOS_CONTRATO).map((t) => <option key={t}>{t}</option>)}</select></Field>
            <Field label="Status"><select className={inputCls} value={d.status} onChange={(e) => set("status", e.target.value)}>{STATUS_LIST.map((s) => <option key={s}>{s}</option>)}</select></Field>
            <Field label="Data de admissão"><input type="date" className={inputCls} value={d.dataAdmissao} onChange={(e) => set("dataAdmissao", e.target.value)} /></Field>
            <Field label="Data de registro" hint={autoReg ? `${d.tipoContrato} é registrado automaticamente` : "Vazio = não registrado"}><input type="date" className={`${inputCls} ${autoReg ? "bg-success/5" : ""}`} value={d.dataRegistro} onChange={(e) => set("dataRegistro", e.target.value)} /></Field>
            <Field label="Fim de contrato (opcional)" hint="Temporário/estágio"><input type="date" className={inputCls} value={d.dataFimContrato} onChange={(e) => set("dataFimContrato", e.target.value)} /></Field>
            <Field label="Salário"><MoedaInput value={d.salarioBase} onChange={(v) => set("salarioBase", v)} /></Field>
          </div>
          {autoReg && <p className="flex items-center gap-1.5 rounded-md bg-success/8 px-3 py-2 text-xs text-success"><CheckCheck size={13} /> Contrato {d.tipoContrato}: funcionário marcado automaticamente como registrado.</p>}
          {ehTreinamento && (
            <div className="space-y-3 rounded-md border border-warning/30 bg-warning/5 p-3">
              <p className="flex items-center gap-1.5 text-xs font-semibold text-warning-ink"><CalendarClock size={13} /> Treinamento (etapa de admissão) — campos obrigatórios</p>
              <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
                <Field label="Início do treinamento"><input type="date" className={inputCls} value={treinInicio} onChange={(e) => setTrein({ data_inicio: e.target.value })} /></Field>
                <Field label="Duração (dias)" hint="Máximo 30 dias"><input type="number" min="1" max="30" className={inputCls} value={num(d.treinamentoDias) || 30} onChange={(e) => set("treinamentoDias", Math.min(Math.max(num(e.target.value), 0), 30))} /></Field>
                <Field label="Término" hint="Automático (início + duração)"><div className={`${inputCls} flex items-center bg-card text-foreground/70`}>{treinFim ? fmtData(treinFim) : "—"}</div></Field>
              </div>
              <Field label="Outros benefícios (valor fixo do treino)" hint="Opcional — somado ao total a pagar"><MoedaInput value={d.treinamento?.outros_beneficios} onChange={(v) => setTrein({ outros_beneficios: v })} /></Field>
              <p className="text-xs text-warning-ink">Valor diário automático: <strong>{fmtBRL(valorDiaSalario(num(d.salarioBase), config, treinInicio || hojeISO()))}</strong> (salário ÷ {diasBaseSalario(config, treinInicio || hojeISO())}, dias de {compLabel((treinInicio || hojeISO()).slice(0, 7))}). No treinamento paga-se somente os <strong>dias reais trabalhados</strong>, mês a mês — se o período atravessar a virada do mês, cada trecho conta pelos dias do seu próprio mês.</p>
              <p className="text-xs text-warning-ink"><strong>Não conta como registrado.</strong> Ao efetivar, vira CLT Ativo. Vale-transporte e vale-refeição são definidos na aba <strong>Benefícios</strong>.</p>
            </div>
          )}
        </div>
      )}
      {tab === "beneficios" && (
        <div className="space-y-3">
          <BenefToggle label="Vale-Transporte" ativo={vt.ativo} onToggle={(v) => setB("vt", { ativo: v })}>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <Field label="Forma de cálculo"><select className={inputCls} value={vt.modo || "passagens"} onChange={(e) => setB("vt", { modo: e.target.value })}><option value="passagens">Por quantidade de passagens</option><option value="valorDia">Por valor gasto por dia</option></select></Field>
              <Field label="Frequência de pagamento"><select className={inputCls} value={vt.frequencia} onChange={(e) => setB("vt", { frequencia: e.target.value })}>{Object.entries(VT_FREQ).map(([k, v]) => <option key={k} value={k}>{v.label}</option>)}</select></Field>
            </div>
            {vt.modo === "valorDia" ? (
              <div className="mt-3"><Field label="Valor total gasto por dia"><MoedaInput value={vt.valorDia} onChange={(v) => setB("vt", { valorDia: v })} /></Field></div>
            ) : (
              <div className="mt-3"><p className="mb-1.5 text-xs font-medium text-muted-foreground">Conduções por dia (quantidade × valor)</p><div className="grid grid-cols-1 gap-2 sm:grid-cols-2">{CONDUCOES.map((c) => (
                <div key={c.key} className="flex items-end gap-2 rounded-md border border-border p-2"><div className="w-16 shrink-0 pb-2 text-sm font-medium text-foreground/70">{c.label}</div><Field label="Qtd/dia"><input type="number" min="0" className={inputCls} value={vt.conducoes[c.key].qtd} onChange={(e) => setConducao(c.key, { qtd: e.target.value })} /></Field><Field label="Valor"><MoedaInput value={vt.conducoes[c.key].valor} onChange={(v) => setConducao(c.key, { valor: v })} /></Field></div>
              ))}</div></div>
            )}
            <div className="mt-3 rounded-md bg-secondary/50 p-2 text-xs"><span className="text-muted-foreground/80">Valor/dia </span><span className="font-semibold text-foreground/80">{fmtBRL(det.valorDiario)}</span><span className="text-muted-foreground/80"> · Empresa custeia </span><span className="font-semibold text-primary">{fmtBRL(det.empresa)}/mês</span></div>
          </BenefToggle>
          <BenefToggle label="Vale-Refeição" ativo={d.beneficios.vr.ativo} onToggle={(v) => setB("vr", { ativo: v })}>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
              <Field label="Valor por dia" hint={`Vazio = padrão (${fmtBRL(config.vrDiario)})`}><MoedaInput value={d.beneficios.vr.valorDia} onChange={(v) => setB("vr", { valorDia: v })} /></Field>
              <Field label="Dias no mês" hint={`Vazio = ${diasBaseVR(config)} (base do mês)`}><input type="number" className={inputCls} value={d.beneficios.vr.diasTrabalhados} onChange={(e) => setB("vr", { diasTrabalhados: e.target.value })} placeholder={`${diasBaseVR(config)}`} /></Field>
              <div className="rounded-md bg-secondary/50 p-2 text-xs"><p className="text-muted-foreground/80">Valor total ({fmtBRL(config.vrDiario)}/dia)</p><p className="font-semibold text-foreground/80">{fmtBRL(vrInfo({ ...d }, config)?.valorMensal || 0)}</p></div>
            </div>
          </BenefToggle>
          <BenefToggle label="Adiantamento Salarial" ativo={adi.ativo} onToggle={(v) => setB("adiantamento", { ativo: v })}>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
              <Field label="Tipo"><select className={inputCls} value={adi.tipo} onChange={(e) => setB("adiantamento", { tipo: e.target.value })}><option value="padrao">Padrão ({config.percentualAdiant}%)</option><option value="personalizado">Percentual personalizado</option><option value="valor">Valor manual (R$)</option></select></Field>
              {adi.tipo === "personalizado" && <Field label="% do salário"><input type="number" className={inputCls} value={adi.percentual} onChange={(e) => setB("adiantamento", { percentual: e.target.value })} /></Field>}
              {adi.tipo === "valor" && <Field label="Valor do adiantamento"><MoedaInput value={adi.valorManual} onChange={(v) => setB("adiantamento", { valorManual: v })} /></Field>}
            </div>
            <div className="mt-2 grid grid-cols-3 gap-2 rounded-md bg-secondary/50 p-2 text-xs"><div><p className="text-muted-foreground/80">Adiantamento</p><p className="font-semibold text-foreground/80">{fmtBRL(valorAdiantamento(d, config))} ({pctAdiantamento(d, config).toFixed(0)}%)</p></div><div className="col-span-2"><p className="text-muted-foreground/80">Salário − adiantamento (referência)</p><p className="font-semibold text-foreground/80">{fmtBRL(liquidoFolha(d, config))}</p><p className="text-[11px] text-muted-foreground/80">Não é o líquido da folha — o líquido oficial vem do Extrato Mensal.</p></div></div>
          </BenefToggle>
        </div>
      )}
      {tab === "convenio" && (
        <div className="space-y-3">
          <BenefToggle label="Convênio Médico" ativo={conv.ativo} onToggle={(v) => setConv({ ativo: v })}>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <Field label="Nome do convênio"><input className={inputCls} value={conv.nome || ""} onChange={(e) => setConv({ nome: e.target.value })} placeholder="Ex.: Unimed, Amil..." /></Field>
              <Field label="Valor mensal"><MoedaInput value={conv.valorMensal} onChange={(v) => setConv({ valorMensal: v })} /></Field>
              <Field label="% descontado do funcionário"><input type="number" min="0" max="100" className={inputCls} value={conv.percentualFunc} onChange={(e) => setConv({ percentualFunc: e.target.value })} /></Field>
              <Field label="% pago pela empresa"><input type="number" min="0" max="100" className={inputCls} value={conv.percentualEmpresa} onChange={(e) => setConv({ percentualEmpresa: e.target.value })} /></Field>
            </div>
            <div className="mt-3 grid grid-cols-1 gap-2 text-xs sm:grid-cols-3">
              <div className="rounded-md bg-secondary/50 p-2"><p className="text-muted-foreground/80">Valor mensal</p><p className="font-semibold text-foreground/80">{fmtBRL(convI.valorMensal)}</p></div>
              <div className="rounded-md bg-destructive/8 p-2"><p className="text-destructive">Desconto do funcionário</p><p className="font-semibold text-destructive">{fmtBRL(convI.descontoFunc)}</p></div>
              <div className="rounded-md bg-primary/8 p-2"><p className="text-primary">Empresa custeia</p><p className="font-semibold text-primary">{fmtBRL(convI.parteEmpresa)}</p></div>
            </div>
            {num(conv.percentualFunc) + num(conv.percentualEmpresa) !== 100 && (conv.percentualFunc || conv.percentualEmpresa) ? <p className="mt-2 text-xs text-warning-ink">Atenção: os percentuais somam {num(conv.percentualFunc) + num(conv.percentualEmpresa)}% (o normal é 100%).</p> : null}
          </BenefToggle>
        </div>
      )}
      {tab === "pagamento" && (
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <Field label="Banco"><input className={inputCls} value={d.banco} onChange={(e) => set("banco", e.target.value)} /></Field>
          <Field label="Tipo de conta"><select className={inputCls} value={d.tipoConta} onChange={(e) => set("tipoConta", e.target.value)}>{TIPOS_CONTA.map((t) => <option key={t}>{t}</option>)}</select></Field>
          <Field label="Agência" hint="somente números"><MaskedInput tipo="num" maxDigits={6} value={d.agencia} onChange={(v) => set("agencia", v)} /></Field>
          <Field label="Conta" hint="somente números"><MaskedInput tipo="num" maxDigits={14} value={d.conta} onChange={(v) => set("conta", v)} /></Field>
          <Field label="Tipo da chave PIX"><select className={inputCls} value={d.tipoChavePix} onChange={(e) => set("tipoChavePix", e.target.value)}>{TIPOS_PIX.map((t) => <option key={t}>{t}</option>)}</select></Field>
          <Field label="Chave PIX"><input className={inputCls} value={d.chavePix} onChange={(e) => set("chavePix", e.target.value)} /></Field>
          <Field label="Nome do titular"><input className={inputCls} value={d.titular} onChange={(e) => set("titular", e.target.value)} /></Field>
        </div>
      )}
    </Modal>
  );
}
function FuncView({ func: f, config, documentos = [], setDocumentos, onClose, onEditar, initialTab = "resumo" }) {
  const [tab, setTab] = useState(initialTab);
  const Linha = ({ k, v }) => (<div className="flex justify-between gap-4 py-1.5 text-sm"><span className="text-muted-foreground/80">{k}</span><span className="text-right font-medium text-foreground/80">{v}</span></div>);
  const docsF = documentos.filter((d) => d.funcId === f.id && !d.pagamentoId);
  async function up(e, categoria) {
    const files = Array.from(e.target.files || []);
    for (const file of files) {
      const id = uid();
      try { const storagePath = await docUpload(file, f.id, id); setDocumentos((prev) => [...prev, { id, funcId: f.id, categoria, nome: file.name, tipo: file.type, tamanho: file.size, dataUpload: hojeISO(), storagePath, historico: [{ id: uid(), data: hojeISO(), acao: "Enviado" }] }]); }
      catch (err) { alert("Falha ao enviar " + file.name + ": " + (err?.message || err)); }
    }
    e.target.value = "";
  }
  async function abrir(doc) { const url = await docUrl(doc); if (url) window.open(url, "_blank"); else alert("Arquivo não disponível — envie novamente."); }
  function excluir(doc) { if (!confirm(`Excluir ${doc.nome}?`)) return; setDocumentos((prev) => prev.filter((x) => x.id !== doc.id)); }
  const tabs = [{ id: "resumo", label: "Resumo", icon: User }, { id: "docs", label: `Documentos (${docsF.length})`, icon: FolderCheck }];
  return (
    <Modal title={f.nome} subtitle={`${f.cargo || "—"} · ${f.departamento || "—"} · ${f.empresa}`} onClose={onClose} max="max-w-2xl" footer={<><Btn variant="secondary" onClick={onClose}>Fechar</Btn><Btn onClick={onEditar}><Pencil size={15} /> Editar</Btn></>}>
      {/* Aba "Documentos" removida do cadastro de funcionário (a pedido). */}
      {tab === "resumo" ? (
        <div className="space-y-4">
          <div className="grid grid-cols-1 gap-x-8 sm:grid-cols-2">
            <div className="divide-y divide-border/60"><Linha k="CPF" v={f.cpf ? fmtCPF(f.cpf) : "—"} /><Linha k="Status" v={<Badge cls={STATUS_COR[f.status]}>{f.status}</Badge>} /><Linha k="Registro" v={isRegistrado(f) ? "Registrado" : "Não registrado"} /><Linha k="Contrato" v={f.tipoContrato} /><Linha k="Departamento" v={f.departamento || "—"} /><Linha k="Cargo" v={f.cargo || "—"} /><Linha k="Admissão" v={fmtData(f.dataAdmissao)} /></div>
            <div className="divide-y divide-border/60"><Linha k="Salário" v={fmtBRL(f.salarioBase)} /><Linha k="Adiantamento" v={fmtBRL(valorAdiantamento(f, config))} /><Linha k="VT (empresa)" v={f.beneficios.vt.ativo ? fmtBRL(calcVTDetalhe(f, config).empresa) : "—"} /><Linha k="VR" v={f.beneficios.vr.ativo ? fmtBRL(vrInfo(f, config).valorMensal) : "—"} /><Linha k="Convênio" v={convenioInfo(f).ativo ? `${fmtBRL(convenioInfo(f).descontoFunc)} (desc. func.)` : "—"} /><Linha k="E-mail" v={f.email || "—"} /><Linha k="Telefone" v={f.telefone ? fmtTelefoneBR(f.telefone) : "—"} /></div>
          </div>
          <div className="border-t border-border/60 pt-3">
            <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground/80">Pagamentos de benefícios (histórico)</p>
            <HistoricoPagamentos func={f} compact />
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          <p className="text-xs text-muted-foreground/80">Documentos anexados a este funcionário, por categoria. Os campos em vermelho são obrigatórios.</p>
          {CATEGORIAS_DOC.map((cat) => { const arqs = docsF.filter((d) => d.categoria === cat); const obrig = DOCS_OBRIGATORIOS.includes(cat); return (
            <div key={cat} className="rounded-md border border-border p-3">
              <div className="flex items-center justify-between"><p className="text-sm font-medium text-foreground/80">{cat}{obrig && arqs.length === 0 && <span className="ml-2 text-xs text-destructive">obrigatório</span>}</p><label className="inline-flex cursor-pointer items-center gap-1.5 rounded-md border border-input px-2.5 py-1 text-xs font-medium text-foreground/80 hover:bg-secondary/50"><Upload size={13} /> Enviar<input type="file" className="hidden" accept=".pdf,.jpg,.jpeg,.png,.docx,.xlsx" multiple onChange={(e) => up(e, cat)} /></label></div>
              {arqs.length > 0 && <ul className="mt-2 space-y-1.5">{arqs.map((doc) => (<li key={doc.id} className="flex items-center justify-between rounded-md bg-secondary/50 px-3 py-1.5 text-sm"><span className="flex items-center gap-2 truncate text-foreground/80"><FileText size={14} className="shrink-0 text-muted-foreground/80" /><span className="truncate">{doc.nome}</span></span><div className="flex shrink-0 gap-0.5"><IconBtn icon={Eye} title="Ver" onClick={() => abrir(doc)} /><IconBtn icon={Trash2} title="Excluir" tone="danger" onClick={() => excluir(doc)} /></div></li>))}</ul>}
            </div>
          ); })}
        </div>
      )}
    </Modal>
  );
}

/* ==================================================================
   ATESTADOS E FALTAS — registro de ausências + impacto em VT/VR
   O impacto é uma PROJEÇÃO calculada com as taxas atuais; as fórmulas
   de VT/VR permanecem inalteradas.
   ================================================================== */
const ATESTADO_VAZIO = { funcId: "", tipo: "Atestado Médico", dataInicio: hojeISO(), dataFim: hojeISO(), qtdDias: "", motivo: "", observacoes: "", cid: "", horaInicio: "", horaFim: "", horaSaida: "", horasAusentes: "", comAtestado: false, anexos: [] };
function Atestados({ funcionarios, ativos, atestados, setAtestados, atualizarFunc, config, setConfig, pagamentos = [], setPagamentos = () => {} }) {
  const [aberto, setAberto] = useState(false);
  const [edit, setEdit] = useState(null);
  const [comp, setComp] = useState(compAtual());
  const [fTipo, setFTipo] = useState("Todos");
  const [fEmpresa, setFEmpresa] = useState("Todas");
  const [gerirTipos, setGerirTipos] = useState(false);
  const tipos = tiposAusencia(config); // padrão + personalizados
  const funcById = useMemo(() => { const m = {}; funcionarios.forEach((f) => { m[f.id] = f; }); return m; }, [funcionarios]);
  const nomeDe = (a) => funcById[a.funcId]?.nome || a.nome || "—";
  const empresaDe = (a) => funcById[a.funcId]?.empresa || "—";
  // Lança/atualiza/remove os descontos por ausência (array pagamentos), rastreados por faltaId.
  // Grava as linhas; o ROTEAMENTO folha × rescisão é decidido na exibição (dadosDe / RescisaoModal)
  // pela competência × mês do desligamento. Adiantamento: se o VT/VR do período já foi pago adiantado,
  // NÃO lança a linha (o Acerto de Benefícios recupera esses dias — evita descontar duas vezes).
  function sincronizarFalta(at) {
    const semEsta = (arr) => (arr || []).filter((p) => !(p.origem === "falta" && p.faltaId === at.id));
    const f = funcById[at.funcId] || funcionarios.find((x) => x.id === at.funcId);
    const df = f ? descontoAusenciaValores(f, at, config, tipos) : null;
    if (!df) { setPagamentos((p) => semEsta(p)); return; }   // tipo não desconta → só remove os antigos
    const adiantado = (ben) => (f.beneficios?.[ben]?.pagamentos || []).some((p) => pagValido(p) && p.periodo_de && p.periodo_ate && p.periodo_de <= (at.dataFim || at.dataInicio) && p.periodo_ate >= at.dataInicio);
    const descVT = adiantado("vt") ? 0 : df.descVT;   // adiantado → o Acerto recupera
    const descVR = adiantado("vr") ? 0 : df.descVR;
    if (df.descSalario <= 0 && descVT <= 0 && descVR <= 0 && df.descHoras <= 0) { setPagamentos((p) => semEsta(p)); return; }
    const compFalta = (at.dataInicio || "").slice(0, 7);
    const emResc = !!(f.rescisao && !f.rescisao.pago && (f.rescisao.dataDesligamento || "").slice(0, 7) === compFalta);
    let comp = compFalta;
    if (!emResc) {   // faltas da FOLHA respeitam o mês fechado; as da RESCISÃO não deslocam competência
      const jaPaga = (pagamentos || []).some((p) => p.funcionarioId === f.id && p.competencia === comp && p.tipo === "Salário" && pagPago(p));
      if (jaPaga) {
        const prox = proximaComp(comp);
        if (!confirm(`A folha de ${compLabel(comp)} de ${f.nome} já foi paga — não posso alterá-la.\n\nLançar o desconto da falta em ${compLabel(prox)}?`)) { setPagamentos((p) => semEsta(p)); return; }
        comp = prox;
      }
    }
    const rot = at.tipo === "Falta" ? "falta" : at.tipo.toLowerCase();
    const base = { origem: "falta", faltaId: at.id, funcionarioId: f.id, nome: f.nome, empresa: f.empresa, competencia: comp, compFalta, tipo: "Desconto Falta", status: "Pendente", dataPrevista: "", dataRealizada: "", dataPagamento: "", ultimaMov: hojeISO(), obs: at.motivo || "" };
    const novas = [];
    if (df.descSalario > 0) novas.push({ id: uid(), ...base, categoria: "Salário", descricao: `Desconto de ${rot} — Salário (${df.dias} dia(s))`, valor: df.descSalario });
    if (descVT > 0) novas.push({ id: uid(), ...base, categoria: "VT", descricao: `Desconto de ${rot} — VT (${df.diasUteis} dia(s))`, valor: descVT });
    if (descVR > 0) novas.push({ id: uid(), ...base, categoria: "VR", descricao: `Desconto de ${rot} — VR (${df.diasUteis} dia(s))`, valor: descVR });
    if (df.descHoras > 0) novas.push({ id: uid(), ...base, categoria: "Horas", descricao: `Desconto de ${rot} — Horas (${fmtHoras(df.horasAusentes)} × ${fmtBRL(df.valorHora)}/h)`, valor: df.descHoras });
    setPagamentos((p) => [...semEsta(p), ...novas]);
  }
  function salvar(d) {
    const nome = funcById[d.funcId]?.nome || "";
    const reg = d.id ? { ...d, nome } : { ...d, id: uid(), nome, dataRegistro: hojeISO() };
    setAtestados((p) => (p.some((x) => x.id === reg.id) ? p.map((x) => (x.id === reg.id ? reg : x)) : [...p, reg]));
    sincronizarFalta(reg);   // reflete o desconto na folha (cria/atualiza/remove conforme o tipo e os valores)
    setAberto(false); setEdit(null);
  }
  const lista = atestados.filter((a) => (a.dataInicio || "").slice(0, 7) === comp && (fTipo === "Todos" || a.tipo === fTipo) && (fEmpresa === "Todas" || empresaDe(a) === fEmpresa)).sort((a, b) => (b.dataInicio || "").localeCompare(a.dataInicio || ""));
  const totalDias = lista.reduce((s, a) => s + atestadoDias(a), 0);
  // Impacto agregado do mes (funcionarios com ausencia que desconta beneficio).
  const impactos = ativos.map((f) => ({ f, i: impactoBeneficios(f, config, atestados, comp, tipos) })).filter((x) => x.i.dias > 0 || x.i.horas > 0);
  const impactoTotal = impactos.reduce((s, x) => s + x.i.total, 0);
  // O desconto de VR já é lançado como LINHA na folha (sincronizarFalta). Aplicar também no cartão
  // (diasTrabalhados) descontaria o MESMO valor duas vezes — então o botão some quando a linha existe.
  const vrJaNaFolha = (f) => (pagamentos || []).some((p) => p.origem === "falta" && p.funcionarioId === f.id && p.categoria === "VR" && mesesDaFalta(p).includes(comp));
  const rowsExport = lista.map((a) => [nomeDe(a), empresaDe(a), a.tipo, fmtData(a.dataInicio), fmtData(a.dataFim), String(atestadoDias(a)), a.motivo || "—"]);
  const columns = [
    { key: "nome", header: "Funcionário", get: (a) => nomeDe(a), cell: (a) => (<div><p className="font-medium text-foreground">{nomeDe(a)}</p><p className="text-xs text-muted-foreground/80">{empresaDe(a)}</p></div>) },
    { key: "tipo", header: "Tipo", get: (a) => a.tipo, cell: (a) => <Badge cls={corAusencia(a.tipo, tipos)}>{a.tipo}</Badge> },
    { key: "inicio", header: "Início", get: (a) => a.dataInicio || "", cell: (a) => fmtData(a.dataInicio) },
    { key: "fim", header: "Fim", get: (a) => a.dataFim || "", cell: (a) => fmtData(a.dataFim) },
    { key: "dias", header: "Dias", type: "number", align: "center", get: (a) => atestadoDias(a), cell: (a) => <span className="font-medium text-foreground/80">{atestadoDias(a)}</span> },
    { key: "motivo", header: "Motivo", get: (a) => a.motivo || "", cell: (a) => <span className="line-clamp-1 text-foreground/70">{a.motivo || "—"}</span> },
  ];
  const filtros = (<>
    <input type="month" className={selCls} value={comp} onChange={(e) => setComp(e.target.value)} />
    <select className={selCls} value={fTipo} onChange={(e) => setFTipo(e.target.value)}><option>Todos</option>{tipos.map((t) => <option key={t.nome}>{t.nome}</option>)}</select>
    <select className={selCls} value={fEmpresa} onChange={(e) => setFEmpresa(e.target.value)}><option>Todas</option>{EMPRESAS.map((x) => <option key={x}>{x}</option>)}</select>
  </>);
  return (
    <div className="space-y-4">
      <PageHeader titulo="Atestados e Faltas" subtitulo={`Registros e ausências · ${compLabel(comp)}`}>
        <Btn variant="secondary" onClick={() => setGerirTipos(true)}><Settings size={16} /> Tipos de ausência</Btn>
        <Btn onClick={() => { setEdit(ATESTADO_VAZIO); setAberto(true); }}><Plus size={16} /> Novo registro</Btn>
      </PageHeader>
      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kpi icon={ClipboardList} label="Registros no mês" value={lista.length} />
        <Kpi icon={CalendarDays} label="Dias de ausência" value={totalDias} tone="amber" />
        <Kpi icon={Stethoscope} label="Atestados médicos" value={lista.filter((a) => a.tipo === "Atestado Médico").length} tone="blue" />
        <Kpi icon={Wallet} label="Impacto total (estim.)" value={fmtBRLc(impactoTotal)} tone="red" />
      </div>
      <DataTable columns={columns} rows={lista} searchPlaceholder="Buscar por funcionário, motivo..." filtros={filtros} pageSize={12}
        toolbarRight={<ExportButtons titulo={`Atestados ${comp}`} headers={["Funcionário", "Empresa", "Tipo", "Início", "Fim", "Dias", "Motivo"]} rows={rowsExport} />}
        actions={(a) => <RowActions onEdit={() => { setEdit(a); setAberto(true); }} onDelete={async () => { if (!confirm(`Excluir registro de ${nomeDe(a)}?`)) return; for (const doc of (a.anexos || [])) { if (doc.storagePath) { try { await docRemove(doc); } catch (_) {} } } setAtestados((p) => p.filter((x) => x.id !== a.id)); setPagamentos((p) => p.filter((x) => !(x.origem === "falta" && x.faltaId === a.id))); }} />}
        vazio="Nenhum atestado ou falta neste período." />

      <Card className="p-4">
        <div className="mb-3 flex items-center justify-between"><h3 className="flex items-center gap-2 text-sm font-semibold text-foreground/80"><Wallet size={15} className="text-muted-foreground/80" /> Recálculo de descontos por ausência — {compLabel(comp)}</h3></div>
        <p className="mb-3 text-xs text-muted-foreground/80">Projeção automática do desconto por ausências, conforme a regra de cada tipo (Falta desconta salário + VT + VR; Atestado, Falta Abonada, Home Office e Declaração descontam VT + VR; Saída Antecipada desconta horas, e o VR só quando a saída é antes do almoço). Salário conta dias corridos; VT/VR só dias úteis; horas usam o valor do dia ÷ jornada. O desconto já entra como <strong>linha na folha</strong> do mês — o botão "Aplicar no VR" só aparece quando ainda não há linha de VR lançada, para não descontar duas vezes.</p>
        {impactos.length === 0 ? <Empty texto="Nenhum desconto por ausência no período." icon={CheckCircle2} /> : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="text-left text-xs font-semibold uppercase tracking-wide text-muted-foreground"><tr><th className="px-2 py-1.5">Funcionário</th><th className="px-2 py-1.5 text-center">Dias</th><th className="px-2 py-1.5 text-right">Desc. Salário</th><th className="px-2 py-1.5 text-right">Desc. VT</th><th className="px-2 py-1.5 text-right">Desc. VR</th><th className="px-2 py-1.5 text-right">Desc. Horas</th><th className="px-2 py-1.5 text-right">Total</th><th className="px-2 py-1.5"></th></tr></thead>
              <tbody className="divide-y divide-border/60">{impactos.map(({ f, i }) => (
                <tr key={f.id}>
                  <td className="px-2 py-2"><p className="font-medium text-foreground/80">{f.nome}</p><p className="text-xs text-muted-foreground/80">{f.empresa}</p></td>
                  <td className="px-2 py-2 text-center">{i.dias}</td>
                  <td className="px-2 py-2 text-right text-foreground/70">{fmtBRL(i.sal)}</td>
                  <td className="px-2 py-2 text-right text-foreground/70">{fmtBRL(i.vt)}</td>
                  <td className="px-2 py-2 text-right text-foreground/70">{fmtBRL(i.vr)}</td>
                  <td className="px-2 py-2 text-right text-foreground/70">{i.horas > 0 ? <>{fmtBRL(i.hrs)} <span className="text-xs text-muted-foreground/80">({fmtHoras(i.horas)})</span></> : fmtBRL(0)}</td>
                  <td className="px-2 py-2 text-right font-semibold text-foreground">{fmtBRL(i.total)}</td>
                  <td className="px-2 py-2 text-right">{f.beneficios.vr.ativo && i.vrDias > 0 && (vrJaNaFolha(f)
                    ? <span className="text-xs text-muted-foreground/80" title="O desconto de VR já está lançado como linha na folha deste mês. Aplicar no cartão descontaria o mesmo valor duas vezes.">VR já descontado na folha</span>
                    : <Btn size="sm" variant="secondary" onClick={() => { const base = num(config.diasUteis); atualizarFunc(f.id, { beneficios: { ...f.beneficios, vr: { ...f.beneficios.vr, diasTrabalhados: Math.max(0, base - i.vrDias) } } }); }}>Aplicar no VR</Btn>)}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        )}
      </Card>
      {aberto && <AtestadoModal inicial={edit} funcionarios={ativos} config={config} tipos={tipos} onClose={() => { setAberto(false); setEdit(null); }} onSalvar={salvar} />}
      {gerirTipos && <TiposAusenciaModal config={config} setConfig={setConfig} onClose={() => setGerirTipos(false)} />}
    </div>
  );
}
// Gerenciar tipos personalizados de ausência (os 6 padrão não são editáveis; ficam sempre disponíveis).
function TiposAusenciaModal({ config, setConfig, onClose }) {
  const custom = (config.tiposAusencia || []);
  const [nome, setNome] = useState("");
  const [sal, setSal] = useState(false);
  const [vt, setVt] = useState(false);
  const [vr, setVr] = useState(false);
  const nomesUsados = new Set([...TIPOS_AUSENCIA_PADRAO.map((t) => t.nome), ...custom.map((t) => t.nome)].map((n) => normalizarTexto(n)));
  const add = () => {
    const n = nome.trim(); if (!n) return;
    if (nomesUsados.has(normalizarTexto(n))) { alert("Já existe um tipo com esse nome."); return; }
    setConfig((p) => ({ ...p, tiposAusencia: [...(p.tiposAusencia || []), { nome: n, salario: sal, vt, vr, cor: "bg-secondary text-foreground/70" }] }));
    setNome(""); setSal(false); setVt(false); setVr(false);
  };
  const remover = (n) => setConfig((p) => ({ ...p, tiposAusencia: (p.tiposAusencia || []).filter((t) => t.nome !== n) }));
  return (
    <Modal title="Tipos de ausência" subtitle="Padrões fixos + tipos personalizados" onClose={onClose} max="max-w-lg" footer={<Btn variant="secondary" onClick={onClose}>Fechar</Btn>}>
      <div className="space-y-4">
        <div>
          <p className="mb-1.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground/80">Padrão</p>
          <div className="space-y-1">{TIPOS_AUSENCIA_PADRAO.map((t) => (
            <div key={t.nome} className="flex items-center justify-between rounded-md bg-secondary/50 px-3 py-1.5 text-sm">
              <Badge cls={t.cor}>{t.nome}</Badge>
              <span className="text-xs text-muted-foreground/80">{[t.salario && "desconta salário", t.vt && "desconta VT", t.vr && "desconta VR", t.vrSeAntesAlmoco && "VR só se sair antes do almoço", t.horas && (t.atestadoAnula ? "desconta horas só sem atestado" : "desconta horas")].filter(Boolean).join(" · ") || "não desconta"}</span>
            </div>
          ))}</div>
        </div>
        <div>
          <p className="mb-1.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground/80">Personalizados</p>
          {custom.length === 0 ? <p className="text-xs text-muted-foreground/80">Nenhum tipo personalizado ainda.</p> : (
            <div className="space-y-1">{custom.map((t) => (
              <div key={t.nome} className="flex items-center justify-between rounded-md border border-border px-3 py-1.5 text-sm">
                <span className="text-foreground/80">{t.nome}</span>
                <span className="flex items-center gap-2"><span className="text-xs text-muted-foreground/80">{[t.salario && "salário", t.vt && "VT", t.vr && "VR"].filter(Boolean).join(" · ") || "não desconta"}</span><IconBtn icon={Trash2} title="Remover" onClick={() => remover(t.nome)} /></span>
              </div>
            ))}</div>
          )}
        </div>
        <div className="rounded-md border border-border p-3">
          <p className="mb-2 text-sm font-medium text-foreground/80">Novo tipo</p>
          <div className="flex flex-wrap items-end gap-2">
            <Field label="Nome"><input className={inputCls} value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Ex.: Licença-maternidade" /></Field>
            <label className="flex items-center gap-1.5 pb-2 text-sm text-foreground/70"><input type="checkbox" checked={sal} onChange={(e) => setSal(e.target.checked)} className="h-4 w-4 rounded border-input text-primary" /> Desconta salário</label>
            <label className="flex items-center gap-1.5 pb-2 text-sm text-foreground/70"><input type="checkbox" checked={vt} onChange={(e) => setVt(e.target.checked)} className="h-4 w-4 rounded border-input text-primary" /> Desconta VT</label>
            <label className="flex items-center gap-1.5 pb-2 text-sm text-foreground/70"><input type="checkbox" checked={vr} onChange={(e) => setVr(e.target.checked)} className="h-4 w-4 rounded border-input text-primary" /> Desconta VR</label>
            <Btn size="sm" onClick={add}><Plus size={14} /> Adicionar</Btn>
          </div>
        </div>
      </div>
    </Modal>
  );
}
function AtestadoModal({ inicial, funcionarios, config, tipos, onClose, onSalvar }) {
  const [d, setD] = useState({ ...ATESTADO_VAZIO, ...inicial, anexos: inicial.anexos || [] });
  const [tab, setTab] = useState("dados");
  const [salvandoAnexos, setSalvandoAnexos] = useState(false);
  const removidosRef = useRef([]); // storagePaths de anexos JÁ salvos removidos nesta edição (apagados do Storage só ao Salvar)
  const set = (k, v) => setD((p) => ({ ...p, [k]: v }));
  const opcoesFunc = funcionarios.map((f) => f.nome);
  const funcByNome = (nome) => funcionarios.find((f) => f.nome === nome);
  const selFunc = funcionarios.find((f) => f.id === d.funcId);
  const tipoInfo = tipoAusenciaDe(d.tipo, tipos);
  const diasCalc = atestadoDias(d);
  // O impacto do próprio registro é calculado no resumo abaixo (descontoAusenciaValores).
  // Anexos: o arquivo só sobe pro Storage no momento do Salvar (se cancelar, nada fica órfão).
  // Aqui guardamos o File em memória; nunca base64 no banco.
  function anexar(e) {
    const files = Array.from(e.target.files || []);
    files.forEach((file) => setD((p) => ({ ...p, anexos: [...(p.anexos || []), { id: uid(), nome: file.name, tipo: file.type, tamanho: file.size, _file: file }] })));
    e.target.value = "";
  }
  // Sobe os anexos pendentes pro Storage, apaga do Storage os que foram removidos e então persiste.
  async function salvarAtestado() {
    if (!d.funcId) { alert("Selecione o funcionário."); return; }
    if (tipoInfo.saida && !horaMin(d.horaSaida)) { alert("Informe o horário em que o funcionário saiu — é ele que calcula as horas não trabalhadas e o VR."); return; }
    setSalvandoAnexos(true);
    try {
      const anexosFinal = [];
      const falhas = [];
      let erroAnexo = null;
      for (const a of (d.anexos || [])) {
        if (a._file) {
          // Um anexo que não sobe não pode levar o registro junto: o atestado (com datas e descontos)
          // é o que importa. O arquivo continua no computador para ser anexado depois.
          try { const storagePath = await docUpload(a._file, d.funcId, a.id); const { _file, ...meta } = a; anexosFinal.push({ ...meta, storagePath }); }
          catch (err) { falhas.push(a.nome); erroAnexo = err; }
        } else anexosFinal.push(a);
      }
      if (falhas.length && !confirm(`Não consegui enviar ${falhas.length} anexo(s) (${falhas.join(", ")}): ${erroAnexo?.message || erroAnexo}\n\nOs arquivos vão para o armazenamento do Supabase, no bucket "documentos" — se ele não existir, precisa ser criado.\n\nSalvar o registro SEM esses anexos? Dá para anexar depois, editando o registro.`)) return;
      for (const path of removidosRef.current) { try { await docRemove({ storagePath: path }); } catch (_) {} }
      removidosRef.current = [];
      onSalvar({ ...d, anexos: anexosFinal });
    } catch (err) { alert("Não consegui salvar o registro: " + (err?.message || err)); }
    finally { setSalvandoAnexos(false); }
  }
  const tabs = [{ id: "dados", label: "Dados", icon: ClipboardList }, { id: "anexos", label: `Anexos (${(d.anexos || []).length})`, icon: Paperclip }];
  return (
    <Modal title={inicial.id ? "Editar registro" : "Novo registro de ausência"} subtitle="Atestados, faltas e ausências" onClose={onClose} max="max-w-lg"
      footer={<><Btn variant="secondary" onClick={onClose} disabled={salvandoAnexos}>Cancelar</Btn><Btn onClick={salvarAtestado} disabled={salvandoAnexos}><Save size={16} /> {salvandoAnexos ? "Salvando..." : "Salvar"}</Btn></>}>
      <div className="mb-4"><Tabs tabs={tabs} active={tab} onChange={setTab} /></div>
      {tab === "dados" ? (
        <div className="space-y-4">
          <Field label="Funcionário"><Combobox value={selFunc?.nome || ""} onChange={(nome) => { const f = funcByNome(nome); set("funcId", f?.id || ""); }} options={opcoesFunc} placeholder="Selecione o funcionário..." /></Field>
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            {/* Trocar de tipo LIMPA os campos que não pertencem ao novo tipo: eles somem da tela, e um
                horário esquecido continuaria entrando na conta (ex.: horaSaida de uma Saída Antecipada
                sequestrando as horas de uma Declaração). */}
            <Field label="Tipo"><select className={inputCls} value={d.tipo} onChange={(e) => { const nome = e.target.value; const t = tipoAusenciaDe(nome, tipos); setD((p) => ({ ...p, tipo: nome, horaSaida: t.saida ? p.horaSaida : "", horaInicio: (t.horas && !t.saida) ? p.horaInicio : "", horaFim: (t.horas && !t.saida) ? p.horaFim : "", horasAusentes: t.horas ? p.horasAusentes : "", comAtestado: t.atestadoAnula ? p.comAtestado : false, cid: t.atestado ? p.cid : "" })); }}>{tipos.map((t) => <option key={t.nome}>{t.nome}</option>)}</select></Field>
            <Field label="Quantidade de dias" hint="Vazio = calcula pelo intervalo"><input type="number" min="0" className={inputCls} value={d.qtdDias} onChange={(e) => set("qtdDias", e.target.value)} placeholder={`${diasCalc}`} /></Field>
            <Field label="Data inicial"><input type="date" className={inputCls} value={d.dataInicio} onChange={(e) => set("dataInicio", e.target.value)} /></Field>
            <Field label="Data final"><input type="date" className={inputCls} value={d.dataFim} onChange={(e) => set("dataFim", e.target.value)} /></Field>
            {/* Saída Antecipada: o horário da saída é OBRIGATÓRIO — dele saem as horas e o VR. */}
            {tipoInfo.saida && (
              <Field label="Horário em que saiu *" hint={`Jornada ${config?.jornadaEntrada || CONFIG_PADRAO.jornadaEntrada}–${config?.jornadaSaida || CONFIG_PADRAO.jornadaSaida} · almoço ${config?.jornadaAlmocoIni || CONFIG_PADRAO.jornadaAlmocoIni}`}>
                <input type="time" className={`${inputCls} ${horaMin(d.horaSaida) ? "" : "border-destructive/40"}`} value={d.horaSaida || ""} onChange={(e) => set("horaSaida", e.target.value)} />
              </Field>
            )}
            {/* Declaração de Comparecimento: intervalo em que a pessoa não esteve presente. */}
            {tipoInfo.horas && !tipoInfo.saida && <Field label="Ausente das" hint="Início da ausência"><input type="time" className={inputCls} value={d.horaInicio || ""} onChange={(e) => set("horaInicio", e.target.value)} /></Field>}
            {tipoInfo.horas && !tipoInfo.saida && <Field label="Até" hint="Retorno ao trabalho"><input type="time" className={inputCls} value={d.horaFim || ""} onChange={(e) => set("horaFim", e.target.value)} /></Field>}
            {tipoInfo.horas && <Field label="Horas ausentes" hint="Vazio = calcula pelo horário"><input type="number" min="0" step="0.5" className={inputCls} value={d.horasAusentes} onChange={(e) => set("horasAusentes", e.target.value)} placeholder={fmtHoras(horasAusentesDe({ ...d, horasAusentes: "" }, jornadaDe(config), tipoInfo))} /></Field>}
            {/* Atestado Médico: CID. */}
            {tipoInfo.atestado && <Field label="CID" hint="opcional"><input className={inputCls} value={d.cid || ""} onChange={(e) => set("cid", e.target.value)} placeholder="Ex.: J11" /></Field>}
          </div>
          {/* Saída por mal-estar: o atestado decide o SALÁRIO (as horas); o horário decide o VR. */}
          {tipoInfo.atestadoAnula && (
            <div className="rounded-md border border-border p-3">
              <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground/80">Apresentou atestado?</p>
              <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
                <button type="button" onClick={() => set("comAtestado", true)} className={`rounded-md border px-3 py-2 text-left text-sm ${d.comAtestado ? "border-success/70 bg-success/8 text-success" : "border-border text-foreground/70 hover:bg-secondary/50"}`}>
                  <span className="flex items-center gap-1.5 font-medium"><CheckCircle2 size={14} /> Com atestado</span>
                  <span className="mt-0.5 block text-[11px] text-muted-foreground">Justificada — <strong>não desconta o salário</strong> (nem as horas).</span>
                </button>
                <button type="button" onClick={() => set("comAtestado", false)} className={`rounded-md border px-3 py-2 text-left text-sm ${d.comAtestado ? "border-border text-foreground/70 hover:bg-secondary/50" : "border-destructive/40 bg-destructive/8 text-destructive"}`}>
                  <span className="flex items-center gap-1.5 font-medium"><X size={14} /> Sem atestado</span>
                  <span className="mt-0.5 block text-[11px] text-muted-foreground">Desconta as <strong>horas não trabalhadas</strong> do salário.</span>
                </button>
              </div>
              <p className="mt-2 text-[11px] text-muted-foreground/80">O <strong>vale-refeição</strong> não depende do atestado, e sim do horário: saiu <strong>antes</strong> do almoço ({config?.jornadaAlmocoIni || CONFIG_PADRAO.jornadaAlmocoIni}) perde o VR do dia; saiu <strong>depois</strong>, recebe normal. O <strong>vale-transporte</strong> do dia nunca é descontado. Anexe o atestado na aba Anexos.</p>
            </div>
          )}
          <Field label="Motivo"><input className={inputCls} value={d.motivo} onChange={(e) => set("motivo", e.target.value)} /></Field>
          <Field label="Observações"><textarea rows={2} className={inputCls} value={d.observacoes} onChange={(e) => set("observacoes", e.target.value)} /></Field>
          <div className="rounded-md bg-secondary/50 p-3 text-xs text-foreground/70">
            {(() => {
              const fl = descontoAusencia(d, tipos, config);
              const temFlag = fl.salario || fl.vt || fl.vr || fl.horas;
              if (!temFlag) return fl.justificada
                ? <p className="text-success"><strong>Com atestado</strong> e saída depois do almoço — <strong>nada a descontar</strong>: salário, horas, VT e VR do dia ficam integrais.</p>
                : <p className="text-muted-foreground">Este tipo de ausência não gera desconto.</p>;
              if (!selFunc) return <p><strong>{diasCalc}</strong> dia(s) — Tipo: {d.tipo}. Selecione o funcionário para calcular o desconto.</p>;
              const df = descontoAusenciaValores(selFunc, d, config, tipos);
              const faltando = [df.semSalario && "salário", df.semVT && "VT", df.semVR && "VR"].filter(Boolean);
              // Resumo em uma linha, no formato pedido pelo RH.
              const partes = [fl.salario && `salário do dia ${fmtBRL(df.descSalario)}`, fl.vt && `VT ${fmtBRL(df.descVT)}`, fl.vr && `VR ${fmtBRL(df.descVR)}`, fl.horas && `horas ${fmtBRL(df.descHoras)}`].filter(Boolean);
              return (<>
                <p className="mb-1 font-semibold text-foreground/80">{df.dias} dia(s) de ausência — Tipo: {d.tipo}</p>
                <div className="space-y-0.5">
                  {fl.salario && <div className="flex justify-between gap-2"><span>Desconto salário:</span><span className="tabular-nums font-medium text-destructive">{fmtBRL(df.descSalario)} <span className="font-normal text-muted-foreground/80">({fmtBRL(df.salMensal)} ÷ 30 × {df.dias})</span></span></div>}
                  {fl.vt && <div className="flex justify-between gap-2"><span>Desconto VT:</span><span className="tabular-nums font-medium text-destructive">{fmtBRL(df.descVT)} <span className="font-normal text-muted-foreground/80">({fmtBRL(df.vtDia)}/dia × {df.diasUteis} úteis)</span></span></div>}
                  {fl.vr && <div className="flex justify-between gap-2"><span>Desconto VR:</span><span className="tabular-nums font-medium text-destructive">{fmtBRL(df.descVR)} <span className="font-normal text-muted-foreground/80">({fmtBRL(df.vrDia)}/dia × {df.diasUteis} úteis)</span></span></div>}
                  {fl.horas && <div className="flex justify-between gap-2"><span>Desconto horas:</span><span className="tabular-nums font-medium text-destructive">{fmtBRL(df.descHoras)} <span className="font-normal text-muted-foreground/80">({fmtBRL(df.valorDia)} ÷ {String(df.jornadaHoras).replace(".", ",")} = R$ {df.valorHora.toLocaleString("pt-BR", { minimumFractionDigits: 4, maximumFractionDigits: 4 })}/h × {fmtHoras(df.horasAusentes)})</span></span></div>}
                  <div className="flex justify-between gap-2 border-t border-border pt-1 font-semibold"><span className="text-foreground/80">Total a abater:</span><span className="tabular-nums text-destructive">{fmtBRL(df.total)}</span></div>
                </div>
                <p className="mt-1.5 rounded bg-card px-2 py-1 text-[11px] text-foreground/70">Desconto: {partes.join(" + ")} = <strong className="text-destructive">TOTAL {fmtBRL(df.total)}</strong></p>
                {fl.justificada && <p className="mt-1.5 text-[11px] text-success"><strong>Com atestado</strong> — o salário/as horas não são descontados. O VR do dia continua saindo porque a saída foi antes do almoço.</p>}
                {tipoInfo.atestadoAnula && !fl.justificada && fl.horas && <p className="mt-1.5 text-[11px] text-muted-foreground/80"><strong>Sem atestado</strong> — descontadas as horas não trabalhadas. Marcando "Com atestado" o desconto de horas some.</p>}
                {df.semHorario && <p className="mt-1.5 text-[11px] text-warning-ink">{tipoInfo.saida ? "Informe o horário da saída" : "Informe o horário (ou as horas) da ausência"} — sem ele o desconto de horas fica R$ 0,00.</p>}
                {fl.vr && tipoInfo.vrSeAntesAlmoco && <p className="mt-1 text-[11px] text-muted-foreground/80">Saiu antes do almoço ({config?.jornadaAlmocoIni || CONFIG_PADRAO.jornadaAlmocoIni}) — o VR do dia entra no desconto. O VT não é descontado (ele foi trabalhar).</p>}
                {!fl.vr && tipoInfo.vrSeAntesAlmoco && horaMin(d.horaSaida) != null && <p className="mt-1 text-[11px] text-muted-foreground/80">Saiu depois do almoço — desconta só as horas não trabalhadas (VT e VR do dia ficam mantidos).</p>}
                {faltando.length > 0 && <p className="mt-1.5 text-[11px] text-warning-ink">Sem {faltando.join(" / ")} no cadastro deste funcionário — esse item entra como R$ 0,00. Complete o cadastro se precisar descontar.</p>}
              </>);
            })()}
          </div>
        </div>
      ) : (
        <div className="space-y-3">
          <label className="inline-flex cursor-pointer items-center gap-2 rounded-md border border-input px-3 py-2 text-sm font-medium text-foreground/80 hover:bg-secondary/50"><Upload size={15} /> Anexar arquivo (PDF ou imagem)<input type="file" accept=".pdf,image/*" multiple className="hidden" onChange={anexar} /></label>
          {(d.anexos || []).length === 0 ? <Empty texto="Nenhum arquivo anexado." icon={Paperclip} /> : (
            <ul className="space-y-1.5">{(d.anexos || []).map((doc) => (
              <li key={doc.id} className="flex items-center justify-between rounded-md bg-card border border-border px-3 py-1.5 text-sm">
                <button type="button" onClick={async () => { if (doc._file) { window.open(URL.createObjectURL(doc._file), "_blank"); return; } const w = window.open("", "_blank"); if (!w) { alert("Permita pop-ups para visualizar o anexo."); return; } try { const url = await docUrl(doc); if (url) w.location = url; else { w.close(); alert("Arquivo não disponível — anexe novamente."); } } catch (err) { w.close(); alert("Falha ao abrir: " + (err?.message || err)); } }} className="flex items-center gap-2 truncate text-left text-foreground/80 hover:text-primary"><FileText size={14} className="shrink-0 text-muted-foreground/80" /><span className="truncate">{doc.nome}</span></button>
                <IconBtn icon={Trash2} title="Remover" onClick={() => { if (doc.storagePath) removidosRef.current.push(doc.storagePath); setD((p) => ({ ...p, anexos: (p.anexos || []).filter((x) => x.id !== doc.id) })); }} />
              </li>
            ))}</ul>
          )}
        </div>
      )}
    </Modal>
  );
}

/* ==================================================================
   BENEFÍCIOS + ADIANTAMENTOS (tabelas)
   ================================================================== */
function BeneficiosOverview({ ativos, atualizarFunc, config }) {
  const [sel, setSel] = useState(null);
  const [fEmp, setFEmp] = useState("Todas");
  const lista = ativos.filter((f) => fEmp === "Todas" || f.empresa === fEmp);
  const totVT = lista.reduce((s, f) => s + calcVTDetalhe(f, config).empresa, 0);
  const totVR = lista.reduce((s, f) => s + (f.beneficios.vr.ativo ? vrInfo(f, config).valorMensal : 0), 0);
  const totAd = lista.reduce((s, f) => s + valorAdiantamento(f, config), 0);
  const rowsExport = lista.map((f) => [f.nome, f.empresa, f.beneficios.vt.ativo ? fmtBRL(calcVTDetalhe(f, config).custo) : "—", f.beneficios.vr.ativo ? fmtBRL(vrInfo(f, config).valorMensal) : "—", f.beneficios.adiantamento.ativo ? fmtBRL(valorAdiantamento(f, config)) : "—"]);
  const columns = [
    { key: "nome", header: "Funcionário", get: (f) => f.nome, cell: (f) => (<div><p className="font-medium text-foreground">{f.nome}</p><p className="text-xs text-muted-foreground/80">{f.empresa}</p></div>) },
    { key: "vt", header: "VT (custo)", type: "number", align: "right", get: (f) => calcVTDetalhe(f, config).custo, cell: (f) => f.beneficios.vt.ativo ? fmtBRL(calcVTDetalhe(f, config).custo) : "—" },
    { key: "vr", header: "VR", type: "number", align: "right", get: (f) => (f.beneficios.vr.ativo ? vrInfo(f, config).valorMensal : 0), cell: (f) => f.beneficios.vr.ativo ? fmtBRL(vrInfo(f, config).valorMensal) : "—" },
    { key: "ad", header: "Adiantamento", type: "number", align: "right", get: (f) => valorAdiantamento(f, config), cell: (f) => f.beneficios.adiantamento.ativo ? fmtBRL(valorAdiantamento(f, config)) : "—" },
  ];
  return (
    <div className="space-y-4">
      <PageHeader titulo="Benefícios" subtitulo="Vale-Transporte, Vale-Refeição e Adiantamento" />
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-3"><Kpi icon={Bus} label="VT (custo empresa)" value={fmtBRL(totVT)} tone="blue" /><Kpi icon={Utensils} label="Vale-Refeição" value={fmtBRL(totVR)} tone="blue" /><Kpi icon={Wallet} label="Adiantamentos" value={fmtBRL(totAd)} /></div>
      <DataTable columns={columns} rows={lista} searchPlaceholder="Buscar funcionário..." filtros={<SelectEmpresa value={fEmp} onChange={setFEmp} />} toolbarRight={<ExportButtons titulo="Beneficios" headers={["Funcionário", "Empresa", "VT (custo)", "VR", "Adiantamento"]} rows={rowsExport} />} actions={(f) => <RowActions onEdit={() => setSel(f)} />} />
      {sel && <BeneficioModal func={sel} config={config} onClose={() => setSel(null)} onSalvar={(patch) => { atualizarFunc(sel.id, patch); setSel(null); }} />}
    </div>
  );
}
// Tela unica de Beneficios: Vale-Transporte, Vale-Refeicao e Visao geral em abas.
function Beneficios(props) {
  // beneficioFoco: abre direto numa aba (usado pelos atalhos do Dashboard). Depois de
  // aplicado é limpo, senão a aba ficaria presa e o clique do usuário não valeria.
  const [sec, setSec] = useState(() => (["vt", "vr", "vale", "geral"].includes(props.beneficioFoco) ? props.beneficioFoco : "vt"));
  useEffect(() => { if (props.beneficioFoco) { setSec(props.beneficioFoco); props.setBeneficioFoco && props.setBeneficioFoco(""); } }, [props.beneficioFoco]);
  const tabsB = [
    { id: "vt", label: "Vale-Transporte", icon: Bus },
    { id: "vr", label: "Vale-Refeição", icon: Utensils },
    { id: "vale", label: "Vale (adiantamento)", icon: Wallet },
    { id: "geral", label: "Visão geral", icon: Gift },
  ];
  return (
    <div className="space-y-4">
      <PageHeader titulo="Benefícios" subtitulo="Vale-Transporte, Vale-Refeição, Vale (adiantamento) e visão geral num só lugar" />
      <Tabs tabs={tabsB} active={sec} onChange={setSec} />
      {sec === "vt" && <ControleVT {...props} />}
      {sec === "vr" && <ControleVR {...props} />}
      {sec === "vale" && <ControleVale {...props} />}
      {sec === "geral" && <BeneficiosOverview {...props} />}
    </div>
  );
}
/* ==================================================================
   VALE (adiantamento) — aba de Benefícios
   ------------------------------------------------------------------
   Mostra o vale de TODO MUNDO: CLT e quem está em treinamento (a aba
   Adiantamento da Folha de Repasse só enxerga CLT, porque treinamento
   tem folha própria). Valor e data são editáveis direto na linha, o
   pagamento cai no dia 20 (ajustado para dia útil) e dá para importar
   o PDF "Relação Geral dos Líquidos" da contabilidade.
   Grava no MESMO lançamento da Folha de Repasse (chave competência +
   funcionário + tipo "Adiantamento") — uma verdade só, sem duplicar.
   ================================================================== */
const VALE_VINCULOS = ["Todos", "CLT", "Treinamento"];
function ControleVale({ funcionarios = [], ativos = [], atualizarFunc, config, setConfig = () => {}, pagamentos = [], setPagamentos, empresaPermitida = "", nomeUsuario = "Administrador" }) {
  const [comp, setComp] = useState(compAtual());
  const [fEmp, setFEmp] = useState("Todas");
  const [fVinc, setFVinc] = useState("Todos");
  const [fStatus, setFStatus] = useState("todos");
  const [importOpen, setImportOpen] = useState(false);
  const [regraDe, setRegraDe] = useState(null);
  const [draft, setDraft] = useState({});          // edição em andamento, por funcionário
  const travaRef = useRef(new Set());               // anti duplo-clique no "marcar pago"
  const empFiltro = empresaPermitida || fEmp;
  const funcById = useMemo(() => { const m = {}; funcionarios.forEach((f) => { m[f.id] = f; }); return m; }, [funcionarios]);
  const pagDe = (fid) => pagamentos.find((p) => p.competencia === comp && p.funcionarioId === fid && p.tipo === "Adiantamento");
  const dataPadrao = dataValeComp(comp, config);

  // Falta já lançada em Atestados e Faltas nesta competência (só a parte de salário).
  const descFaltaVale = (fid) => FR.descontoFaltaNoVale((pagamentos || []).filter((p) => p.origem === "falta" && p.funcionarioId === fid), comp).descontoCentavos / 100;
  const todas = ativos.map((f) => { const p = pagDe(f.id); return { f, p, v: valeInfo(f, config, comp, p, descFaltaVale(f.id)) }; })
    .filter((x) => x.v.ativo && (x.v.total > 0 || x.p));
  const linhas = todas
    .filter(({ f }) => empFiltro === "Todas" || f.empresa === empFiltro)
    .filter(({ v }) => fVinc === "Todos" || v.vinculo === fVinc)
    .filter(({ v }) => fStatus === "todos" || (fStatus === "pendentes" ? !v.pago : fStatus === "pagos" ? v.pago : v.importado))
    .sort((a, b) => a.f.nome.localeCompare(b.f.nome));

  const soma = (arr, get) => arred2(arr.reduce((s, x) => s + get(x), 0));
  const totGeral = soma(linhas, (x) => x.v.total);
  const totCLT = soma(linhas.filter((x) => !x.v.emTreino), (x) => x.v.total);
  const totTreino = soma(linhas.filter((x) => x.v.emTreino), (x) => x.v.total);
  const totPago = soma(linhas.filter((x) => x.v.pago), (x) => x.v.total);
  const totCompl = soma(linhas, (x) => x.v.complemento);
  const totFalta = arred2(totGeral - totPago);
  const totDescFalta = soma(linhas, (x) => x.v.descontoFalta);
  const nCLT = linhas.filter((x) => !x.v.emTreino).length;
  const nTreino = linhas.filter((x) => x.v.emTreino).length;

  // ── Gravação: sempre pelo mesmo lançamento (upsertPagamento), nunca duplicando ──
  const gravar = (f, patch) => setPagamentos((prev) => upsertPagamento(prev, { comp, func: f, tipo: "Adiantamento", patch, dataPrevista: dataPadrao }));
  const limparDraft = (id) => setDraft((p) => { const n = { ...p }; delete n[id]; return n; });
  // Ao gravar a DATA de quem ainda nao tem lancamento, o valor vai junto: sem isso o
  // registro nascia com valor 0 e zerava um vale que a tela mostrava como R$ 800,00.
  function salvarData(x) {
    const d = draft[x.f.id]?.data;
    limparDraft(x.f.id);
    if (!d || d === x.v.dataPrevista) return;
    if (String(d).slice(0, 7) !== comp) return;            // data fora da competencia da tela
    gravar(x.f, { dataPrevista: d, valor: arred2(x.v.valor) });
  }
  function salvarComplemento(x) {
    const novo = draft[x.f.id]?.compl;
    if (novo == null) return;
    limparDraft(x.f.id);
    if (arred2(novo) === arred2(x.v.complemento)) return;        // nada mudou
    // Leva o valor junto pelo mesmo motivo da data: sem isso o registro nasceria com
    // valor 0 e zeraria um vale que a tela mostra cheio.
    gravar(x.f, { complemento: arred2(novo), valor: arred2(x.v.valor), editadoEm: `${hojeISO()} ${horaAgora()}`, editadoPor: nomeUsuario });
  }
  function salvarComplObs(x) {
    const novo = draft[x.f.id]?.complObs;
    if (novo == null) return;
    limparDraft(x.f.id);
    if (novo === x.v.complementoObs) return;
    gravar(x.f, { complementoObs: novo, valor: arred2(x.v.valor), complemento: arred2(x.v.complemento) });
  }
  /* REABRIR: desfaz o "pago" e devolve o lançamento para edição. Para quem está em
     treinamento, estorna junto o salário que o pagamento lançou em Proc. Treinamento —
     senão o saldo de lá continuaria abatido por um vale que não está mais pago. */
  function reabrir(ids, emLote) {
    const alvos = linhas.filter((x) => ids.includes(x.f.id) && x.v.pago);
    if (!alvos.length) { if (emLote) alert("Nenhum dos selecionados está pago."); return 0; }
    const comTreino = alvos.filter((x) => x.p?.treinoPagId);
    const aviso = comTreino.length ? `\n\n${comTreino.length} de treinamento: o salário que este vale lançou em Proc. Treinamento é estornado junto, e o saldo de lá volta a contar.` : "";
    const msg = alvos.length === 1
      ? `Reabrir o vale de ${alvos[0].f.nome}?\n\nValor: ${fmtBRL(alvos[0].v.total)}\n\nEle volta a PENDENTE, perde a data de pagamento e fica editável de novo.${aviso}`
      : `Reabrir ${alvos.length} vales pagos?\n\nTotal: ${fmtBRL(soma(alvos, (x) => x.v.total))}\n\nEles voltam a PENDENTE, perdem a data de pagamento e ficam editáveis de novo.${aviso}`;
    if (!confirm(msg)) return 0;
    comTreino.forEach((x) => { try { cancelarPagTreino(atualizarFunc, x.f, x.p.treinoPagId, nomeUsuario); } catch (_) {} });
    setPagamentos((prev) => {
      let out = prev;
      alvos.forEach((x) => {
        out = upsertPagamento(out, { comp, func: x.f, tipo: "Adiantamento", dataPrevista: dataPadrao,
          patch: { status: "Pendente", dataRealizada: "", dataPagamento: "", treinoPagId: "",
            reabertoEm: `${hojeISO()} ${horaAgora()}`, reabertoPor: nomeUsuario } });
      });
      return out;
    });
    return alvos.length;
  }
  function marcarPago(ids, emLote) {
    const alvos = linhas.filter((x) => ids.includes(x.f.id) && !x.v.pago && x.v.total > 0 && !travaRef.current.has(x.f.id));
    if (!alvos.length) { if (emLote) alert("Os selecionados já estão pagos."); return 0; }
    const total = soma(alvos, (x) => x.v.total);
    const emTreino = alvos.filter((x) => x.v.emTreino && !x.p?.treinoPagId);
    const aviso = emTreino.length ? `\n\n${emTreino.length} de treinamento: o valor também entra como salário já pago em Proc. Treinamento, abatendo o saldo de lá (para não pagar duas vezes).` : "";
    const msg = alvos.length === 1
      ? `Marcar o vale de ${alvos[0].f.nome} como PAGO?\n\nValor: ${fmtBRL(alvos[0].v.total)}${alvos[0].v.complemento > 0 ? ` (vale ${fmtBRL(alvos[0].v.valor)} + complemento ${fmtBRL(alvos[0].v.complemento)})` : ""}${aviso}\n\nDepois de pago o lançamento trava — dá para reabrir pelo botão da linha.`
      : `Marcar ${alvos.length} vales como PAGOS?\n\nTotal: ${fmtBRL(total)}${aviso}\n\nDepois de pagos os lançamentos travam — dá para reabrir pelo botão da linha ou em lote.`;
    if (!confirm(msg)) return 0;
    alvos.forEach((x) => {
      travaRef.current.add(x.f.id);
      setTimeout(() => travaRef.current.delete(x.f.id), 1000);
    });
    // O vale de quem está em treinamento é adiantamento do salário do treinamento, que
    // tem folha própria (f.treinamento.pagamentos_salario) e NÃO lê a lista de pagamentos.
    // Sem registrar dos dois lados, a pessoa recebia o vale aqui e o saldo cheio lá.
    // O treinoPagId guardado no lançamento impede registrar de novo.
    const idsTreino = {};
    emTreino.forEach((x) => {
      try { idsTreino[x.f.id] = registrarPagTreino(atualizarFunc, x.f, { tipo: "salario", data: hojeISO(), valor: x.v.total, dias: 0, por: nomeUsuario }); } catch (_) {}
    });
    setPagamentos((prev) => {
      let out = prev;
      alvos.forEach((x) => {
        const extra = idsTreino[x.f.id] ? { treinoPagId: idsTreino[x.f.id] } : {};
        out = upsertPagamento(out, { comp, func: x.f, tipo: "Adiantamento", dataPrevista: dataPadrao,
          patch: { valor: x.v.valor, status: "Realizado", dataRealizada: hojeISO(), dataPagamento: hojeISO(), ...extra } });
      });
      return out;
    });
    return alvos.length;
  }

  // ── Importação do PDF da contabilidade (Cálculo: Adiantamento) ──
  const atualDe = (fid) => {
    const f = funcById[fid]; const p = pagDe(fid);
    // total: null = "esta tela nao trata salario" — a conferencia mostra "—" em vez de R$ 0,00.
    return { total: null, adiant: f ? valeInfo(f, config, comp, p).valor : 0, temSal: false, temAdi: !!p, salPago: false, adiPago: !!(p && pagPago(p)) };
  };
  function aplicarImport(linhasImp) {
    setPagamentos((prev) => {
      let out = prev;
      linhasImp.forEach((l) => {
        if (!l.func || !l.temAdiant || l.adiBloqueado || !(num(l.adiantamento) > 0)) return;
        out = upsertPagamento(out, { comp, func: l.func, tipo: "Adiantamento", dataPrevista: dataPadrao,
          patch: { valor: arred2(l.adiantamento), importadoEm: `${hojeISO()} ${horaAgora()}` } });
      });
      return out;
    });
  }
  const registrarImport = (meta) => setConfig((c) => ({ ...c, repasseImports: [{ ...meta, origemTela: "Vale" }, ...(c.repasseImports || [])].slice(0, 50) }));
  const importsDoMes = (config.repasseImports || []).filter((x) => x.competencia === comp);

  // ── Colunas ── Complemento e Data são editáveis e por isso não são ordenáveis: reordenar
  // no meio da digitação tira o foco do campo e a edição se perde. Valor do vale é só
  // exibição (vem do cadastro ou da importação), pode ordenar à vontade.
  const complDe = (x) => draft[x.f.id]?.compl ?? x.v.complemento;
  const setD = (id, patch) => setDraft((p) => ({ ...p, [id]: { ...(p[id] || {}), ...patch } }));
  const columns = [
    { key: "codigo", header: "Código", type: "number", align: "right", get: (x) => num(x.f.matricula), cell: ({ f }) => f.matricula
      ? <span className="font-medium tabular-nums text-foreground/70">{f.matricula}</span>
      : <span className="text-muted-foreground/50" title="Sem código no cadastro — a importação grava sozinha na primeira vez">—</span> },
    { key: "nome", header: "Nome do empregado", get: (x) => `${x.f.nome} ${x.f.matricula || ""}`, cell: ({ f, v }) => (
      <div className="min-w-0">
        <p className="truncate font-medium text-foreground">{f.nome}</p>
        <p className="truncate text-xs text-muted-foreground/80">{f.empresa}{f.rg ? ` · ident. ${f.rg}` : ""}</p>
      </div>
    ) },
    { key: "vinculo", header: "Vínculo", get: (x) => x.v.vinculo, cell: ({ f, v }) => v.emTreino
      ? <Badge cls="bg-warning/8 text-warning-ink"><GraduationCap size={11} /> Treinamento</Badge>
      : f.tipoContrato && f.tipoContrato !== "CLT Ativo"
        ? <Badge cls="bg-primary/8 text-primary">{f.tipoContrato}</Badge>
        : <Badge cls="bg-secondary text-foreground/70">CLT</Badge> },
    { key: "base", header: "Base do cálculo", type: "number", align: "right", get: (x) => x.v.baseSalario, cell: ({ v }) => (
      <span>{fmtBRL(v.baseSalario)}
        <span className="block text-[11px] text-muted-foreground/80">{v.tipoRegra === "valor" ? "valor fixo" : `${v.pct.toFixed(0)}%${v.emTreino ? " do proporcional" : ""}`}</span>
      </span>
    ) },
    { key: "valor", header: "Valor do vale", type: "number", align: "right", get: (x) => x.v.valor, cell: (x) => (
      <span className="tabular-nums text-foreground/80" title="Vem da regra cadastrada na pessoa (% ou valor manual) ou da importação da contabilidade — ajusta pelo lápis ou pela importação">{fmtBRL(x.v.valor)}</span>
    ) },
    { key: "descFalta", header: "Desconto por falta", type: "number", align: "right", get: (x) => x.v.descontoFalta, cell: ({ f, v }) => v.descontoFalta > 0
      ? <span className="font-medium text-destructive" title="Lançado em Atestados e Faltas (só a parte de salário) — já abatido do vale">- {fmtBRL(v.descontoFalta)}<span className="block text-[11px] text-muted-foreground/80">de {fmtBRL(v.valorBruto)}</span></span>
      : v.descontoIgnorado > 0
        ? <span className="text-muted-foreground/80" title={`Há ${fmtBRL(v.descontoIgnorado)} de falta lançada, mas este contrato não desconta no vale`}>—
            <span className="block text-[11px]">{v.pago ? "vale já pago" : v.emTreino ? "treinamento: já é por dias trabalhados" : f.tipoContrato === "CLT Ativo" ? "CLT: desconta na folha" : `${f.tipoContrato}: não desconta no vale`}</span>
          </span>
        : <span className="text-muted-foreground/50">—</span> },
    /* COMPLEMENTO: valor que a pessoa recebeu por fora. Soma no total e, por isso, abate
       no líquido da Folha de Repasse. Fica em campo próprio para não sujar o valor do
       vale que veio da contabilidade. */
    { key: "compl", header: "Complemento", type: "number", align: "right", sortable: false, get: (x) => x.v.complemento, cell: (x) => x.v.pago ? (
      x.v.complemento > 0
        ? <span className="tabular-nums text-foreground/80" title={x.v.complementoObs || undefined}>{fmtBRL(x.v.complemento)}{x.v.complementoObs && <span className="block text-[11px] text-muted-foreground/80">{x.v.complementoObs}</span>}</span>
        : <span className="text-muted-foreground/50">—</span>
    ) : (
      <span className="inline-block w-32 text-left">
        <span className="block" onBlur={() => salvarComplemento(x)}>
          <MoedaInput className={`${inputCls} h-8 py-1 text-right`} value={complDe(x)} onChange={(v) => setD(x.f.id, { compl: v })} />
        </span>
        {(complDe(x) > 0 || x.v.complementoObs) && (
          <input className={`${inputCls} mt-1 h-7 py-0 text-[11px]`} placeholder="do que é?" maxLength={40}
            value={draft[x.f.id]?.complObs ?? x.v.complementoObs}
            onChange={(e) => setD(x.f.id, { complObs: e.target.value })} onBlur={() => salvarComplObs(x)} />
        )}
      </span>
    ) },
    { key: "total", header: "Total do vale", type: "number", align: "right", get: (x) => x.v.total, cell: ({ v }) => (
      <span className="font-semibold text-foreground">{fmtBRL(v.total)}
        {v.complemento > 0 && <span className="block text-[11px] text-muted-foreground/80">{fmtBRL(v.valor)} + {fmtBRL(v.complemento)}</span>}
      </span>
    ) },
    { key: "data", header: "Data do pagamento", sortable: false, get: (x) => x.v.dataPrevista || "", cell: (x) => x.v.pago ? (
      <span className="tabular-nums text-success">{fmtData(x.v.dataPago)}</span>
    ) : (
      <input type="date" min={primeiroDiaComp(comp)} max={ultimoDiaComp(comp)} className={`${inputCls} h-8 w-36 py-1`}
        value={draft[x.f.id]?.data ?? (x.v.dataPrevista || "")}
        onChange={(e) => setDraft((p) => ({ ...p, [x.f.id]: { ...(p[x.f.id] || {}), data: e.target.value } }))}
        onBlur={() => salvarData(x)} />
    ) },
    { key: "status", header: "Situação", get: (x) => (x.v.pago ? "Pago" : "Pendente"), cell: ({ v }) => (
      <div>
        {v.pago ? <Badge cls="bg-success/8 text-success"><Lock size={11} /> Pago</Badge> : <Badge cls="bg-warning/8 text-warning-ink">Pendente</Badge>}
        {v.importado && <span className="mt-0.5 block text-[11px] text-primary">da contabilidade</span>}
        {!v.pago && v.reabertoEm && <span className="mt-0.5 block text-[11px] text-muted-foreground/80" title={`por ${v.reabertoPor || "—"}`}>reaberto em {fmtData(v.reabertoEm.slice(0, 10))}</span>}
        {!v.temRegistro && <span className="mt-0.5 block text-[11px] text-muted-foreground/80">sem lançamento</span>}
      </div>
    ) },
  ];

  const headers = ["Codigo", "Nome do empregado", "Identidade", "Empresa", "Vinculo", "Base", "Percentual", "Valor cheio", "Desconto por falta", "Valor do vale", "Complemento", "Total", "Data", "Situacao"];
  const rowsExport = linhas.map(({ f, v }) => [f.matricula || "", f.nome, f.rg || "", f.empresa, v.vinculo, v.baseSalario, `${v.pct.toFixed(0)}%`, v.valorBruto, v.descontoFalta, v.valor, v.complemento, v.total, fmtData(v.pago ? v.dataPago : v.dataPrevista), v.pago ? "Pago" : "Pendente"]);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <h2 className="text-base font-semibold text-foreground">Vale (adiantamento)</h2>
          <p className="text-xs text-muted-foreground">{compLabel(comp)} · pagamento no dia <strong>{fmtData(dataPadrao)}</strong>{(config?.valeDia || VALE_DIA_PADRAO) !== new Date(dataPadrao + "T12:00:00").getDate() ? " (ajustado para dia útil)" : ""} · CLT e treinamento juntos</p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <input type="month" className={`${inputCls} w-40`} value={comp} onChange={(e) => setComp(e.target.value)} />
          <Btn variant="secondary" onClick={() => setImportOpen(true)}><Upload size={15} /> Importar da contabilidade</Btn>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <Kpi icon={Wallet} label="Vale do mês (total)" value={fmtBRL(totGeral)} tone="amber" />
        <Kpi icon={Users} label={`CLT (${nCLT})`} value={fmtBRL(totCLT)} onClick={() => setFVinc("CLT")} />
        <Kpi icon={GraduationCap} label={`Treinamento (${nTreino})`} value={fmtBRL(totTreino)} tone="blue" onClick={() => setFVinc("Treinamento")} />
        <Kpi icon={CheckCircle2} label={`Pago / falta pagar${totCompl > 0 ? ` · compl. ${fmtBRL(totCompl)}` : ""}`} value={`${fmtBRL(totPago)} / ${fmtBRL(totFalta)}`} tone={totFalta > 0 ? "amber" : "emerald"} onClick={() => setFStatus("pendentes")} />
      </div>

      {totDescFalta > 0 && (
        <p className="text-xs text-foreground/70">Já descontado do vale: <strong className="tabular-nums text-destructive">{fmtBRL(totDescFalta)}</strong> de falta lançada em Atestados e Faltas. Descontam no vale apenas <strong>Estágio e PJ</strong> — CLT não (a falta desconta na folha da contabilidade) e Treinamento não (já é pago por dias trabalhados). Só a parte de salário entra: VT e VR têm controle próprio. Vale já pago não muda: o que saiu, saiu.</p>
      )}

      {importsDoMes.length > 0 && (
        <div className="flex flex-wrap items-center gap-x-4 gap-y-1 rounded-md border border-border bg-secondary/50 px-3 py-2 text-xs text-muted-foreground">
          <span className="font-semibold uppercase tracking-wide text-muted-foreground/80">Importações de {compLabel(comp)}</span>
          {importsDoMes.slice(0, 3).map((x) => (
            <span key={x.id} className="inline-flex items-center gap-1"><Paperclip size={12} className="text-muted-foreground/80" />{x.arquivo} · {x.aplicadas} de {x.linhas} linha(s)</span>
          ))}
        </div>
      )}

      <DataTable
        key={comp} columns={columns} rows={linhas} getId={(x) => x.f.id} pageSize={20} selectable
        searchPlaceholder="Buscar por nome ou código..." initialSort={{ key: "nome", dir: "asc" }}
        vazio="Ninguém com vale neste filtro."
        rowClassName={(x) => (x.v.pago ? "bg-success/5" : "")}
        filtros={<>
          {!empresaPermitida && <SelectEmpresa value={fEmp} onChange={setFEmp} />}
          <select className={selCls} value={fVinc} onChange={(e) => setFVinc(e.target.value)}>
            {VALE_VINCULOS.map((v) => <option key={v} value={v}>{v === "Todos" ? "Todos os vínculos" : v}</option>)}
          </select>
          <select className={selCls} value={fStatus} onChange={(e) => setFStatus(e.target.value)}>
            <option value="todos">Todas as situações</option>
            <option value="pendentes">Só pendentes</option>
            <option value="pagos">Só pagos</option>
            <option value="importados">Só os da contabilidade</option>
          </select>
        </>}
        toolbarRight={<ExportButtons titulo={`Vale ${comp}`} headers={headers} rows={rowsExport} resumo={`Total ${fmtBRL(totGeral)} · CLT ${fmtBRL(totCLT)} · Treinamento ${fmtBRL(totTreino)}`} />}
        bulkActions={(ids, limpar) => (<>
          <Btn size="sm" onClick={() => { if (marcarPago(ids, true)) limpar(); }}><CheckCircle2 size={14} /> Marcar como pago</Btn>
          <Btn size="sm" variant="secondary" onClick={() => { if (reabrir(ids, true)) limpar(); }}><RotateCcw size={14} /> Reabrir</Btn>
        </>)}
        actions={(x) => (x.v.pago ? (<>
          <span className="inline-flex items-center gap-1 text-xs text-success" title={`Pago em ${fmtData(x.v.dataPago)} — registro travado`}><Lock size={13} /></span>
          <IconBtn icon={RotateCcw} title="Reabrir (desmarcar pago e liberar a edição)" onClick={() => reabrir([x.f.id])} />
        </>) : (<>
          <IconBtn icon={CheckCircle2} title="Marcar como pago" onClick={() => marcarPago([x.f.id])} />
          <IconBtn icon={Pencil} title="Regra do vale desta pessoa" onClick={() => setRegraDe(x.f)} />
        </>))}
        rodape={(rows) => {
          const t = (fil) => arred2(rows.filter(fil).reduce((s, x) => s + x.v.total, 0));
          return (
            <div className="flex flex-wrap items-center justify-end gap-x-6 gap-y-1 text-sm">
              <span className="mr-auto text-xs font-semibold uppercase tracking-wide text-muted-foreground/80">Total de {compLabel(comp)} · {rows.length} pessoa(s)</span>
              <span className="text-muted-foreground">CLT <strong className="tabular-nums text-foreground">{fmtBRL(t((x) => !x.v.emTreino))}</strong></span>
              <span className="text-muted-foreground">Treinamento <strong className="tabular-nums text-primary">{fmtBRL(t((x) => x.v.emTreino))}</strong></span>
              <span className="text-muted-foreground">Total <strong className="tabular-nums text-warning-ink">{fmtBRL(t(() => true))}</strong></span>
            </div>
          );
        }}
      />

      {nTreino > 0 && (
        <div className="flex items-start gap-2 rounded-md border border-warning/30 bg-warning/8 px-3 py-2.5 text-sm text-warning-ink">
          <AlertTriangle size={16} className="mt-0.5 shrink-0" />
          <span>
            <strong>{nTreino} pessoa(s) em treinamento</strong> nesta lista. O vale delas é calculado sobre o <strong>salário proporcional aos dias trabalhados até {fmtData(dataPadrao)}</strong> (o mesmo cálculo da tela de Processamento de Treinamento), e não sobre o salário mensal cheio.
            <span className="block text-xs">Ao marcar como pago, o valor <strong>também entra como salário já pago</strong> em Folha de Pagamento &gt; Proc. Treinamento e abate o saldo de lá — assim o mesmo dinheiro não é pago duas vezes.</span>
          </span>
        </div>
      )}
      <p className="text-xs text-muted-foreground/80">
        O valor, o complemento e a data são editáveis direto na linha enquanto o vale está <strong>pendente</strong>; depois de pago o lançamento trava — e o botão <strong>Reabrir</strong> (na linha ou em lote, pelos selecionados) destrava de volta, apagando a data de pagamento e estornando o que o vale tiver lançado em Proc. Treinamento. É o <strong>mesmo lançamento</strong> que aparece na Folha de Repasse &gt; Adiantamento (um por pessoa por competência), então marcar aqui ou lá dá no mesmo e nunca conta duas vezes — a diferença é que esta aba mostra também quem está em treinamento.
        <span className="mt-1 block"><strong>Complemento</strong> é valor que a pessoa recebeu por fora do vale. Ele soma no total adiantado e, por isso, <strong>abate no líquido</strong> da Folha de Repasse — o valor do vale em si continua sendo o que veio da contabilidade.</span>
      </p>

      {importOpen && (
        <ImportarRepasseModal
          comp={comp} funcsMatch={ativos} atualDe={atualDe} exigirAdiantamento
          titulo="Importar vales da contabilidade" contexto="Vale (adiantamento)"
          onAplicar={aplicarImport} onRegistrar={registrarImport}
          onGravarMatriculas={(pares) => pares.forEach(({ id, matricula }) => atualizarFunc(id, { matricula }))}
          onUsarCompetencia={(c) => setComp(c)}
          onClose={() => setImportOpen(false)}
        />
      )}
      {regraDe && <AdiantamentoRegraModal func={regraDe} config={config} onClose={() => setRegraDe(null)} onSalvar={(patch) => { atualizarFunc(regraDe.id, patch); setRegraDe(null); }} />}
    </div>
  );
}

// (A tela "Adiantamentos por funcionário" foi removida: era código morto e imprimia salário − adiantamento
// com o rótulo "Restante (líquido)". O adiantamento de verdade vive na Folha de Repasse › Adiantamento.)
function BeneficioModal({ func, config, onClose, onSalvar }) {
  const [b, setB] = useState(func.beneficios);
  const set = (chave, patch) => setB((p) => ({ ...p, [chave]: { ...p[chave], ...patch } }));
  const fSim = { ...func, beneficios: b };
  function salvar() {
    const hist = [...(func.beneficiosHistorico || [])];
    const antesAd = valorAdiantamento(func, config), depoisAd = valorAdiantamento(fSim, config);
    if (antesAd !== depoisAd) hist.push({ id: uid(), data: hojeISO(), beneficio: "Adiantamento", de: antesAd, para: depoisAd });
    const antesVR = func.beneficios.vr.ativo ? vrInfo(func, config).valorMensal : 0, depoisVR = b.vr.ativo ? vrInfo(fSim, config).valorMensal : 0;
    if (antesVR !== depoisVR) hist.push({ id: uid(), data: hojeISO(), beneficio: "Vale-Refeição", de: antesVR, para: depoisVR });
    onSalvar({ beneficios: b, beneficiosHistorico: hist });
  }
  return (
    <Modal title={`Benefícios — ${func.nome}`} subtitle={func.empresa} onClose={onClose} max="max-w-lg" footer={<><Btn variant="secondary" onClick={onClose}>Cancelar</Btn><Btn onClick={salvar}><Save size={16} /> Salvar</Btn></>}>
      <div className="space-y-3">
        <BenefToggle label="Vale-Refeição" ativo={b.vr.ativo} onToggle={(v) => set("vr", { ativo: v })}>
          <div className="grid grid-cols-2 gap-3"><Field label="Valor por dia" hint={`Vazio = padrão (${fmtBRL(config.vrDiario)})`}><MoedaInput value={b.vr.valorDia} onChange={(v) => set("vr", { valorDia: v })} /></Field><Field label="Dias no mês" hint={`Vazio = ${diasBaseVR(config)} (base do mês)`}><input type="number" className={inputCls} value={b.vr.diasTrabalhados} onChange={(e) => set("vr", { diasTrabalhados: e.target.value })} placeholder={`${diasBaseVR(config)}`} /></Field></div>
        </BenefToggle>
        <BenefToggle label="Adiantamento Salarial" ativo={b.adiantamento.ativo} onToggle={(v) => set("adiantamento", { ativo: v })}>
          <div className="grid grid-cols-2 gap-3"><Field label="Tipo"><select className={inputCls} value={b.adiantamento.tipo} onChange={(e) => set("adiantamento", { tipo: e.target.value })}><option value="padrao">Padrão ({config.percentualAdiant}%)</option><option value="personalizado">Percentual personalizado</option><option value="valor">Valor manual (R$)</option></select></Field>{b.adiantamento.tipo === "personalizado" && <Field label="% do salário"><input type="number" className={inputCls} value={b.adiantamento.percentual} onChange={(e) => set("adiantamento", { percentual: e.target.value })} /></Field>}{b.adiantamento.tipo === "valor" && <Field label="Valor"><MoedaInput value={b.adiantamento.valorManual} onChange={(v) => set("adiantamento", { valorManual: v })} /></Field>}</div>
          <div className="mt-2 grid grid-cols-3 gap-2 rounded-md bg-secondary/50 p-2 text-xs"><div><p className="text-muted-foreground/80">Adiantamento</p><p className="font-semibold text-foreground/80">{fmtBRL(valorAdiantamento(fSim, config))}</p></div><div className="col-span-2"><p className="text-muted-foreground/80">Salário − adiantamento (referência)</p><p className="font-semibold text-foreground/80">{fmtBRL(liquidoFolha(fSim, config))}</p><p className="text-[11px] text-muted-foreground/80">Não é o líquido da folha — o líquido oficial vem do Extrato Mensal.</p></div></div>
        </BenefToggle>
      </div>
      {func.beneficiosHistorico?.length > 0 && (
        <div className="mt-5"><p className="mb-2 text-xs font-semibold uppercase tracking-wide text-muted-foreground/80">Histórico de alterações</p><ul className="space-y-1.5">{[...func.beneficiosHistorico].reverse().map((h) => (<li key={h.id} className="flex items-center justify-between rounded-md bg-secondary/50 px-3 py-1.5 text-xs text-foreground/70"><span>{fmtData(h.data)} · {h.beneficio}</span><span className="font-medium">{fmtBRL(h.de)} → {fmtBRL(h.para)}</span></li>))}</ul></div>
      )}
    </Modal>
  );
}

/* ==================================================================
   FOLHA / PAGAMENTOS (tabela + modais) — cálculos inalterados
   ================================================================== */
// Estado de um pagamento derivado das datas (compatível com dados antigos que usavam status/dataPagamento).
/* ==================================================================
   FOLHA DE PAGAMENTO — Demonstrativos (Departamento Pessoal)
   Tela premium que LÊ as folhas importadas (tabelas folhas/folha_itens).
   A fonte (PDF hoje, integração direta amanhã) é externa: o n8n grava,
   esta tela apresenta, confere, aprova e exporta.
   ================================================================== */
const escHtml = (s) => String(s == null ? "" : s).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));

const iniciais = (nome) => (nome || "?").split(/\s+/).filter(Boolean).slice(0, 2).map((p) => p[0]).join("").toUpperCase();
const compBonito = (c) => { if (!c) return "—"; const [a, m] = String(c).split("-"); return `${MESES_FULL[(+m || 1) - 1] || m}/${a}`; };
// Referência como o PDF imprime ("31,00", "12:06") quando foi guardada; senão, a quantidade numérica.
const refItem = (i) => { if (i.referencia_texto) return String(i.referencia_texto); const q = num(i.quantidade), r = num(i.referencia); return q ? q.toLocaleString("pt-BR") : (r ? r.toLocaleString("pt-BR") : ""); };


const HOLERITE_ESTILO = `body{font-family:Arial,sans-serif;color:#1e293b;margin:24px;font-size:12px}h1{font-size:16px;margin:0}.cab{display:flex;justify-content:space-between;border-bottom:2px solid #1e293b;padding-bottom:8px;margin-bottom:12px}.grid{display:flex;gap:16px}table{width:100%;border-collapse:collapse;margin-top:6px}th,td{border-bottom:1px solid #e2e8f0;padding:4px 6px;text-align:left}.n{text-align:right}th{background:#f1f5f9;font-size:10px;text-transform:uppercase}.tot{display:flex;justify-content:space-between;margin-top:8px;font-weight:bold;border-top:2px solid #1e293b;padding-top:4px}.liq{background:#eff6ff;border:1px solid #bfdbfe;border-radius:6px;padding:8px 12px;margin-top:12px;display:flex;justify-content:space-between;font-size:14px;font-weight:bold;color:#1d4ed8}`;

// Miolo do demonstrativo (sem <html>/<head>) — reaproveitado tanto pro PDF de 1 pessoa
// quanto pro PDF da competência inteira (um <div class="pagina"> por funcionário).
function holeriteBlocoHTML(f) {
  const linhas = (tipo) => (f.itens || []).filter((i) => i.tipo === tipo).map((i) => `<tr><td>${escHtml(i.codigo || "")}</td><td>${escHtml(i.descricao)}</td><td class="n">${escHtml(refItem(i))}</td><td class="n">${fmtBRL(i.valor)}</td></tr>`).join("");
  const totP = num(f.total_proventos) || somaItens(f.itens, "provento");
  const totD = num(f.total_descontos) || somaItens(f.itens, "desconto");
  return `<div class="cab"><div><h1>${escHtml(f.nome)}</h1><div>${escHtml(f.cargo || "")} · ${escHtml(f.empresa || "")}</div><div>CPF ${escHtml(f.cpf || "")}${f.matricula ? " · Matrícula " + escHtml(f.matricula) : ""}</div></div><div style="text-align:right"><div><b>Demonstrativo de pagamento</b></div><div>Competência ${escHtml(compBonito(f.competencia))}</div><div>Salário base: ${fmtBRL(f.salario_base)}</div></div></div>
  <div class="grid">
    <div style="flex:1"><b style="color:#047857">Proventos</b><table><thead><tr><th>Cód</th><th>Descrição</th><th class="n">Ref</th><th class="n">Valor</th></tr></thead><tbody>${linhas("provento")}</tbody></table><div class="tot"><span>Total proventos</span><span>${fmtBRL(totP)}</span></div></div>
    <div style="flex:1"><b style="color:#be123c">Descontos</b><table><thead><tr><th>Cód</th><th>Descrição</th><th class="n">Ref</th><th class="n">Valor</th></tr></thead><tbody>${linhas("desconto")}</tbody></table><div class="tot"><span>Total descontos</span><span>${fmtBRL(totD)}</span></div></div>
  </div>
  <div class="liq"><span>Líquido a receber</span><span>${fmtBRL(f.liquido)}</span></div>
  <table style="margin-top:14px"><thead><tr><th>Base INSS</th><th>Base FGTS</th><th>Valor FGTS</th><th>Base IRRF</th></tr></thead><tbody><tr><td class="n">${fmtBRL(f.base_inss)}</td><td class="n">${fmtBRL(f.base_fgts)}</td><td class="n">${fmtBRL(f.valor_fgts)}</td><td class="n">${fmtBRL(f.base_irrf)}</td></tr></tbody></table>`;
}

function holeriteHTML(f) {
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Demonstrativo ${escHtml(f.nome)} ${escHtml(f.competencia)}</title>
  <style>${HOLERITE_ESTILO}</style></head><body>${holeriteBlocoHTML(f)}</body></html>`;
}

// Todos os holerites da competência num PDF só — uma "página" (div) por funcionário,
// cada uma forçando quebra de página na impressão.
function holeritesCompetenciaHTML(lista) {
  const blocos = lista.map((f) => `<div class="pagina">${holeriteBlocoHTML(f)}</div>`).join("");
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Folha ${escHtml(compBonito(lista[0]?.competencia || ""))}</title>
  <style>${HOLERITE_ESTILO} .pagina{page-break-after:always}</style></head><body>${blocos}</body></html>`;
}


// Leitura de PDF (pdf.js) + OCR (Tesseract) no próprio navegador — grátis, sem IA paga e sem chave.
// Carregado sob demanda (só quando o usuário importa) para não pesar o carregamento do app.
async function carregarMotorOCR() {
  const pdfjsLib = await import("pdfjs-dist");
  const worker = await import("pdfjs-dist/build/pdf.worker.min.mjs?url");
  pdfjsLib.GlobalWorkerOptions.workerSrc = worker.default;
  const Tesseract = (await import("tesseract.js")).default;
  return { pdfjsLib, Tesseract };
}
// Renderiza cada página do PDF numa imagem e passa no OCR (português). Retorna o texto lido.
async function ocrPdf(file, onProgress) {
  const { pdfjsLib, Tesseract } = await carregarMotorOCR();
  const buf = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;
  const n = pdf.numPages;
  let texto = "";
  for (let p = 1; p <= n; p++) {
    onProgress && onProgress(Math.round(((p - 1) / n) * 90) + 5, `Lendo página ${p} de ${n}...`);
    const page = await pdf.getPage(p);
    const viewport = page.getViewport({ scale: 2 });
    const canvas = document.createElement("canvas");
    canvas.width = viewport.width; canvas.height = viewport.height;
    await page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise;
    const res = await Tesseract.recognize(canvas, "por");
    texto += "\n\n" + ((res && res.data && res.data.text) || "");
    canvas.width = canvas.height = 0;
  }
  onProgress && onProgress(100, "Leitura concluída.");
  return texto;
}
// Converte "1.980,00" -> 1980.00 (formato brasileiro).
const parseNumBR = (s) => { const x = String(s == null ? "" : s).replace(/[^\d,\-]/g, "").replace(",", "."); const v = parseFloat(x); return isNaN(v) ? 0 : v; };
// Reconstrói as LINHAS de uma página a partir dos fragmentos de texto do pdf.js: agrupa por Y
// (tolerância de 3pt) e ordena por X. Sem isso os pedaços vêm soltos e o rótulo da verba perde o
// valor que está na mesma linha — que é justamente o que a gente precisa casar.
function agruparLinhasPdf(items) {
  const linhas = new Map();
  (items || []).forEach((it) => {
    const s = (it && it.str) || ""; if (!s.trim()) return;
    const y = Math.round(((it.transform && it.transform[5]) || 0) / 3) * 3;
    const x = (it.transform && it.transform[4]) || 0;
    if (!linhas.has(y)) linhas.set(y, []);
    linhas.get(y).push({ x, s });
  });
  return [...linhas.entries()]
    .sort((a, b) => b[0] - a[0])                    // Y maior = mais alto na página
    .map(([, ps]) => ps.sort((a, b) => a.x - b.x).map((p) => p.s).join(" ").replace(/\s{2,}/g, " ").trim())
    .filter(Boolean).join("\n");
}
// Texto de um arquivo: PDF digital sai pela CAMADA DE TEXTO (leitura exata, rápida, sem OCR); só
// cai no OCR (Tesseract) quando a página não tem texto — PDF escaneado ou foto. Imagem vai direto.
async function textoDeArquivoPdf(file, onProgress) {
  const ehPdf = /pdf/i.test(file.type || "") || /\.pdf$/i.test(file.name || "");
  const { pdfjsLib, Tesseract } = await carregarMotorOCR();
  if (!ehPdf) {
    onProgress && onProgress(15, "Lendo a imagem (OCR)...");
    const res = await Tesseract.recognize(file, "por");
    onProgress && onProgress(100, "Leitura concluída.");
    return (res && res.data && res.data.text) || "";
  }
  const pdf = await pdfjsLib.getDocument({ data: await file.arrayBuffer() }).promise;
  const n = pdf.numPages;
  let texto = "", ocrUsado = false;
  for (let p = 1; p <= n; p++) {
    onProgress && onProgress(Math.round(((p - 1) / n) * 90) + 5, `Lendo página ${p} de ${n}...`);
    const page = await pdf.getPage(p);
    const linhas = agruparLinhasPdf((await page.getTextContent()).items);
    if (linhas.replace(/\s/g, "").length >= 20) { texto += "\n" + linhas; continue; }
    ocrUsado = true;                                 // página sem texto → escaneada
    onProgress && onProgress(Math.round(((p - 1) / n) * 90) + 5, `Página ${p} é escaneada — usando OCR...`);
    const viewport = page.getViewport({ scale: 2 });
    const canvas = document.createElement("canvas");
    canvas.width = viewport.width; canvas.height = viewport.height;
    await page.render({ canvasContext: canvas.getContext("2d"), viewport }).promise;
    const res = await Tesseract.recognize(canvas, "por");
    texto += "\n" + ((res && res.data && res.data.text) || "");
    canvas.width = canvas.height = 0;
  }
  onProgress && onProgress(100, ocrUsado ? "Leitura concluída (com OCR — confira os valores)." : "Leitura concluída.");
  return texto;
}
// Rótulos que a contabilidade usa para cada verba do "Relatório Analítico do Cálculo de Rescisão".
// A ORDEM IMPORTA: o primeiro termo que casar ganha a linha, então o mais específico vem antes
// ("vale transporte não utilizado" antes de "vale transporte"; "INSS 13º" antes de "INSS").
const SINONIMOS_VERBAS = [
  { key: "desc_vt_nao_utilizado", termos: ["vale transporte nao utilizado", "vt nao utilizado", "transporte nao utilizado"] },
  { key: "desc_vr_nao_utilizado", termos: ["vale refeicao nao utilizado", "vr nao utilizado", "refeicao nao utilizado", "vale alimentacao nao utilizado"] },
  { key: "desc_inss_decimo", termos: ["inss 13", "inss sobre 13", "inss s 13", "inss grat natalina", "inss decimo terceiro", "inss sobre gratificacao"] },
  { key: "decimo_avos_indenizado", termos: ["13 1/12", "13 salario 1/12", "grat natalina 1/12", "decimo terceiro 1/12", "13 avos indenizado", "13 salario indenizado"] },
  { key: "decimo_integral", termos: ["13 salario integral", "13 integral", "grat natalina integral", "decimo terceiro integral", "gratificacao natalina"] },
  { key: "terco_ferias_proporcionais", termos: ["1/3 ferias proporcionais", "terco ferias proporcionais", "1/3 constitucional proporcionais", "abono 1/3 proporcionais"] },
  { key: "terco_ferias_indenizadas", termos: ["1/3 ferias indenizadas", "terco ferias indenizadas", "1/3 constitucional indenizadas", "1/3 ferias", "abono 1/3"] },
  { key: "ferias_avos_indenizado", termos: ["ferias 1/12", "ferias avos indenizado", "ferias indenizadas", "ferias vencidas"] },
  { key: "ferias_proporcionais", termos: ["ferias proporcionais"] },
  { key: "aviso_previo", termos: ["aviso previo"] },
  { key: "saldo_salario", termos: ["saldo de salario", "saldo salario", "salario do mes"] },
  { key: "desc_troco_mes_anterior", termos: ["troco mes anterior", "troco"] },
  { key: "desc_dias_faltas", termos: ["dias faltas", "desconto faltas", "dias de falta", "faltas"] },
  { key: "desc_vale_transporte", termos: ["vale transporte", "vt"] },
  { key: "desc_inss_rescisao", termos: ["inss sobre rescisao", "inss rescisao", "inss"] },
];
// Normaliza para casar rótulo: sem acento, minúsculo, sem pontuação — mas MANTÉM a barra, senão
// "1/12" e "1/3" (que distinguem verbas parecidas) viram a mesma coisa.
const normVerba = (s) => String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036F]/g, "").replace(/[\u00BA\u00AA\u00B0]/g, "").replace(/[^a-z0-9/]+/g, " ").replace(/\s+/g, " ").trim();
const reTermoVerba = (t) => new RegExp("(^|\\s)" + t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&").replace(/\s+/g, "\\s+") + "($|\\s)");
// Todos os números com centavos da linha, na ordem ("1.234,56" e "234,56"; o código da verba, que
// vem sem centavos, é ignorado de propósito).
const moedasDaLinha = (linha) => (String(linha || "").match(/-?\d{1,3}(?:\.\d{3})*,\d{2}|-?\d+,\d{2}/g) || []);
// Lê o texto do relatório da contabilidade e devolve as verbas reconhecidas (chave do card,
// rótulo lido, referência e valor), os totais que o PDF declara e os nomes encontrados.
// Heurística de coluna: o ÚLTIMO número com centavos da linha é o valor; se houver outro antes
// dele, é a referência (dias/avos). Verbas repetidas somam, e as linhas de total nunca viram verba.
// Função PURA — é ela que os autotestes exercitam.
function parseFolhaRescisaoTexto(texto) {
  const linhas = String(texto || "").replace(/\r/g, "\n").split("\n").map((l) => l.trim()).filter(Boolean);
  const achados = {};
  const totais = { proventos: null, descontos: null, liquido: null };
  const nomes = [];
  linhas.forEach((linha) => {
    const n = normVerba(linha);
    if (!n) return;
    const moedas = moedasDaLinha(linha);
    const nome = linha.match(/(?:empregado|funcionario|nome)\s*:?\s*([A-ZÀ-Ú][A-ZÀ-Ú\s.]{5,60})/i);
    if (nome) nomes.push(nome[1].trim().replace(/\s{2,}/g, " "));
    if (!moedas.length) return;
    const valor = parseNumBR(moedas[moedas.length - 1]);
    // Linhas de TOTAL: viram validação, nunca verba.
    if (/total (de )?(vencimentos|proventos|creditos)/.test(n)) { totais.proventos = valor; return; }
    if (/total (de )?descontos/.test(n)) { totais.descontos = valor; return; }
    if (/(liquido a receber|total liquido|valor liquido|liquido rescisao)/.test(n)) { totais.liquido = valor; return; }
    if (/^(base|fgts|deposito|saldo fgts|irrf base|total)/.test(n)) return;
    const hit = SINONIMOS_VERBAS.find((v) => v.termos.some((t) => reTermoVerba(t).test(n)));
    if (!hit) return;
    const ref = moedas.length > 1 ? moedas[0] : "";
    const at = achados[hit.key];
    if (at) { at.valor = Math.round((at.valor + valor + Number.EPSILON) * 100) / 100; at.rotulos.push(linha); }
    else achados[hit.key] = { key: hit.key, valor, ref, rotulos: [linha] };
  });
  const itens = VERBAS_RESCISAO.flatMap((g) => g.itens.map((i) => ({ ...i, tipo: g.tipo })))
    .filter((i) => achados[i.key])
    .map((i) => ({ key: i.key, label: i.label, tipo: i.tipo, ...achados[i.key] }));
  const somaProv = itens.filter((i) => i.tipo === "prov").reduce((s, i) => s + i.valor, 0);
  const somaDesc = itens.filter((i) => i.tipo === "desc").reduce((s, i) => s + i.valor, 0);
  const r2 = (v) => Math.round((v + Number.EPSILON) * 100) / 100;
  return { itens, totais, nomes, somaProv: r2(somaProv), somaDesc: r2(somaDesc), somaLiquido: r2(somaProv - somaDesc), linhas: linhas.length };
}
// Quebra o texto do OCR em um funcionário por CPF e puxa os campos por palavra-chave.
// Leitura APROXIMADA (foto + OCR erram); o usuário confere/corrige na tabela antes de salvar.
function parseExtratoOCR(texto, competencia, empresaHint) {
  const t = String(texto || "").replace(/\r/g, "\n");
  const cpfRe = /(\d{3}\.?\s?\d{3}\.?\s?\d{3}\s?-?\s?\d{2})/g;
  const cpfs = []; let m;
  while ((m = cpfRe.exec(t))) cpfs.push({ cpf: m[1], pos: m.index });
  if (!cpfs.length) return [];
  const rows = [];
  for (let i = 0; i < cpfs.length; i++) {
    const ini = i === 0 ? 0 : Math.floor((cpfs[i - 1].pos + cpfs[i].pos) / 2);
    const fim = i + 1 < cpfs.length ? Math.floor((cpfs[i].pos + cpfs[i + 1].pos) / 2) : t.length;
    const b = t.slice(ini, fim);
    const g = (re) => { const x = b.match(re); return x ? x[1].trim().replace(/\s{2,}/g, " ") : ""; };
    const gn = (re) => parseNumBR(g(re));
    rows.push({
      id: "r" + i, competencia, empresa: empresaHint || "",
      cpf: cpfs[i].cpf.replace(/\D/g, ""),
      nome: g(/Empr[.:\s]*\d*\s*([A-ZÀ-Ú][A-ZÀ-Ú .]{4,50})/),
      cargo: g(/Cargo[.:\s]*\d*\s*([A-ZÀ-Ú][A-ZÀ-Ú ()\/.\-]{2,50})/i),
      situacao: (b.match(/Situa[cç][aã]o[.:\s]*([A-Za-zç]+)/i) || [])[1] || "",
      salario_base: gn(/Sal[aá]rio[.:\s]*([\d.,]+)/i),
      proventos: gn(/Proventos?[.:\s]*([\d.,]+)/i),
      descontos: gn(/Descontos?[.:\s]*([\d.,]+)/i),
      liquido: gn(/L[ií]quido[.:\s]*([\d.,]+)/i),
      base_inss: gn(/Base\s*INSS[.:\s]*([\d.,]+)/i),
      base_fgts: gn(/Base\s*FGTS[.:\s]*([\d.,]+)/i),
      valor_fgts: gn(/Valor\s*FGTS[.:\s]*([\d.,]+)/i),
      base_irrf: gn(/Base\s*IRRF[.:\s]*([\d.,\-]+)/i),
    });
  }
  return rows;
}

/* Junta uma linha que é SÓ UM NÚMERO ("1.041,67") ao final da linha anterior — o pdf.js às
   vezes quebra um valor da mesma linha visual em duas linhas de texto (arredondamento de Y).
   Sem isso a referência ou o valor de uma verba fica orfão, sozinho numa linha. */
function mergeLinhasQuebradas(texto) {
  const linhas = String(texto || "").replace(/\r/g, "\n").split("\n");
  const out = [];
  for (const l of linhas) {
    if (/^\s*-?\d{1,3}(?:\.\d{3})*,\d{2}\s*$/.test(l) && out.length) out[out.length - 1] += " " + l.trim();
    else out.push(l);
  }
  return out.join("\n");
}
const MESES_EXTENSO = ["janeiro", "fevereiro", "marco", "abril", "maio", "junho", "julho", "agosto", "setembro", "outubro", "novembro", "dezembro"];
const normMes = (s) => String(s || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036F]/g, "");
// Acha "Julho de 2026" (ou variações de espaço/maiúscula) em qualquer lugar do texto e devolve
// "2026-07" — usado para PRÉ-PREENCHER a competência do import, sem travar a escolha do usuário.
function competenciaDoTexto(texto) {
  const m = String(texto || "").match(/\b(janeiro|fevereiro|mar[cç]o|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)\s+de\s+(\d{4})\b/i);
  if (!m) return "";
  const idx = MESES_EXTENSO.indexOf(normMes(m[1]));
  return idx < 0 ? "" : `${m[2]}-${String(idx + 1).padStart(2, "0")}`;
}
/* Lê o layout "Folha Mensal" — um holerite por funcionário, SEM CPF: identifica cada pessoa
   pela linha "matrícula NOME CBO departamento filial" (ex.: "12 ANDERSON KENJI TAKEDA
   253225 1 1") logo abaixo do cabeçalho "Código Nome do Funcionário CBO Departamento Filial".
   Não tenta separar cada verba (referência x vencimento x desconto, que pode vir fora de ordem
   quando uma linha quebra) — usa só os TOTAIS do rodapé de cada holerite (Total de Vencimentos/
   Descontos, Valor Líquido, Salário Base e as bases de FGTS/IRRF), que são confiáveis e é
   exatamente o que a tela de revisão precisa. Cada holerite aparece DUAS VEZES no PDF (via
   funcionário + via empresa) — dedup por matrícula mantém só a primeira ocorrência. Função
   PURA — os autotestes exercitam ela direto com o texto real de um PDF da LAPORTEC.
   Referência do formato: 260806102901OZ65t.pdf (Folha Mensal, LAPORTEC, julho/2026). */
function parseFolhaMensalTexto(texto, competenciaFallback, empresaHint) {
  const t = mergeLinhasQuebradas(texto);
  const cnpj = (t.match(/CNPJ:\s*([\d.\/-]+)/) || [])[1] || "";
  const anchors = [...t.matchAll(/^(\d{1,6})\s+([A-ZÀ-Ý][A-ZÀ-Ý()./'\- ]{2,60}?)\s+(\d{4,8})\s+(\d{1,3})\s+(\d{1,3})\s*$/gm)];
  if (!anchors.length) return [];
  const vistos = new Set();
  const rows = [];
  for (let i = 0; i < anchors.length; i++) {
    const a = anchors[i];
    const matricula = a[1];
    if (vistos.has(matricula)) continue;         // segunda cópia do mesmo holerite
    vistos.add(matricula);
    const nome = a[2].trim().replace(/\s{2,}/g, " ");
    const cbo = a[3], departamento = a[4], filial = a[5];
    const bloco = t.slice(a.index, anchors[i + 1] ? anchors[i + 1].index : t.length);
    const cargoAdm = bloco.match(/^([A-ZÀ-Ý][A-ZÀ-Ý()./\- ]{2,60}?)\s+Admiss[aã]o:\s*(\d{2})\/(\d{2})\/(\d{4})/m);
    const cargo = cargoAdm ? cargoAdm[1].trim().replace(/\s{2,}/g, " ") : "";
    const admissao = cargoAdm ? `${cargoAdm[4]}-${cargoAdm[3]}-${cargoAdm[2]}` : "";
    const totais = bloco.match(/Total de Vencimentos\s+Total de Descontos[\s\S]*?\n\s*(-?[\d.]+,\d{2})\s+(-?[\d.]+,\d{2})/);
    const liquido = bloco.match(/Valor\s*L[ií]quido\s*(-?[\d.]+,\d{2})?\s*\n?\s*(-?[\d.]+,\d{2})?/);
    const bases = bloco.match(/Sal[aá]rio Base\s+Sal\.?\s*Contr\.?\s*INSS\s+Base\s*C[aá]lc\.?\s*FGTS\s+F\.?G\.?T\.?S\s*do\s*M[eê]s\s+Base\s*C[aá]lc\.?\s*IRRF\s+Faixa\s*IRRF\s*\n\s*(-?[\d.]+,\d{2})\s+(-?[\d.]+,\d{2})\s+(-?[\d.]+,\d{2})\s+(-?[\d.]+,\d{2})\s+(-?[\d.]+,\d{2})\s+(-?[\d.]+,\d{2})/);
    rows.push({
      id: "fm" + matricula + "-" + i, competencia: competenciaFallback, empresa: empresaHint || "",
      cpf: "", matricula, cbo, departamento, filial, cnpj, admissao,
      nome, cargo, situacao: "",   // este layout não informa situação; o que vinha aqui era o REGIME
      vinculo: (bloco.match(/^(Mensalista|Horista|Diarista)\b/m) || [])[1] || "",
      salario_base: bases ? parseNumBR(bases[1]) : 0,
      proventos: totais ? parseNumBR(totais[1]) : 0,
      descontos: totais ? parseNumBR(totais[2]) : 0,
      liquido: liquido ? parseNumBR(liquido[2] || liquido[1]) : 0,
      base_inss: bases ? parseNumBR(bases[2]) : 0,
      base_fgts: bases ? parseNumBR(bases[3]) : 0,
      valor_fgts: bases ? parseNumBR(bases[4]) : 0,
      base_irrf: bases ? parseNumBR(bases[5]) : 0,
    });
  }
  return rows;
}

/* Lê o relatório OFICIAL "EXTRATO MENSAL" da contabilidade (cabeçalho "Empr.: <matrícula> NOME
   Situação: ... CPF: ... Adm: ...", linha "Vínculo/CC/Depto/Horas Mês", linha "Cargo/C.B.O/
   Filial/Salário", tabela de verbas com cada linha já marcada P (provento) ou D (desconto), e
   rodapé "ND: ... Proventos: ... Descontos: ... Líquido: ..." + "NF: ... Base INSS: ... Base
   FGTS: ... Valor FGTS: ... Base IRRF: ..."). É o formato PADRÃO a partir de 2026-08: tem CPF de
   verdade (o formato "Folha Mensal" acima não tinha) e cada verba vem com P/D — dá pra achar o
   adiantamento (código 981, DESC.ADIANT.SALARIAL) sem ambiguidade de coluna. Diretor/pró-labore
   usa "Contr:" no lugar de "Empr.:" e não tem Horas Mês (fica em branco). Função PURA — os
   autotestes exercitam ela com o texto real de um PDF da LAPORTEC (260806102901Z6lvG.pdf).
   Referência do formato antigo (sem CPF): 260806102901OZ65t.pdf → parseFolhaMensalTexto acima. */
function competenciaExtratoOficial(texto) {
  const m = String(texto || "").match(/Compet[eê]ncia:\s*(\d{2})\/(\d{4})/);
  return m ? `${m[2]}-${m[1]}` : "";
}
/* Lê CADA verba da tabela (código, descrição, referência, valor, provento/desconto) usando o
   P/D como âncora — sem isso um número pode ser lido como se pertencesse à linha errada (já
   vi acontecer: a busca "vazando" pro valor do Salário logo acima, por exemplo). Por isso o
   texto passado aqui é só o TRECHO entre "Salário: ..." e "ND:" — nunca o bloco inteiro. */
function verbasDoTrecho(spanVerbas) {
  // Descrição = qualquer coisa (não-greedy, sem quebra de linha) — já que o span é isolado, o
  // risco não é "casar demais", e sim casar de menos: "PRO-LABORE" tem hífen, "Art. 480/CLT"
  // tem minúscula, e um alfabeto fechado deixava as duas de fora (achado rodando nos 21 reais).
  // A referência normalmente é "31,00" (dias) ou "7,77" (%), mas verbas de HORAS (ex.: 8069
  // HORAS FALTAS PARCIAL) vêm como "12:06" (h:mm) — sem aceitar as duas formas essa verba
  // inteira ficava de fora (achado rodando nos 21 reais: Renata perdia 105,39 de desconto).
  const re = /(\d{1,6})\s+([^\n]+?)\s+(-?[\d.]+,\d{2}|\d{1,3}:\d{2})\s+(-?[\d.]+,\d{2})\s+([PD])\b/g;
  // A referência é guardada TAMBÉM como texto ("31,00", "7,77", "12:06"): é o que o PDF imprime,
  // e "12:06" (horas) virar 0 escondia a informação. Em "quantidade" as horas entram em decimal (12,1).
  return [...String(spanVerbas || "").matchAll(re)].map((m) => ({
    codigo: m[1], descricao: m[2].trim().replace(/\s{2,}/g, " "),
    tipo: m[5] === "P" ? "provento" : "desconto",
    quantidade: m[3].includes(":") ? arred2(FR.horasDecimais(m[3]) || 0) : parseNumBR(m[3]), valor: parseNumBR(m[4]),
    referencia_texto: m[3],
  }));
}
function parseExtratoMensalOficial(texto, competenciaFallback, empresaHint) {
  const t = mergeLinhasQuebradas(texto);
  const cnpj = (t.match(/CNPJ:\s*([\d.\/-]+)/) || [])[1] || "";
  const anchors = [...t.matchAll(/^(?:Empr|Contr)\.?:\s*(\d{1,6})\s+([A-ZÀ-Ý][A-ZÀ-Ý .'\-]*?)\s+Situa[cç][aã]o:\s*(\S+)\s+CPF:\s*([\d.\-]+)\s+Adm:\s*(\d{2})\/(\d{2})\/(\d{4})\s*$/gm)];
  if (!anchors.length) return [];
  const vistos = new Set();
  const rows = [];
  for (let i = 0; i < anchors.length; i++) {
    const a = anchors[i];
    const matricula = a[1];
    if (vistos.has(matricula)) continue;          // defensivo — este formato não costuma repetir
    vistos.add(matricula);
    const nome = a[2].trim().replace(/\s{2,}/g, " ");
    const situacao = a[3], cpf = soDigitos(a[4]), admissao = `${a[7]}-${a[6]}-${a[5]}`;
    const bloco = t.slice(a.index, anchors[i + 1] ? anchors[i + 1].index : t.length);
    const vinc = bloco.match(/V[ií]nculo:\s*(\S+)\s+CC:\s*(\S+)\s+Depto:\s*(\S+)\s+Horas\s*M[eê]s:\s*([\d.,]*)/);
    const carg = bloco.match(/Cargo:\s*(\d+)\s+([A-ZÀ-Ý()./\- ]+?)\s+C\.B\.O:\s*(\d+)\s+Filial:\s*(\S+)\s+Sal[aá]rio:\s*(-?[\d.,]+)/);
    const nd = bloco.match(/Proventos:\s*(-?[\d.,]+)\s+Descontos:\s*(-?[\d.,]+)[\s\S]*?L[ií]quido:\s*(-?[\d.,]+)/);
    const nf = bloco.match(/Base\s*INSS:\s*(-?[\d.,]+)[\s\S]*?Base\s*FGTS:\s*(-?[\d.,]+)\s+Valor\s*FGTS:\s*(-?[\d.,]+)\s+Base\s*IRRF:\s*(-?[\d.,]+)/);
    const adi = bloco.match(/\b981\s+DESC\.ADIANT\.SALARIAL\s+[\d.,]+\s+(-?[\d.,]+)\s+D\b/);
    // Trecho ISOLADO da tabela de verbas: começa logo após "Salário: X" e termina antes de
    // "ND:" — assim nenhum número da linha do Cargo/Salário (ou do rodapé) vaza pra cá.
    const spanVerbas = bloco.split(/Sal[aá]rio:\s*-?[\d.,]+\s*\n/)[1]?.split(/\nND:/)[0] || "";
    // Página do PDF em que a pessoa começa — para o "abrir o PDF na página" da tela.
    const pagina = FR.paginaNoTexto(t, a.index);
    rows.push({
      id: "em" + matricula + "-" + i, competencia: competenciaFallback, empresa: empresaHint || "",
      cpf, matricula, nome, situacao, pagina, layout: "extrato-mensal",
      vinculo: vinc ? vinc[1] : "", cc: vinc ? vinc[2] : "", departamento: vinc ? vinc[3] : "",
      horas_mensais: vinc ? parseNumBR(vinc[4]) : 0,
      cargo: carg ? carg[2].trim().replace(/\s{2,}/g, " ") : "", cbo: carg ? carg[3] : "", filial: carg ? carg[4] : "",
      cnpj, admissao,
      salario_base: carg ? parseNumBR(carg[5]) : 0,
      proventos: nd ? parseNumBR(nd[1]) : 0,
      descontos: nd ? parseNumBR(nd[2]) : 0,
      liquido: nd ? parseNumBR(nd[3]) : 0,
      base_inss: nf ? parseNumBR(nf[1]) : 0,
      base_fgts: nf ? parseNumBR(nf[2]) : 0,
      valor_fgts: nf ? parseNumBR(nf[3]) : 0,
      base_irrf: nf ? parseNumBR(nf[4]) : 0,
      adiantamento: adi ? parseNumBR(adi[1]) : 0,   // 981 DESC.ADIANT.SALARIAL — alinha com o Repasse ao salvar
      eventos: verbasDoTrecho(spanVerbas),           // cada linha da tabela — vira folha_eventos ao salvar
    });
  }
  return rows;
}

// Importa o Extrato Mensal SEM custo: lê o PDF/foto (texto real do PDF quando é digital, OCR só
// quando é escaneado/foto — textoDeArquivoPdf), mostra a PRÉVIA do que vai acontecer e só então grava
// em extratos_mensais + folha_eventos. Reimportar é IDEMPOTENTE: o mesmo arquivo não duplica nada, e
// uma versão revisada atualiza só quem mudou — guardando ANTES a versão anterior no histórico.
// Reconhece três formatos (nessa ordem): o relatório OFICIAL "Extrato Mensal" (CPF + verbas P/D), o
// holerite "Folha Mensal" por matrícula (sem CPF) e o formato genérico por CPF solto no texto.
// Importar NÃO marca nada como pago: a linha 981 prova que a folha abateu o adiantamento, não que
// alguém pagou. O pagamento do adiantamento é confirmado na aba Adiantamento da Folha de Repasse.
function ImportarExtratoModal({ empresaPermitida = "", onClose, onImportado, funcionarios = [], config, setConfig = () => {}, nomeUsuario = "" }) {
  const [file, setFile] = useState(null);
  const [comp, setComp] = useState(compAtual());
  const [empresa, setEmpresa] = useState(empresaPermitida || "");
  const [fase, setFase] = useState("idle"); // idle | lendo | revisao | salvando | ok | erro
  const [prog, setProg] = useState(0);
  const [progMsg, setProgMsg] = useState("");
  const [rows, setRows] = useState([]);
  const [textoOcr, setTextoOcr] = useState("");
  const [msg, setMsg] = useState("");
  const [cab, setCab] = useState(null);
  const [layout, setLayout] = useState("");
  const [hash, setHash] = useState("");
  const [existentes, setExistentes] = useState(null);   // null = ainda carregando (ou falhou)
  const [erroExistentes, setErroExistentes] = useState("");
  const [resultado, setResultado] = useState(null);
  const ocupado = fase === "lendo" || fase === "salvando";
  const fechada = !!config?.folhaFechamentos?.[comp]?.fechado;
  // O PDF oficial é digital: lido exato, e dado oficial não se edita. Só OCR/foto pode ser corrigido.
  const editavel = layout !== "extrato-mensal";

  // O que JÁ está gravado nesta competência — é contra isso que a prévia decide novo/revisado/igual.
  async function carregarExistentes(c) {
    setExistentes(null); setErroExistentes("");
    try {
      const q = await supabase.from("extratos_mensais").select("*").eq("competencia", c);
      if (q.error) throw q.error;
      const lista = q.data || [];
      const porEx = {};
      for (let i = 0; i < lista.length; i += 150) {
        const qe = await supabase.from("folha_eventos").select("*").in("extrato_id", lista.slice(i, i + 150).map((e) => e.id));
        if (qe.error) throw qe.error;
        (qe.data || []).forEach((ev) => { (porEx[ev.extrato_id] = porEx[ev.extrato_id] || []).push(ev); });
      }
      setExistentes(lista.map((e) => ({ ...e, eventos: porEx[e.id] || [] })));
    } catch (e) { setErroExistentes(e?.message || String(e)); }
  }

  async function ler() {
    if (!file) { setMsg("Escolha o PDF ou a foto do extrato."); return; }
    setFase("lendo"); setMsg(""); setProg(3); setProgMsg("Preparando o leitor (na 1ª vez baixa o motor de OCR)...");
    try {
      const texto = await textoDeArquivoPdf(file, (p, mm) => { setProg(p); if (mm) setProgMsg(mm); });
      setTextoOcr(texto);
      const cabecalho = FR.cabecalhoExtrato(texto);
      setCab(cabecalho); setLayout(FR.detectarLayout(texto)); setHash(await sha256Arquivo(file));
      // Competência vem do CAMPO "Competência" — nunca da data de emissão nem do nome do arquivo.
      const compDetectada = cabecalho.competencia || competenciaExtratoOficial(texto) || competenciaDoTexto(texto);
      const compUsar = compDetectada || comp;
      if (compDetectada && compDetectada !== comp) setComp(compDetectada);
      const oficial = parseExtratoMensalOficial(texto, compUsar, empresa);
      const parsed = oficial.length ? oficial : parseExtratoOCR(texto, compUsar, empresa);
      const finalRows = parsed.length ? parsed : parseFolhaMensalTexto(texto, compUsar, empresa);
      setRows(finalRows);
      setFase("revisao");
      carregarExistentes(compUsar);
      const semVerbas = finalRows.length > 0 && !finalRows.some((r) => r.eventos && r.eventos.length);
      if (!finalRows.length) setMsg("Não identifiquei funcionários automaticamente. Veja o texto lido abaixo e/ou adicione linhas à mão.");
      else if (semVerbas) setMsg("ATENÇÃO: este PDF foi lido por um formato que NÃO traz as verbas (INSS, adiantamento, faltas linha a linha) — só os totais. Dá para gravar, mas na Folha de Repasse essas pessoas ficam marcadas \"sem verbas — conferir\": o sistema não consegue conferir adiantamento nem faltas. Se tiver o PDF \"Extrato Mensal\" oficial da contabilidade, prefira ele.");
    } catch (e) {
      setFase("erro"); setMsg("Falha ao ler o arquivo: " + (e?.message || String(e)));
    }
  }

  const setLinha = (i, k, v) => setRows((p) => p.map((r, j) => (j === i ? { ...r, [k]: v } : r)));
  const removerLinha = (i) => setRows((p) => p.filter((_, j) => j !== i));

  // ── PRÉVIA: tudo derivado, nada gravado ainda ──
  const empresaArquivo = empresa || empresaPermitida || "";
  const novos = rows.map((r) => ({
    ...r, competencia: comp, cpf: soDigitos(r.cpf || ""), matricula: r.matricula ? String(r.matricula) : "",
    cnpj: r.cnpj || cab?.cnpj || "", empresa: r.empresa || empresaArquivo, nome: String(r.nome || "").trim(),
    salario_base: num(r.salario_base), proventos: num(r.proventos), descontos: num(r.descontos), liquido: num(r.liquido),
    base_inss: num(r.base_inss), base_fgts: num(r.base_fgts), valor_fgts: num(r.valor_fgts), base_irrf: num(r.base_irrf),
    eventos: r.eventos || [],
  })).filter((r) => r.nome || r.cpf);
  const plano = existentes ? FR.planejarImportacao({ existentes, novos }) : null;
  const sitPorLinha = new Map();
  if (plano) {
    plano.inserir.forEach((x) => sitPorLinha.set(x.depois, { s: "novo" }));
    plano.atualizar.forEach((x) => sitPorLinha.set(x.depois, { s: "revisado", campos: x.campos, viaNome: x.viaNome }));
    plano.inalterados.forEach((x) => sitPorLinha.set(x.depois, { s: "igual", viaNome: x.viaNome }));
    plano.semChave.forEach((x) => sitPorLinha.set(x, { s: "semchave" }));
    plano.duplicadosNoArquivo.forEach((x) => sitPorLinha.set(x, { s: "duplicado" }));
    plano.conflitoEmpresa.forEach((x) => sitPorLinha.set(x.depois, { s: "conflito" }));
  }
  const totais = FR.conferirTotais(novos, cab?.totalGeral || null);
  const layoutMapa = layout || "extrato-mensal";
  const mapa = FR.mapaEventos(layoutMapa, config?.folhaMapaEventos?.[layoutMapa]);
  const desconhecidos = [...new Map(novos.flatMap((r) => FR.eventosNaoReconhecidos(r.eventos, mapa)).map((e) => [e.codigo, e])).values()];
  const semCadastro = novos.filter((r) => !FR.vincularFuncionario(r, funcionarios, { empresa: r.empresa }).funcionario);
  const compArquivo = cab?.competencia || "";
  const compDiferente = !!compArquivo && compArquivo !== comp;
  const logsComp = config?.folhaImportacoes?.[comp] || [];
  const mesmoArquivo = hash ? logsComp.find((x) => x.hash === hash) : null;
  const nadaMuda = !!plano && !plano.inserir.length && !plano.atualizar.length;
  const bloqueio = fechada ? "Esta competência está FECHADA. Reabra na Folha de Repasse (com permissão e motivo) antes de importar."
    : compDiferente ? `O arquivo é de ${compLabel(compArquivo)} e a importação está em ${compLabel(comp)}. Use a competência do arquivo.`
    : erroExistentes ? `Não consegui ler o que já está gravado em ${compLabel(comp)} (${erroExistentes}). Sem isso não dá para garantir que nada vai duplicar — tente de novo.`
    : !plano ? "Conferindo o que já está gravado nesta competência..."
    : plano.duplicadosNoArquivo.length ? "O mesmo CPF aparece duas vezes neste arquivo. Confira a leitura antes de gravar."
    : nadaMuda ? (mesmoArquivo ? `Este arquivo já foi importado (versão ${mesmoArquivo.versao}, em ${mesmoArquivo.quando}) e nada mudou.` : "Nada novo para gravar: tudo já está igual no sistema.")
    : "";

  async function salvar() {
    if (bloqueio || !plano) return;
    setFase("salvando"); setMsg("");
    const quando = `${hojeISO()} ${horaAgora()}`;
    const versao = logsComp.reduce((m, x) => Math.max(m, num(x.versao)), 0) + 1;
    // O PDF fica guardado (bucket privado "extratos") para abrir na página certa depois.
    let pdfPath = "";
    try {
      if (file && /pdf/i.test(`${file.type} ${file.name}`)) {
        const p = `${comp}/${hash || uid()}.pdf`;
        const up = await supabase.storage.from("extratos").upload(p, file, { upsert: true, contentType: "application/pdf" });
        if (!up.error) pdfPath = p;
      }
    } catch (_) { pdfPath = ""; }
    const meta = { arquivo: file?.name || "", arquivo_hash: hash || null, emissao: cab?.emissao || null, layout: layout || null, versao, pdf_url: pdfPath || null };
    const linhaBanco = (r) => ({
      competencia: comp, empresa: r.empresa || "", nome: r.nome || "(sem nome)", cpf: r.cpf || null,
      cargo: r.cargo || "", situacao: r.situacao || "", cbo: r.cbo || "", departamento: r.departamento || "", filial: r.filial || "",
      cnpj: r.cnpj || "", admissao: r.admissao || null, vinculo: r.vinculo || "", centro_custo: r.cc || "", horas_mensais: num(r.horas_mensais) || null,
      salario_base: r.salario_base, proventos: r.proventos, descontos: r.descontos, liquido: r.liquido,
      base_inss: r.base_inss, base_fgts: r.base_fgts, valor_fgts: r.valor_fgts, base_irrf: r.base_irrf,
      matricula: r.matricula || null, pagina: r.pagina || null, ...meta,
    });
    const eventosBanco = (r, extratoId) => (r.eventos || []).map((ev, ordem) => ({
      extrato_id: extratoId, funcionario_id: null, competencia: comp, codigo: ev.codigo, descricao: ev.descricao, tipo: ev.tipo,
      quantidade: ev.quantidade, valor: ev.valor, origem: "extrato mensal", ordem,
      referencia_texto: ev.referencia_texto || null, pagina: r.pagina || null,
    }));
    let semColunasNovas = false;
    const inseridos = [], revisados = [], falhas = [];
    try {
      // 1) NOVOS — um insert em lote; se as verbas falharem, desfaz os registros recém-criados.
      if (plano.inserir.length) {
        const lista = plano.inserir.map((x) => x.depois);
        const q = await gravarComFallback((p) => supabase.from("extratos_mensais").insert(p).select("id"), lista.map(linhaBanco), COLS_EXTRATO_0010);
        if (q.semColunasNovas) semColunasNovas = true;
        if (q.error) throw new Error("Não consegui gravar os registros novos: " + q.error.message);
        // O Postgres devolve o RETURNING na mesma ordem do INSERT em lote: casa 1:1 pelo índice.
        const ids = (q.data || []).map((x) => x.id);
        const evs = lista.flatMap((r, i) => (ids[i] ? eventosBanco(r, ids[i]) : []));
        if (evs.length) {
          const qe = await gravarComFallback((p) => supabase.from("folha_eventos").insert(p), evs, COLS_EVENTO_0010);
          if (qe.semColunasNovas) semColunasNovas = true;
          if (qe.error) {
            try { await supabase.from("extratos_mensais").delete().in("id", ids); } catch (_) {}
            throw new Error(`Não gravei as verbas (${qe.error.message}). Desfiz os registros novos para não deixar extrato pela metade — tente de novo.`);
          }
        }
        ids.forEach((id, i) => inseridos.push({ id, nome: lista[i].nome }));
      }
      // 2) REVISADOS — um de cada vez: guarda a versão anterior ANTES de trocar; se a troca falhar, a
      //    cópia guardada é marcada como "não aplicada" (o histórico não diz que trocou quando não trocou).
      const naConfig = [];
      for (const { antes, depois, campos } of plano.atualizar) {
        const snap = { extratoId: antes.id, nome: antes.nome, campos, antes: semEventos(antes), eventosAntes: antes.eventos || [] };
        const guardado = await guardarVersaoAnterior({ comp, versao, arquivo: file?.name || "", substituidos: [snap], por: nomeUsuario });
        // Sem a tabela de histórico, a cópia vai para a configuração — e vai AGORA, antes de trocar
        // o registro. Guardar só no fim do laço deixava sem cópia quem já tinha sido trocado se a
        // janela fosse fechada no meio.
        if (!guardado.ok) { naConfig.push(snap); setConfig((c) => ({ ...c, folhaVersoes: { ...(c.folhaVersoes || {}), [comp]: [...((c.folhaVersoes || {})[comp] || []), { versao, quando, por: nomeUsuario, arquivo: file?.name || "", substituidos: [snap] }] } })); }
        // CPF/matrícula já gravados não são apagados por um arquivo que não os traz.
        const novaLinha = { ...linhaBanco(depois), cpf: depois.cpf || antes.cpf || null, matricula: depois.matricula || antes.matricula || null };
        // Arquivo sem verbas (só totais): as verbas já gravadas ficam como estão.
        const r = await revisarExtrato({ antes, novaLinha, novosEventos: depois.eventos?.length ? eventosBanco(depois, antes.id) : null });
        if (r.semColunasNovas) semColunasNovas = true;
        if (r.ok) revisados.push({ id: antes.id, nome: depois.nome, campos });
        else {
          falhas.push(`${depois.nome}: ${r.erro}`);
          snap.naoAplicada = true;
          if (guardado.id) { try { await supabase.from("folha_importacoes").update({ status: "Revisão não aplicada" }).eq("id", guardado.id); } catch (_) {} }
        }
      }
      // (as cópias que não couberam no banco já foram para a config, uma a uma, dentro do laço)
      // 3) Registro da importação — metadados pequenos, é o que o cabeçalho da tela mostra.
      const log = {
        id: uid(), versao, quando, por: nomeUsuario, arquivo: file?.name || "", tamanho: file?.size || 0, hash, layout,
        emissao: cab?.emissao || "", empresaPdf: cab?.empresa || "", cnpj: cab?.cnpj || "", calculo: cab?.calculo || "", paginas: cab?.paginas || null, pdfPath,
        totalGeral: cab?.totalGeral ? { proventos: FR.centavos(cab.totalGeral.proventos), descontos: FR.centavos(cab.totalGeral.descontos), liquido: FR.centavos(cab.totalGeral.liquido) } : null,
        soma: totais.soma, bate: totais.somaBateComGeral, inseridos: inseridos.length, revisados: revisados.map((x) => x.id),
        iguais: plano.inalterados.length, semChave: plano.semChave.length, conflitos: plano.conflitoEmpresa.length, falhas, semColunasNovas,
      };
      setConfig((c) => ({ ...c, folhaImportacoes: { ...(c.folhaImportacoes || {}), [comp]: [...((c.folhaImportacoes || {})[comp] || []), log] } }));
      try {
        await supabase.from("folha_importacoes").insert({
          competencia: comp, arquivo: log.arquivo, pdf_url: pdfPath || null, qtd_funcionarios: novos.length,
          qtd_avisos: falhas.length + plano.semChave.length + plano.conflitoEmpresa.length,
          avisos: { tipo: "importacao", versao, inseridos: inseridos.length, revisados: revisados.length, iguais: plano.inalterados.length, falhas },
          status: falhas.length ? "Parcial" : "Concluída", importado_por: nomeUsuario,
        });
      } catch (_) {}
      setResultado({ inseridos, revisados, iguais: plano.inalterados.length, semChave: plano.semChave, conflitos: plano.conflitoEmpresa, falhas, semColunasNovas, pdfPath, versao, pdfTentado: !!file && /pdf/i.test(`${file.type} ${file.name}`) });
      setFase("ok");
      onImportado && onImportado();
    } catch (e) {
      setFase("revisao"); setMsg(e?.message || String(e));
      if (inseridos.length || revisados.length) onImportado && onImportado();
    }
  }

  const numInput = "w-24 rounded border border-border px-1.5 py-1 text-right text-xs tabular-nums";
  const txtInput = "w-full rounded border border-border px-1.5 py-1 text-xs";
  const contagem = (rot, n, tom = "slate") => (
    <div className={`rounded-md p-2.5 ${tom === "rose" ? "bg-destructive/8" : tom === "amber" ? "bg-warning/8" : tom === "blue" ? "bg-primary/8" : "bg-secondary/50"}`}>
      <p className="text-[11px] text-muted-foreground">{rot}</p><p className="text-lg font-bold tabular-nums text-foreground">{n}</p>
    </div>
  );
  const nGravar = plano ? plano.inserir.length + plano.atualizar.length : 0;

  return (
    <Modal title="Importar Extrato Mensal" subtitle="Leitura no navegador — grátis. Nada é gravado antes da sua conferência." onClose={() => { if (!ocupado) onClose(); }} max={fase === "revisao" ? "max-w-6xl" : "max-w-lg"}
      footer={fase === "ok"
        ? <Btn onClick={onClose}>Concluir</Btn>
        : fase === "revisao"
          ? <><Btn variant="secondary" onClick={onClose}>Cancelar</Btn><Btn onClick={salvar} disabled={ocupado || !!bloqueio}><CheckCircle2 size={16} /> {bloqueio ? "Nada a gravar" : `Gravar ${plano.inserir.length} novo(s) e ${plano.atualizar.length} revisado(s)`}</Btn></>
          : <><Btn variant="secondary" onClick={onClose} disabled={ocupado}>Cancelar</Btn><Btn onClick={ler} disabled={ocupado || !file}><Upload size={16} /> {fase === "lendo" ? "Lendo..." : "Ler arquivo"}</Btn></>}>
      {(fase === "idle" || fase === "lendo" || fase === "erro") && (
        <div className="space-y-3">
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <Field label="Competência" hint="Se o PDF tiver o campo Competência, ele manda."><input type="month" className={inputCls} value={comp} onChange={(e) => setComp(e.target.value)} disabled={ocupado} /></Field>
            {!empresaPermitida && <Field label="Empresa"><select className={inputCls} value={empresa} onChange={(e) => setEmpresa(e.target.value)} disabled={ocupado}><option value="">— definir —</option>{EMPRESAS.map((x) => <option key={x}>{x}</option>)}</select></Field>}
          </div>
          <Field label="PDF ou foto do extrato">
            <input type="file" accept="application/pdf,image/*" className={inputCls} onChange={(e) => { setFile((e.target.files || [])[0] || null); setMsg(""); }} disabled={ocupado} />
          </Field>
          {file && <p className="text-xs text-muted-foreground">Arquivo: <strong>{file.name}</strong> ({Math.round(file.size / 1024)} KB)</p>}
          {fase === "lendo" && (
            <div className="rounded-md bg-primary/8 px-3 py-2 text-sm text-primary">
              <div className="mb-1 flex items-center gap-2"><RefreshCw size={14} className="animate-spin shrink-0" /> {progMsg}</div>
              <div className="h-1.5 w-full rounded-full bg-primary/15"><div className="h-1.5 rounded-full bg-primary transition-all" style={{ width: prog + "%" }} /></div>
            </div>
          )}
          {fase === "erro" && <div className="rounded-md bg-destructive/8 px-3 py-2 text-sm text-destructive">{msg}</div>}
          {fase === "idle" && msg && <div className="rounded-md bg-warning/8 px-3 py-2 text-sm text-warning-ink">{msg}</div>}
          {fase === "idle" && <p className="text-xs text-muted-foreground/80">PDF digital (com texto) é lido exatamente como está. Foto ou PDF escaneado passa por OCR e pode precisar de correção.</p>}
        </div>
      )}
      {fase === "revisao" && (
        <div className="space-y-3">
          {cab && (
            <div className="flex flex-wrap gap-x-5 gap-y-1 rounded-md border border-border bg-secondary/50 p-3 text-xs text-foreground/70">
              <span><span className="text-muted-foreground/80">Arquivo:</span> <strong>{file?.name}</strong></span>
              <span><span className="text-muted-foreground/80">Formato:</span> <strong>{FR.LAYOUTS[layout] || "não reconhecido (OCR)"}</strong></span>
              {cab.empresa && <span><span className="text-muted-foreground/80">Empresa:</span> <strong>{cab.empresa}</strong></span>}
              {cab.cnpj && <span><span className="text-muted-foreground/80">CNPJ:</span> {cab.cnpj}</span>}
              <span><span className="text-muted-foreground/80">Competência:</span> <strong>{compArquivo ? compLabel(compArquivo) : "não informada no PDF"}</strong></span>
              {cab.emissao && <span><span className="text-muted-foreground/80">Emissão:</span> {dataBR(cab.emissao)}</span>}
              {cab.calculo && <span><span className="text-muted-foreground/80">Cálculo:</span> {cab.calculo}</span>}
              {cab.paginas && <span><span className="text-muted-foreground/80">Páginas:</span> {cab.paginas}</span>}
            </div>
          )}
          {compDiferente && (
            <div className="flex flex-wrap items-center gap-2 rounded-md bg-warning/15 px-3 py-2 text-xs text-warning-ink">
              <AlertTriangle size={14} className="shrink-0" />
              <span>O arquivo é de <strong>{compLabel(compArquivo)}</strong> e a importação está em <strong>{compLabel(comp)}</strong>.</span>
              <Btn size="sm" onClick={() => { setComp(compArquivo); carregarExistentes(compArquivo); }}>Usar {compLabel(compArquivo)}</Btn>
            </div>
          )}
          {msg && <div className="rounded-md bg-warning/8 px-3 py-2 text-sm text-warning-ink">{msg}</div>}
          <div className="rounded-md border border-border p-3 text-xs">
            <p className="mb-1 font-semibold text-foreground/70">Conferência dos totais</p>
            <div className="flex flex-wrap items-center gap-x-5 gap-y-1 text-foreground/70">
              <span>Soma dos {novos.length} registro(s): proventos <strong className="tabular-nums">{brlC(totais.soma.proventos)}</strong> · descontos <strong className="tabular-nums">{brlC(totais.soma.descontos)}</strong> · líquido <strong className="tabular-nums">{brlC(totais.soma.liquido)}</strong></span>
              {totais.geral && <span>Total Geral impresso: <strong className="tabular-nums">{brlC(totais.geral.proventos)}</strong> · <strong className="tabular-nums">{brlC(totais.geral.descontos)}</strong> · <strong className="tabular-nums">{brlC(totais.geral.liquido)}</strong></span>}
              {totais.somaBateComGeral === true && <Badge cls="bg-success/8 text-success"><CheckCircle2 size={11} /> a soma bate com o Total Geral do PDF</Badge>}
              {totais.somaBateComGeral === false && <Badge cls="bg-destructive/8 text-destructive"><AlertTriangle size={11} /> a soma NÃO bate com o Total Geral — pode ter registro não lido</Badge>}
              {!totais.geral && <span className="text-muted-foreground/80">O PDF não traz Total Geral para conferir.</span>}
            </div>
            {totais.divergentes.length > 0 && <p className="mt-1 text-destructive">Não fecham (proventos − descontos ≠ líquido): {totais.divergentes.map((d) => d.nome || d.chave).join(", ")}</p>}
          </div>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4 lg:grid-cols-8">
            {contagem("Novos", plano ? plano.inserir.length : "…", "blue")}
            {contagem("Revisados", plano ? plano.atualizar.length : "…", plano?.atualizar.length ? "amber" : "slate")}
            {contagem("Sem mudança", plano ? plano.inalterados.length : "…")}
            {contagem("Sem CPF/matrícula", plano ? plano.semChave.length : "…", plano?.semChave.length ? "rose" : "slate")}
            {contagem("CPF em outra empresa", plano ? plano.conflitoEmpresa.length : "…", plano?.conflitoEmpresa.length ? "rose" : "slate")}
            {contagem("Duplicados no arquivo", plano ? plano.duplicadosNoArquivo.length : "…", plano?.duplicadosNoArquivo.length ? "rose" : "slate")}
            {contagem("Sem cadastro no CRM", semCadastro.length, semCadastro.length ? "amber" : "slate")}
            {contagem("Códigos sem significado", desconhecidos.length, desconhecidos.length ? "amber" : "slate")}
          </div>
          {plano?.atualizar.length > 0 && (
            <div className="rounded-md border border-warning/40 bg-warning/8 px-3 py-2 text-xs text-warning-ink">
              <strong>Versão revisada.</strong> {plano.atualizar.map((a) => `${a.depois.nome} (${a.campos.join(", ")})`).join("; ")}. A versão anterior de cada um fica guardada no histórico, e a conferência dessas pessoas volta para "reconferir" na Folha de Repasse. Complementos, pagamentos e demais lançamentos internos não são tocados.
            </div>
          )}
          {(plano?.semChave.length > 0 || plano?.conflitoEmpresa.length > 0) && (
            <p className="rounded-md bg-destructive/8 px-3 py-2 text-xs text-destructive">Não serão gravados: registros sem CPF nem matrícula (não dá para garantir que não duplicam) e CPF que já está gravado nesta competência por OUTRA empresa (confira qual está certo antes).</p>
          )}
          {desconhecidos.length > 0 && (
            <p className="rounded-md bg-warning/8 px-3 py-2 text-xs text-warning-ink">Códigos que o sistema ainda não sabe o que significam: {desconhecidos.map((e) => `${e.codigo} ${e.descricao}`).join(" · ")}. Eles são gravados exatamente como vieram e ficam marcados para conferência.</p>
          )}
          {bloqueio && <p className="rounded-md bg-secondary px-3 py-2 text-xs font-medium text-foreground/80">{bloqueio}</p>}
          <div className="max-h-[24rem] overflow-auto rounded-md border border-border">
            <table className="w-full min-w-[980px] text-xs">
              <thead className="sticky top-0 z-10 bg-secondary text-left text-muted-foreground"><tr>
                <th className="px-2 py-2">Pág.</th><th className="px-2 py-2">Matr.</th><th className="px-2 py-2">Nome</th><th className="px-2 py-2">CPF</th><th className="px-2 py-2">Tipo</th><th className="px-2 py-2">Situação</th>
                <th className="px-2 py-2 text-right">Salário</th><th className="px-2 py-2 text-right">Proventos</th><th className="px-2 py-2 text-right">Descontos</th><th className="px-2 py-2 text-right">Líquido</th>
                <th className="px-2 py-2">Cadastro</th><th className="px-2 py-2">Nesta importação</th>{editavel && <th className="px-2 py-2"></th>}
              </tr></thead>
              <tbody className="divide-y divide-border/60">
                {rows.map((r, i) => {
                  const n = novos.find((x) => x.id === r.id) || null;
                  const sit = n ? sitPorLinha.get(n) : null;
                  const vinc = n ? FR.vincularFuncionario(n, funcionarios, { empresa: n.empresa }) : null;
                  const cls = n ? FR.classificarRegistro(n, n.eventos, mapa) : null;
                  const s = sit ? SIT_IMPORT_EXTRATO[sit.s] : null;
                  return (
                    <tr key={r.id || i}>
                      <td className="px-2 py-1 tabular-nums text-muted-foreground/80">{r.pagina || "—"}</td>
                      <td className="px-2 py-1 tabular-nums text-muted-foreground">{r.matricula || "—"}</td>
                      <td className="px-2 py-1">{editavel ? <input className={txtInput} value={r.nome || ""} onChange={(e) => setLinha(i, "nome", e.target.value)} /> : <span className="font-medium text-foreground/80">{r.nome}</span>}</td>
                      <td className="px-2 py-1">{editavel ? <input className={txtInput + " !w-28"} value={r.cpf || ""} onChange={(e) => setLinha(i, "cpf", e.target.value)} /> : <span className="tabular-nums text-muted-foreground">{cpfMascarado(r.cpf)}</span>}</td>
                      <td className="px-2 py-1">{cls && <Badge cls={TIPO_REGISTRO[cls.tipo].cls}>{TIPO_REGISTRO[cls.tipo].txt}</Badge>}</td>
                      <td className="px-2 py-1">{editavel ? <input className={txtInput + " !w-24"} value={r.situacao || ""} onChange={(e) => setLinha(i, "situacao", e.target.value)} /> : r.situacao || "—"}</td>
                      {["salario_base", "proventos", "descontos", "liquido"].map((k) => (
                        <td key={k} className="px-2 py-1 text-right">{editavel ? <input className={numInput} value={r[k]} onChange={(e) => setLinha(i, k, e.target.value)} /> : <span className="tabular-nums text-foreground/80">{fmtBRL(r[k])}</span>}</td>
                      ))}
                      <td className="px-2 py-1">{vinc?.funcionario ? <span className="text-foreground/70">por {vinc.via}</span> : <span className="text-warning-ink">sem cadastro{vinc?.sugestoes.length ? " (há nome parecido — não vincula sozinho)" : ""}</span>}</td>
                      <td className="px-2 py-1">{s ? <Badge cls={s.cls}>{s.txt}{sit.campos ? `: ${sit.campos.join(", ")}` : ""}</Badge> : <span className="text-muted-foreground/50">…</span>}{sit?.viaNome && <span className="block text-[11px] text-warning-ink">casado pelo nome (o registro gravado não tem CPF/matrícula)</span>}</td>
                      {editavel && <td className="px-2 py-1 text-center"><button onClick={() => removerLinha(i)} className="text-muted-foreground/50 hover:text-destructive" title="Remover"><Trash2 size={13} /></button></td>}
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          <div className="flex items-center justify-between">
            {editavel ? <button onClick={() => setRows((p) => [...p, { id: "n" + uid(), competencia: comp, empresa, cpf: "", nome: "", cargo: "", situacao: "", salario_base: 0, proventos: 0, descontos: 0, liquido: 0 }])} className="text-xs font-medium text-primary hover:text-primary">+ Adicionar linha</button>
              : <span className="text-xs text-muted-foreground/80">PDF oficial: os valores são lidos exatamente como impressos e não se editam aqui.</span>}
            <span className="text-xs text-muted-foreground/80">{rows.length} registro(s) lido(s)</span>
          </div>
          <details className="rounded-md border border-border p-2">
            <summary className="cursor-pointer text-xs font-medium text-foreground/70">Ver o texto lido do arquivo</summary>
            <pre className="mt-2 max-h-48 overflow-auto whitespace-pre-wrap text-[11px] text-muted-foreground">{textoOcr || "(vazio)"}</pre>
          </details>
        </div>
      )}
      {fase === "salvando" && <div className="flex items-center gap-2 rounded-md bg-primary/8 px-3 py-2 text-sm text-primary"><RefreshCw size={14} className="animate-spin shrink-0" /> Gravando... não feche esta janela.</div>}
      {fase === "ok" && resultado && (
        <div className="space-y-2 text-sm">
          <div className="rounded-md bg-success/8 px-3 py-2.5 text-success">
            <p className="flex items-center gap-1.5 font-semibold"><CheckCircle2 size={15} /> Importação gravada — versão {resultado.versao} de {compLabel(comp)}</p>
            <p className="mt-0.5">{resultado.inseridos.length} novo(s) · {resultado.revisados.length} revisado(s) · {resultado.iguais} sem mudança.</p>
            {resultado.revisados.length > 0 && <p className="mt-0.5 text-xs">Revisados: {resultado.revisados.map((x) => x.nome).join(", ")}. A versão anterior ficou guardada.</p>}
          </div>
          {resultado.falhas.length > 0 && <div className="rounded-md bg-destructive/8 px-3 py-2 text-xs text-destructive"><strong>Não foram revisados:</strong> {resultado.falhas.join(" · ")}</div>}
          {(resultado.semChave.length > 0 || resultado.conflitos.length > 0) && <div className="rounded-md bg-warning/8 px-3 py-2 text-xs text-warning-ink">Ficaram de fora: {resultado.semChave.length} sem CPF/matrícula e {resultado.conflitos.length} com CPF de outra empresa.</div>}
          {resultado.semColunasNovas && <div className="rounded-md bg-warning/8 px-3 py-2 text-xs text-warning-ink">O banco ainda não tem as colunas da migração <strong>0010</strong>: página, matrícula, versão e a referência em horas ("12:06") não foram guardadas. Os valores foram. Rode a migração para guardar tudo.</div>}
          {resultado.pdfTentado && !resultado.pdfPath && <div className="rounded-md bg-warning/8 px-3 py-2 text-xs text-warning-ink">O PDF original não subiu para o armazenamento — os dados foram gravados, mas o botão "PDF original" não vai funcionar para esta versão.</div>}
          <p className="text-xs text-muted-foreground">Nenhum pagamento foi marcado como pago por esta importação.</p>
        </div>
      )}
    </Modal>
  );
}

function FolhaDP({ folhas = [], recarregar, empresaPermitida = "", funcionarios = [], config, setConfig = () => {}, nomeUsuario = "", admin = false, perfil = "", irPara = () => {}, setRepasseFoco = () => {} }) {
  const [importarAberto, setImportarAberto] = useState(false);
  const [extratos, setExtratos] = useState([]);
  const [eventosPorExtrato, setEventosPorExtrato] = useState({});
  const [versoesBanco, setVersoesBanco] = useState([]);
  const [erroCarga, setErroCarga] = useState("");
  const [carregando, setCarregando] = useState(true);
  const carregarExtratos = useCallback(async () => {
    setCarregando(true);
    try {
      const q = await supabase.from("extratos_mensais").select("*").order("competencia", { ascending: false });
      if (q.error) throw q.error;
      const lista = q.data || [];
      const porExtrato = {};
      // Em lotes: um único .in() com centenas de ids estoura o tamanho da URL.
      for (let i = 0; i < lista.length; i += 150) {
        const qe = await supabase.from("folha_eventos").select("*").in("extrato_id", lista.slice(i, i + 150).map((e) => e.id)).order("ordem", { ascending: true });
        if (qe.error) throw qe.error;
        (qe.data || []).forEach((ev) => { (porExtrato[ev.extrato_id] = porExtrato[ev.extrato_id] || []).push(ev); });
      }
      setExtratos(lista); setEventosPorExtrato(porExtrato); setErroCarga("");
      try { const qv = await supabase.from("folha_importacoes").select("*").eq("status", "Versão anterior"); if (!qv.error) setVersoesBanco(qv.data || []); } catch (_) {}
    } catch (e) { setErroCarga(e?.message || String(e)); }
    setCarregando(false);
  }, []);
  useEffect(() => { carregarExtratos(); }, [carregarExtratos]);
  const [fComp, setFComp] = useState("");          // "" = a competência mais recente
  const [fEmp, setFEmp] = useState("Todas");
  const [fSit, setFSit] = useState("Todas");
  const [fTipo, setFTipo] = useState("Todos");
  const [busca, setBusca] = useState("");
  const [selId, setSelId] = useState(null);
  const [aviso, setAviso] = useState("");
  const [mapear, setMapear] = useState(null);   // { ev, layout } — dar significado a um código novo

  const podeImportar = permFolha(perfil, admin).importar;
  const mapaDe = (lay) => FR.mapaEventos(lay || "extrato-mensal", config?.folhaMapaEventos?.[lay || "extrato-mensal"]);
  // Extratos importados + folhas antigas (tabela "folhas", do n8n) no mesmo formato. Tudo somente leitura.
  const registros = useMemo(() => [
    ...extratos.map((e) => normalizarRegistroFolha({ ...e, fonte: "extrato", eventos: eventosPorExtrato[e.id] || [], mapa: mapaDe(e.layout) })),
    ...folhas.map((f) => normalizarRegistroFolha({ ...f, fonte: "folha", proventos: f.total_proventos, descontos: f.total_descontos, eventos: (f.itens || []).filter((i) => i.tipo === "provento" || i.tipo === "desconto"), mapa: mapaDe("extrato-mensal") })),
  ], [extratos, eventosPorExtrato, folhas, config?.folhaMapaEventos]);
  const visiveis = empresaPermitida ? registros.filter((r) => (r.empresa || "") === empresaPermitida) : registros;
  const competencias = [...new Set(visiveis.map((r) => r.competencia).filter(Boolean))].sort().reverse();
  const compSel = fComp === "Todas" ? "Todas" : (fComp && competencias.includes(fComp) ? fComp : competencias[0] || "");
  const empresas = [...new Set(visiveis.map((r) => r.empresa).filter(Boolean))].sort();
  const situacoes = [...new Set(visiveis.map((r) => r.situacao).filter(Boolean))].sort();
  const termo = busca.trim().toLowerCase();
  const filtradas = visiveis.filter((r) =>
    (compSel === "Todas" || r.competencia === compSel) && (fEmp === "Todas" || r.empresa === fEmp) &&
    (fSit === "Todas" || r.situacao === fSit) && (fTipo === "Todos" || r.tipo === fTipo) &&
    (!termo || [r.nome, r.cargo, r.matricula, soDigitos(r.cpf)].some((x) => String(x || "").toLowerCase().includes(termo)))
  ).sort((a, b) => (b.competencia || "").localeCompare(a.competencia || "") || (a.nome || "").localeCompare(b.nome || ""));
  const soma = {
    P: FR.somaCentavos(filtradas, (r) => r.P), D: FR.somaCentavos(filtradas, (r) => r.D), L: FR.somaCentavos(filtradas, (r) => r.L),
    fgts: FR.somaCentavos(filtradas, (r) => FR.centavos(r.valor_fgts)),
    porTipo: Object.fromEntries(Object.keys(TIPO_REGISTRO).map((t) => [t, { n: filtradas.filter((r) => r.tipo === t).length, L: FR.somaCentavos(filtradas.filter((r) => r.tipo === t), (r) => r.L) }])),
  };
  const semFiltroExtra = fEmp === "Todas" && fSit === "Todas" && fTipo === "Todos" && !termo;
  // Um arquivo por empresa (CNPJ): a versão mais recente de cada, com a conferência do Total Geral.
  const logsComp = compSel !== "Todas" ? (config?.folhaImportacoes?.[compSel] || []) : [];
  const ultimosPorCnpj = [...logsComp.reduce((m, x) => m.set(soDigitos(x.cnpj) || x.arquivo, x), new Map()).values()];
  const somaDoCnpj = (cnpj) => {
    const rs = visiveis.filter((r) => r.competencia === compSel && r.fonte === "extrato" && soDigitos(r.cnpj) === soDigitos(cnpj));
    return { P: FR.somaCentavos(rs, (r) => r.P), D: FR.somaCentavos(rs, (r) => r.D), L: FR.somaCentavos(rs, (r) => r.L), n: rs.length };
  };
  const sel = visiveis.find((r) => r.id === selId) || null;
  const historico = sel ? visiveis.filter((r) => soDigitos(r.cpf) && soDigitos(r.cpf) === soDigitos(sel.cpf)).sort((a, b) => (b.competencia || "").localeCompare(a.competencia || "")) : [];
  const versoesDe = (r) => {
    if (!r) return [];
    const doBanco = versoesBanco.flatMap((v) => (v.avisos?.substituidos || []).filter((s) => s.extratoId === r.id).map((s) => ({ versao: v.avisos?.versao, quando: String(v.criado_em || "").replace("T", " ").slice(0, 16), por: v.importado_por, ...s })));
    const daConfig = Object.values(config?.folhaVersoes || {}).flat().flatMap((v) => (v.substituidos || []).filter((s) => s.extratoId === r.id && !s.naoAplicada).map((s) => ({ versao: v.versao, quando: v.quando, por: v.por, ...s })));
    return [...doBanco, ...daConfig];
  };
  const alertas = {
    naoFecha: filtradas.filter((r) => !r.fecha).length,
    verbasNaoBatem: filtradas.filter((r) => !r.verbasBatem).length,
    semVerbas: filtradas.filter((r) => r.semVerbas).length,
    desconhecidos: filtradas.filter((r) => r.naoReconhecidos.length).length,
  };

  const abrirPdf = async (path, pagina) => {
    if (!path) return;
    try {
      const { data, error } = await supabase.storage.from("extratos").createSignedUrl(path, 300);
      if (error || !data?.signedUrl) throw error || new Error("sem link");
      window.open(data.signedUrl + (pagina ? `#page=${pagina}` : ""), "_blank", "noopener");
    } catch (e) { setAviso("Não consegui abrir o PDF original agora."); }
  };
  const abrirNoRepasse = (r) => { setRepasseFoco({ comp: r.competencia, cpf: soDigitos(r.cpf), nome: r.nome, t: uid() }); irPara("pagamentos", "folha"); };
  const paraHolerite = (r) => ({ ...r, itens: r.eventos, total_proventos: r.proventos, total_descontos: r.descontos });
  const exportarExcel = (r) => baixarXLSX(`extrato_${(r.nome || "").replace(/\s+/g, "_")}_${r.competencia}`, ["Tipo", "Código", "Descrição", "Referência", "Valor", "Significado"], (r.eventos || []).map((i) => [i.tipo, i.codigo || "", i.descricao, refItem(i), num(i.valor), FR.PAPEIS[FR.papelDoEvento(i, r.mapa)] || ""]));
  const imprimirCompetencia = () => {
    const daComp = filtradas.slice().sort((a, b) => (a.nome || "").localeCompare(b.nome || ""));
    if (daComp.length) abrirImprimirHTML(holeritesCompetenciaHTML(daComp.map(paraHolerite)), `extrato_${compSel}.html`);
  };
  // Excluir: só o administrador, com a competência aberta, e a versão excluída fica guardada.
  const excluirExtrato = async (r) => {
    if (!admin || !r || r.fonte !== "extrato") return;
    if (config?.folhaFechamentos?.[r.competencia]?.fechado) { setAviso("A competência está fechada — reabra antes de excluir."); return; }
    const motivo = prompt(`Excluir ${r.nome} do Extrato de ${compLabel(r.competencia)}?\nOs dados ficam guardados no histórico. Informe o motivo:`);
    if (!motivo || !motivo.trim()) return;
    const quando = `${hojeISO()} ${horaAgora()}`;
    const substituidos = [{ extratoId: r.id, nome: r.nome, campos: ["excluido"], motivo: motivo.trim(), antes: semEventos(extratos.find((e) => e.id === r.id) || {}), eventosAntes: r.eventos }];
    const noBanco = (await guardarVersaoAnterior({ comp: r.competencia, versao: "exclusão", arquivo: "", substituidos, por: nomeUsuario })).ok;
    if (!noBanco) setConfig((c) => ({ ...c, folhaVersoes: { ...(c.folhaVersoes || {}), [r.competencia]: [...((c.folhaVersoes || {})[r.competencia] || []), { versao: "exclusão", quando, por: nomeUsuario, substituidos }] } }));
    try { const d = await supabase.from("extratos_mensais").delete().eq("id", r.id); if (d.error) throw d.error; setSelId(null); await carregarExtratos(); }
    catch { setAviso("Não consegui excluir agora."); }
  };

  const th = "px-3 py-2.5 font-semibold";
  return (
    <div className="space-y-4">
      <PageHeader titulo="Extrato Mensal" subtitulo="Dados oficiais da contabilidade — somente leitura. Correções entram por nova importação (versão revisada).">
        {podeImportar && <Btn size="sm" onClick={() => setImportarAberto(true)}><Upload size={14} /> Importar Extrato</Btn>}
        <Btn variant="secondary" size="sm" onClick={() => { recarregar && recarregar(); carregarExtratos(); }}><RefreshCw size={14} /> Atualizar</Btn>
        {compSel !== "Todas" && filtradas.length > 0 && <Btn variant="secondary" size="sm" onClick={imprimirCompetencia}><Printer size={14} /> Imprimir (PDF)</Btn>}
        <ExportButtons titulo={`Extrato Mensal ${compSel}`} headers={HEADERS_EXTRATO} rows={filtradas.map(linhaExtratoExport)} resumo={`${filtradas.length} registro(s) · Proventos ${brlC(soma.P)} · Descontos ${brlC(soma.D)} · Líquido ${brlC(soma.L)}`} />
      </PageHeader>
      {importarAberto && <ImportarExtratoModal empresaPermitida={empresaPermitida} funcionarios={funcionarios} config={config} setConfig={setConfig} nomeUsuario={nomeUsuario} onClose={() => setImportarAberto(false)} onImportado={() => { carregarExtratos(); recarregar && recarregar(); }} />}
      {erroCarga && <div className="flex items-start gap-2 rounded-md border border-destructive/40 bg-destructive/8 px-3 py-2.5 text-xs text-destructive"><AlertTriangle size={15} className="mt-0.5 shrink-0" /><span><strong>Não consegui carregar os extratos ({erroCarga}).</strong> O que aparece abaixo pode estar incompleto — clique em Atualizar.</span></div>}
      {aviso && <div className="rounded-md bg-warning/8 px-3 py-2 text-xs text-warning-ink">{aviso}</div>}

      {!carregando && visiveis.length === 0 ? (
        <Card className="p-10">
          <div className="mx-auto max-w-md text-center">
            <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-primary/8 text-primary"><Banknote size={26} /></div>
            <h3 className="text-base font-semibold text-foreground">Nenhum extrato importado ainda</h3>
            <p className="mt-1 text-sm text-muted-foreground">Importe o PDF "Extrato Mensal" da contabilidade. Cada pessoa aparece aqui com as verbas, as bases e o líquido — exatamente como no PDF.</p>
            {podeImportar && <Btn className="mt-5" onClick={() => setImportarAberto(true)}><Upload size={15} /> Importar Extrato</Btn>}
          </div>
        </Card>
      ) : (<>
        <Card className="sticky top-[4.5rem] z-20 p-3">
          <div className="flex flex-wrap items-end gap-3">
            <Field label="Competência"><select className={`${selCls} w-44`} value={compSel} onChange={(e) => setFComp(e.target.value)}><option value="Todas">Todas</option>{competencias.map((c) => <option key={c} value={c}>{compBonito(c)}</option>)}</select></Field>
            {!empresaPermitida && <Field label="Empresa"><select className={`${selCls} w-40`} value={fEmp} onChange={(e) => setFEmp(e.target.value)}><option>Todas</option>{empresas.map((x) => <option key={x}>{x}</option>)}</select></Field>}
            <Field label="Situação"><select className={`${selCls} w-36`} value={fSit} onChange={(e) => setFSit(e.target.value)}><option>Todas</option>{situacoes.map((x) => <option key={x}>{x}</option>)}</select></Field>
            <Field label="Tipo"><select className={`${selCls} w-36`} value={fTipo} onChange={(e) => setFTipo(e.target.value)}><option value="Todos">Todos</option>{Object.entries(TIPO_REGISTRO).map(([k, v]) => <option key={k} value={k}>{v.txt}</option>)}</select></Field>
            <div className="min-w-[14rem] flex-1"><Field label="Funcionário"><SearchInput valor={busca} onChange={setBusca} placeholder="Nome, cargo, matrícula ou CPF..." /></Field></div>
          </div>
        </Card>

        {ultimosPorCnpj.length > 0 && (
          <Card className="divide-y divide-border/60">
            {ultimosPorCnpj.map((lg) => {
              const s = somaDoCnpj(lg.cnpj);
              const bate = lg.totalGeral ? s.P === lg.totalGeral.proventos && s.D === lg.totalGeral.descontos && s.L === lg.totalGeral.liquido : null;
              return (
                <div key={lg.id} className="flex flex-wrap items-center gap-x-5 gap-y-1 px-4 py-2.5 text-xs text-foreground/70">
                  <span className="inline-flex items-center gap-1.5 font-semibold text-foreground/80"><FileText size={13} className="text-muted-foreground/80" /> {lg.arquivo || "arquivo"}</span>
                  {lg.empresaPdf && <span>{lg.empresaPdf}{lg.cnpj ? ` · ${lg.cnpj}` : ""}</span>}
                  <span>Competência <strong>{compLabel(compSel)}</strong></span>
                  {lg.emissao && <span>Emissão {dataBR(lg.emissao)}</span>}
                  <span>Versão <strong>{lg.versao}</strong></span>
                  <span>Importado em {lg.quando}{lg.por ? ` por ${lg.por}` : ""}</span>
                  {bate === true && <Badge cls="bg-success/8 text-success"><CheckCircle2 size={11} /> {s.n} registros somam o Total Geral do PDF ({brlC(lg.totalGeral.liquido)})</Badge>}
                  {bate === false && <Badge cls="bg-destructive/8 text-destructive"><AlertTriangle size={11} /> Soma gravada ({brlC(s.L)}) ≠ Total Geral do PDF ({brlC(lg.totalGeral.liquido)})</Badge>}
                  {lg.pdfPath && <button onClick={() => abrirPdf(lg.pdfPath)} className="ml-auto inline-flex items-center gap-1 font-medium text-primary hover:underline"><FileText size={12} /> PDF original</button>}
                </div>
              );
            })}
          </Card>
        )}

        <div className="grid grid-cols-2 gap-3 lg:grid-cols-5">
          <Kpi icon={Users} label="Registros" value={String(filtradas.length)} />
          <Kpi icon={TrendingUp} label="Proventos" value={brlC(soma.P)} tone="emerald" />
          <Kpi icon={TrendingDown} label="Descontos" value={brlC(soma.D)} tone="red" />
          <Kpi icon={Banknote} label="Líquido" value={brlC(soma.L)} tone="blue" />
          <Kpi icon={Home} label="FGTS (informativo)" value={brlC(soma.fgts)} />
        </div>
        {/* Rótulo curto no card e o detalhe aqui: no celular (e mesmo no computador) o rótulo longo era cortado. */}
        <p className="text-xs text-muted-foreground">{soma.porTipo.mensal.n} mensal · {soma.porTipo.rescisao.n} rescisão · {soma.porTipo.pro_labore.n} pró-labore. FGTS e bases são informativos: não entram no líquido nem no repasse.</p>
        {(alertas.naoFecha || alertas.verbasNaoBatem || alertas.semVerbas || alertas.desconhecidos) > 0 && (
          <div className="flex flex-wrap gap-2 text-xs">
            {alertas.naoFecha > 0 && <Badge cls="bg-destructive/8 text-destructive"><AlertTriangle size={11} /> {alertas.naoFecha} não fecham (proventos − descontos ≠ líquido)</Badge>}
            {alertas.verbasNaoBatem > 0 && <Badge cls="bg-destructive/8 text-destructive"><AlertTriangle size={11} /> {alertas.verbasNaoBatem} com verbas que não somam os totais</Badge>}
            {alertas.semVerbas > 0 && <Badge cls="bg-warning/8 text-warning-ink"><AlertTriangle size={11} /> {alertas.semVerbas} sem verbas lidas</Badge>}
            {alertas.desconhecidos > 0 && <Badge cls="bg-warning/8 text-warning-ink"><AlertTriangle size={11} /> {alertas.desconhecidos} com código sem significado cadastrado</Badge>}
          </div>
        )}

        <Card className="overflow-hidden">
          <div className="max-h-[62vh] overflow-auto">
            <table className="w-full min-w-[1000px] text-sm">
              <thead className="sticky top-0 z-10 bg-[color-mix(in_oklab,var(--color-primary)_8%,var(--color-card))] text-left text-[11px] uppercase tracking-wide text-primary/70">
                <tr><th className={th}>Matr.</th><th className={th}>Funcionário</th><th className={th}>Tipo</th><th className={th}>Situação</th><th className={th}>Admissão</th>
                  {compSel === "Todas" && <th className={th}>Comp.</th>}
                  <th className={`${th} text-right`}>Salário</th><th className={`${th} text-right`}>Proventos</th><th className={`${th} text-right`}>Descontos</th><th className={`${th} text-right`}>Líquido</th><th className={`${th} text-center`}>Pág.</th><th className={th}></th></tr>
              </thead>
              <tbody className="divide-y divide-border/60">
                {filtradas.map((r) => (
                  <tr key={r.id} onClick={() => setSelId(r.id)} className={`cursor-pointer hover:bg-primary/5 ${selId === r.id ? "bg-primary/5" : ""}`}>
                    <td className="px-3 py-2 tabular-nums text-muted-foreground">{r.matricula || "—"}</td>
                    <td className="px-3 py-2"><span className="font-medium text-foreground">{r.nome}</span><span className="block text-xs text-muted-foreground/80">{r.cargo || "—"}{r.empresa ? ` · ${r.empresa}` : ""}</span></td>
                    <td className="px-3 py-2"><Badge cls={TIPO_REGISTRO[r.tipo].cls}>{TIPO_REGISTRO[r.tipo].txt}</Badge></td>
                    <td className="px-3 py-2 text-foreground/70">{r.situacao || "—"}</td>
                    <td className="px-3 py-2 tabular-nums text-muted-foreground">{dataBR(r.admissao)}</td>
                    {compSel === "Todas" && <td className="px-3 py-2 text-muted-foreground">{compLabel(r.competencia)}</td>}
                    <td className="px-3 py-2 text-right tabular-nums text-foreground/70">{fmtBRL(r.salario_base)}</td>
                    <td className="px-3 py-2 text-right tabular-nums text-success">{brlC(r.P)}</td>
                    <td className="px-3 py-2 text-right tabular-nums text-destructive">{brlC(r.D)}</td>
                    <td className="px-3 py-2 text-right font-semibold tabular-nums text-foreground">{brlC(r.L)}</td>
                    <td className="px-3 py-2 text-center tabular-nums text-muted-foreground/80">{r.pagina || "—"}</td>
                    <td className="px-3 py-2">
                      <span className="flex flex-wrap justify-end gap-1">
                        {!r.fecha && <Badge cls="bg-destructive/8 text-destructive">não fecha</Badge>}
                        {r.semVerbas && <Badge cls="bg-warning/8 text-warning-ink">sem verbas</Badge>}
                        {r.naoReconhecidos.length > 0 && <Badge cls="bg-warning/8 text-warning-ink">código novo</Badge>}
                        <ChevronRight size={15} className="text-muted-foreground/50" />
                      </span>
                    </td>
                  </tr>
                ))}
                {filtradas.length === 0 && <tr><td colSpan={12} className="px-3 py-10 text-center text-sm text-muted-foreground/80">{carregando ? "Carregando..." : "Nenhum registro com esses filtros."}</td></tr>}
              </tbody>
              {filtradas.length > 0 && (
                <tfoot className="sticky bottom-0 bg-secondary text-sm font-semibold text-foreground/80">
                  <tr><td className="px-3 py-2.5" colSpan={compSel === "Todas" ? 7 : 6}>Total do filtro — {filtradas.length} registro(s){semFiltroExtra && compSel !== "Todas" ? "" : " (filtrado)"}</td>
                    <td className="px-3 py-2.5 text-right tabular-nums text-success">{brlC(soma.P)}</td><td className="px-3 py-2.5 text-right tabular-nums text-destructive">{brlC(soma.D)}</td><td className="px-3 py-2.5 text-right tabular-nums">{brlC(soma.L)}</td><td colSpan={2}></td></tr>
                </tfoot>
              )}
            </table>
          </div>
        </Card>
      </>)}

      {mapear && <SignificadoEventoModal ev={mapear.ev} layout={mapear.layout} nomeUsuario={nomeUsuario} onClose={() => setMapear(null)}
        onSalvar={(papel) => { setConfig((c) => ({ ...c, folhaMapaEventos: { ...(c.folhaMapaEventos || {}), [mapear.layout]: { ...((c.folhaMapaEventos || {})[mapear.layout] || {}), [String(mapear.ev.codigo)]: { papel, por: nomeUsuario, em: `${hojeISO()} ${horaAgora()}` } } } })); setMapear(null); }} />}
      {sel && (
        <PainelLateral titulo={sel.nome} subtitulo={`${sel.cargo || "—"} · ${sel.empresa || "—"} · ${compBonito(sel.competencia)}`} onClose={() => setSelId(null)}
          acoes={<>
            <Btn size="sm" onClick={() => abrirNoRepasse(sel)}><Banknote size={14} /> Abrir na Folha de Repasse</Btn>
            {sel.pdfPath && <Btn size="sm" variant="secondary" onClick={() => abrirPdf(sel.pdfPath, sel.pagina)}><FileText size={14} /> PDF original{sel.pagina ? ` (pág. ${sel.pagina})` : ""}</Btn>}
            <Btn size="sm" variant="secondary" onClick={() => abrirImprimirHTML(holeriteHTML(paraHolerite(sel)), `extrato_${(sel.nome || "").replace(/\s+/g, "_")}_${sel.competencia}.html`)}><Printer size={14} /> Imprimir</Btn>
            <Btn size="sm" variant="secondary" onClick={() => exportarExcel(sel)}><FileDown size={14} /> Excel</Btn>
            {admin && sel.fonte === "extrato" && <Btn size="sm" variant="danger" onClick={() => excluirExtrato(sel)}><Trash2 size={14} /> Excluir</Btn>}
          </>}>
          <DetalheExtrato r={sel} historico={historico} versoes={versoesDe(sel)} onSelHist={setSelId} onDarSignificado={permFolha(perfil, admin).conferir && !config?.folhaFechamentos?.[sel.competencia]?.fechado ? (ev) => setMapear({ ev, layout: sel.layout || "extrato-mensal" }) : null} />
        </PainelLateral>
      )}
    </div>
  );
}

// ── Peças da tela Extrato Mensal (e reaproveitadas pela Folha de Repasse) ──
const TIPO_REGISTRO = {
  mensal: { txt: "Mensal", cls: "bg-secondary text-foreground/70" },
  rescisao: { txt: "Rescisão", cls: "bg-destructive/8 text-destructive" },
  pro_labore: { txt: "Pró-labore", cls: "bg-violet-50 dark:bg-violet-500/15 text-violet-700 dark:text-violet-300" },
};
const SIT_IMPORT_EXTRATO = {
  novo: { txt: "Novo", cls: "bg-primary/8 text-primary" },
  revisado: { txt: "Revisado", cls: "bg-warning/8 text-warning-ink" },
  igual: { txt: "Sem mudança", cls: "bg-secondary text-muted-foreground" },
  semchave: { txt: "Sem CPF/matrícula — fica de fora", cls: "bg-destructive/8 text-destructive" },
  duplicado: { txt: "Duplicado no arquivo", cls: "bg-destructive/8 text-destructive" },
  conflito: { txt: "CPF gravado por outra empresa", cls: "bg-destructive/8 text-destructive" },
};
const HEADERS_EXTRATO = ["Competencia", "Matricula", "Nome", "Empresa", "CNPJ", "Tipo", "Situacao", "Vinculo", "Admissao", "Cargo", "Salario", "Proventos", "Descontos", "Liquido", "FGTS (informativo)", "Pagina", "Versao"];
const linhaExtratoExport = (r) => [r.competencia, r.matricula || "", r.nome, r.empresa || "", r.cnpj || "", TIPO_REGISTRO[r.tipo].txt, r.situacao || "", r.vinculo || "", dataBR(r.admissao), r.cargo || "", num(r.salario_base), r.P / 100, r.D / 100, r.L / 100, num(r.valor_fgts), r.pagina || "", r.versao || ""];
// Centavos → texto em reais. null/undefined = "—" (ausência não é zero).
const brlC = (c) => (c === null || c === undefined ? "—" : fmtBRL(c / 100));
// Data de calendário AAAA-MM-DD → DD/MM/AAAA sem passar por Date (sem risco de fuso virar o dia).
const dataBR = (iso) => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || "")); return m ? `${m[3]}/${m[2]}/${m[1]}` : "—"; };
// CPF só com o miolo visível — o suficiente para conferir, sem expor o documento inteiro na tela.
const cpfMascarado = (cpf) => { const d = soDigitos(cpf); return d.length === 11 ? `***.${d.slice(3, 6)}.${d.slice(6, 9)}-**` : (d ? "***" : "—"); };
const semEventos = (o) => { const { eventos, mapa, ...resto } = o || {}; return resto; };
// Colunas da migração 0010 (opcionais): se o banco ainda não tem, grava sem elas e avisa.
const COLS_EXTRATO_0010 = ["matricula", "pagina", "layout", "arquivo", "arquivo_hash", "emissao", "versao"];
const COLS_EVENTO_0010 = ["referencia_texto", "pagina"];
const tirarColunas = (obj, cols) => { const o = { ...obj }; cols.forEach((c) => delete o[c]); return o; };
const erroDeColuna = (e) => /column|coluna|schema cache/i.test(String(e?.message || e || ""));
async function gravarComFallback(fn, payload, cols) {
  let r = await fn(payload);
  if (r.error && erroDeColuna(r.error)) {
    r = await fn(Array.isArray(payload) ? payload.map((p) => tirarColunas(p, cols)) : tirarColunas(payload, cols));
    r.semColunasNovas = true;
  }
  return r;
}
async function sha256Arquivo(file) {
  try {
    const h = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());
    return [...new Uint8Array(h)].map((b) => b.toString(16).padStart(2, "0")).join("");
  } catch (_) { return ""; }
}
// A versão anterior vai para folha_importacoes (auditoria). Se a tabela não existir, quem chama
// guarda na config — a revisão nunca acontece sem a versão anterior guardada em algum lugar.
async function guardarVersaoAnterior({ comp, versao, arquivo, substituidos, por }) {
  try {
    const r = await supabase.from("folha_importacoes").insert({ competencia: comp, arquivo, status: "Versão anterior", importado_por: por, qtd_funcionarios: substituidos.length, avisos: { tipo: "versao_anterior", versao, substituidos } }).select("id");
    return { ok: !r.error, id: (r.data && r.data[0] && r.data[0].id) || null };
  } catch (_) { return { ok: false, id: null }; }
}
// Troca UM extrato pela versão revisada, com desfazer manual (o cliente não tem transação):
// atualiza a linha → insere as verbas novas → apaga as velhas pelo id. Se um passo falha, volta
// ao estado anterior e devolve o motivo.
async function revisarExtrato({ antes, novaLinha, novosEventos }) {
  let semColunasNovas = false;
  // Volta a linha para a versão anterior. Se nem isso der certo, a mensagem manda conferir à mão.
  const restaurar = async () => { try { const r = await supabase.from("extratos_mensais").update(tirarColunas(semEventos(antes), ["id"])).eq("id", antes.id); return !r.error; } catch (_) { return false; } };
  const falhou = async (erro, verbasLimpas = true) => {
    const voltou = await restaurar();
    const aviso = !verbasLimpas ? "ATENÇÃO: as verbas novas e as antigas podem ter ficado juntas — confira este registro no Extrato Mensal"
      : !voltou ? "ATENÇÃO: não consegui voltar à versão anterior — confira este registro no Extrato Mensal" : "mantida a versão anterior";
    return { ok: false, semColunasNovas, erro: `${erro} — ${aviso}` };
  };
  const up = await gravarComFallback((p) => supabase.from("extratos_mensais").update(p).eq("id", antes.id), novaLinha, COLS_EXTRATO_0010);
  if (up.semColunasNovas) semColunasNovas = true;
  if (up.error) return { ok: false, erro: `${up.error.message} — mantida a versão anterior`, semColunasNovas };
  if (novosEventos === null) return { ok: true, semColunasNovas };   // arquivo sem verbas: as gravadas continuam
  let idsNovos = [];
  if (novosEventos.length) {
    const ins = await gravarComFallback((p) => supabase.from("folha_eventos").insert(p).select("id"), novosEventos, COLS_EVENTO_0010);
    if (ins.semColunasNovas) semColunasNovas = true;
    if (ins.error) return falhou(`verbas não gravadas (${ins.error.message})`);
    idsNovos = (ins.data || []).map((x) => x.id);
  }
  const idsVelhos = (antes.eventos || []).map((e) => e.id).filter(Boolean);
  if (idsVelhos.length) {
    const del = await supabase.from("folha_eventos").delete().in("id", idsVelhos);
    if (del.error) {
      let limpou = true;
      if (idsNovos.length) { try { const d2 = await supabase.from("folha_eventos").delete().in("id", idsNovos); limpou = !d2.error; } catch (_) { limpou = false; } }
      return falhou("não consegui trocar as verbas", limpou);
    }
  }
  return { ok: true, semColunasNovas };
}
// Um registro da folha já com classificação (mensal/rescisão/pró-labore) e as conferências prontas.
function normalizarRegistroFolha(x) {
  const eventos = x.eventos || [];
  const cls = FR.classificarRegistro(x, eventos, x.mapa);
  const P = FR.centavos(x.proventos), D = FR.centavos(x.descontos), L = FR.centavos(x.liquido);
  const somaP = FR.somaCentavos(eventos.filter((e) => e.tipo === "provento"), (e) => FR.centavos(e.valor));
  const somaD = FR.somaCentavos(eventos.filter((e) => e.tipo === "desconto"), (e) => FR.centavos(e.valor));
  return {
    ...x, eventos, cls, tipo: cls.tipo, P, D, L, pdfPath: x.pdf_url || "",
    fecha: P - D === L, verbasBatem: !eventos.length || (somaP === P && somaD === D),
    semVerbas: x.fonte === "extrato" && !eventos.length, naoReconhecidos: FR.eventosNaoReconhecidos(eventos, x.mapa),
  };
}
// Dar significado a um código de evento que a contabilidade passou a usar. Vale para o LAYOUT (todos
// os funcionários lidos por aquele formato) e fica registrado quem definiu — é o mesmo mecanismo do 871.
function SignificadoEventoModal({ ev, layout, nomeUsuario = "", onClose, onSalvar }) {
  const [papel, setPapel] = useState("outro_desconto");
  useEffect(() => { setPapel(ev?.tipo === "provento" ? "outro_provento" : "outro_desconto"); }, [ev]);
  return (
    <Modal title={`Significado do evento ${ev?.codigo}`} subtitle={`${ev?.descricao || ""} · ${FR.LAYOUTS[layout] || layout}`} onClose={onClose} max="max-w-lg"
      footer={<><Btn variant="secondary" onClick={onClose}>Cancelar</Btn><Btn onClick={() => onSalvar(papel)}><Save size={15} /> Salvar significado</Btn></>}>
      <div className="space-y-3">
        <p className="text-sm text-foreground/70">O que este evento é, para o sistema conferir direito? Vale para todos os funcionários lidos no formato <strong>{FR.LAYOUTS[layout] || layout}</strong>.</p>
        <Field label="Significado"><select className={inputCls} value={papel} onChange={(e) => setPapel(e.target.value)}>{Object.entries(FR.PAPEIS).map(([k, v]) => <option key={k} value={k}>{v}</option>)}</select></Field>
        <p className="text-xs text-muted-foreground/80">O valor do evento não muda — isto só diz ao sistema como tratá-lo nas conferências (adiantamento, falta, VT/VR, rescisão…). Fica registrado que foi {nomeUsuario} quem definiu.</p>
      </div>
    </Modal>
  );
}
// Painel lateral largo (detalhe sem sair da lista). Fica ABAIXO dos modais (z-40 × z-50).
function PainelLateral({ titulo, subtitulo, onClose, acoes, children }) {
  useEffect(() => { const h = (e) => e.key === "Escape" && onClose(); window.addEventListener("keydown", h); return () => window.removeEventListener("keydown", h); }, [onClose]);
  return (
    <div className="fixed inset-0 z-40 flex justify-end" style={{ backgroundColor: "rgba(15,23,42,0.35)" }} onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <aside className="flex h-full w-full max-w-4xl flex-col bg-card shadow-2xl">
        <div className="flex items-start justify-between gap-3 border-b border-primary/20 bg-primary/5 px-5 py-4">
          <div className="min-w-0"><h2 className="truncate text-lg font-bold text-foreground">{titulo}</h2>{subtitulo && <p className="truncate text-sm text-muted-foreground">{subtitulo}</p>}</div>
          <button onClick={onClose} className="rounded-md p-1.5 text-muted-foreground/80 hover:bg-card" title="Fechar (Esc)"><X size={18} /></button>
        </div>
        {acoes && <div className="flex flex-wrap gap-2 border-b border-border/60 px-5 py-2.5">{acoes}</div>}
        <div className="flex-1 overflow-y-auto px-5 py-4">{children}</div>
      </aside>
    </div>
  );
}
